/**
 * Câu ví dụ cho bộ Mimikara N2 — tra theo số thứ tự (no) của thẻ trong data.js.
 * Từ đang học được đánh dấu bằng **...** trong câu tiếng Nhật.
 */
tangoRegister('n2', 'examples', {
  "1": [{"jp":"**人生**は一度きりだから、後悔したくない。","vi":"Đời người chỉ có một lần nên tôi không muốn hối tiếc."},{"jp":"その出会いが私の**人生**を変えた。","vi":"Cuộc gặp gỡ đó đã thay đổi cuộc đời tôi."}],
  "2": [{"jp":"**人間**は一人では生きていけない。","vi":"Con người không thể sống một mình."},{"jp":"失敗するのは**人間**なら当然のことだ。","vi":"Đã là con người thì thất bại là chuyện đương nhiên."}],
  "3": [{"jp":"駅前にはたくさんの**人**が集まっていた。","vi":"Có rất nhiều người tụ tập trước nhà ga."},{"jp":"あの**人**は誰ですか。","vi":"Người kia là ai vậy?"}],
  "4": [{"jp":"お盆には**祖先**の墓参りをします。","vi":"Vào dịp Obon, chúng tôi đi viếng mộ tổ tiên."},{"jp":"人類の**祖先**はアフリカで生まれたと言われる。","vi":"Người ta nói tổ tiên loài người ra đời ở châu Phi."}],
  "5": [{"jp":"正月には**親戚**が集まります。","vi":"Vào dịp Tết, họ hàng tụ họp lại."},{"jp":"彼とは遠い**親戚**に当たる。","vi":"Tôi với anh ấy là họ hàng xa."}],
  "6": [{"jp":"あの**夫婦**はとても仲がいい。","vi":"Cặp vợ chồng đó rất hòa thuận."},{"jp":"**夫婦**で協力して店を経営している。","vi":"Hai vợ chồng cùng nhau kinh doanh cửa hàng."}],
  "7": [{"jp":"彼は農家の**長男**として生まれた。","vi":"Anh ấy sinh ra là con trai trưởng của một gia đình nông dân."},{"jp":"**長男**が今年大学に入学しました。","vi":"Con trai cả của tôi năm nay đã vào đại học."}],
  "8": [{"jp":"**主人**は今、出張中です。","vi":"Chồng tôi hiện đang đi công tác."},{"jp":"この店の**主人**はとても親切だ。","vi":"Ông chủ tiệm này rất tốt bụng."},{"jp":"うちの**主人**は料理が得意なんです。","vi":"Chồng tôi nấu ăn giỏi lắm."}],
  "9": [{"jp":"あの二人は**双子**なので顔がそっくりだ。","vi":"Hai người đó là sinh đôi nên mặt giống hệt nhau."},{"jp":"姉は**双子**の男の子を出産した。","vi":"Chị tôi đã sinh một cặp bé trai sinh đôi."}],
  "10": [{"jp":"デパートで**迷子**の子供を見つけた。","vi":"Tôi tìm thấy một đứa trẻ bị lạc ở trung tâm thương mại."},{"jp":"人が多い所では**迷子**にならないように気をつけて。","vi":"Ở chỗ đông người thì cẩn thận kẻo bị lạc nhé."}],
  "11": [{"jp":"**他人**の物を勝手に使ってはいけない。","vi":"Không được tự tiện dùng đồ của người khác."},{"jp":"**他人**の意見にも耳を傾けるべきだ。","vi":"Nên lắng nghe cả ý kiến của người khác."}],
  "12": [{"jp":"彼は**敵**が多い人だ。","vi":"Anh ta là người có nhiều kẻ thù."},{"jp":"昨日の**敵**は今日の友。","vi":"Kẻ thù hôm qua là bạn hôm nay."}],
  "13": [{"jp":"私はいつでもあなたの**味方**です。","vi":"Tôi luôn đứng về phía bạn."},{"jp":"彼を**味方**にすれば心強い。","vi":"Nếu kéo được anh ấy về phe mình thì yên tâm lắm."}],
  "14": [{"jp":"この文章で**筆者**が言いたいことは何か。","vi":"Điều tác giả muốn nói trong đoạn văn này là gì?"},{"jp":"**筆者**の意見に賛成だ。","vi":"Tôi đồng ý với ý kiến của tác giả."}],
  "15": [{"jp":"日本人の平均**寿命**は年々延びている。","vi":"Tuổi thọ trung bình của người Nhật tăng lên qua từng năm."},{"jp":"この電池の**寿命**は約2年です。","vi":"Tuổi thọ của cục pin này khoảng 2 năm."}],
  "16": [{"jp":"**将来**は医者になりたいです。","vi":"Sau này tôi muốn trở thành bác sĩ."},{"jp":"**将来**のことをよく考えなさい。","vi":"Hãy suy nghĩ kỹ về tương lai."}],
  "17": [{"jp":"彼女には音楽の**才能**がある。","vi":"Cô ấy có tài năng âm nhạc."},{"jp":"子供の**才能**を伸ばしてあげたい。","vi":"Tôi muốn phát triển tài năng của con."}],
  "18": [{"jp":"この仕事には高い語学**能力**が必要だ。","vi":"Công việc này cần năng lực ngoại ngữ cao."},{"jp":"彼は**能力**を十分に発揮した。","vi":"Anh ấy đã phát huy hết năng lực của mình."}],
  "19": [{"jp":"あなたの**長所**は何ですか。","vi":"Điểm mạnh của bạn là gì?"},{"jp":"明るいところが彼女の**長所**だ。","vi":"Sự vui vẻ là ưu điểm của cô ấy."}],
  "20": [{"jp":"彼の服装は**個性**的だ。","vi":"Cách ăn mặc của anh ấy rất cá tính."},{"jp":"子供の**個性**を大切にしたい。","vi":"Tôi muốn trân trọng cá tính của con trẻ."}],
  "21": [{"jp":"背の高さは**遺伝**することが多い。","vi":"Chiều cao thường được di truyền."},{"jp":"この病気は**遺伝**とは関係がない。","vi":"Căn bệnh này không liên quan đến di truyền."}],
  "22": [{"jp":"祖父は**動作**がゆっくりになった。","vi":"Ông tôi đã cử động chậm chạp hơn."},{"jp":"先生の**動作**をよく見てまねしてください。","vi":"Hãy nhìn kỹ động tác của thầy rồi bắt chước theo."}],
  "23": [{"jp":"子供は親の**真似**をするものだ。","vi":"Trẻ con thường hay bắt chước cha mẹ."},{"jp":"人の答えを**真似**してはいけない。","vi":"Không được chép câu trả lời của người khác."}],
  "24": [{"jp":"健康のために**睡眠**を十分にとりましょう。","vi":"Hãy ngủ đủ giấc để giữ sức khỏe."},{"jp":"最近、**睡眠**不足で頭が痛い。","vi":"Dạo này tôi thiếu ngủ nên bị đau đầu."}],
  "25": [{"jp":"風邪で**食欲**がありません。","vi":"Tôi bị cảm nên chẳng thấy thèm ăn."},{"jp":"秋は**食欲**の秋と言われる。","vi":"Mùa thu được gọi là mùa ăn ngon."}],
  "26": [{"jp":"一人暮らしなので**外食**が多い。","vi":"Vì sống một mình nên tôi hay ăn ngoài."},{"jp":"節約のために**外食**を減らした。","vi":"Tôi đã giảm ăn ngoài để tiết kiệm."}],
  "27": [{"jp":"夫と**家事**を分担しています。","vi":"Tôi chia sẻ việc nhà với chồng."},{"jp":"仕事と**家事**の両立は大変だ。","vi":"Cân bằng giữa công việc và việc nhà thật vất vả."}],
  "28": [{"jp":"姉は先月、無事に**出産**した。","vi":"Tháng trước chị tôi đã sinh nở bình an."},{"jp":"**出産**のために会社を休んでいます。","vi":"Tôi đang nghỉ làm để sinh con."}],
  "29": [{"jp":"母は祖母の**介護**をしている。","vi":"Mẹ tôi đang chăm sóc bà."},{"jp":"**介護**の仕事は体力が必要だ。","vi":"Công việc chăm sóc người già cần có thể lực."},{"jp":"親の**介護**のために会社を辞めた。","vi":"Tôi đã nghỉ việc để chăm sóc bố mẹ."}],
  "30": [{"jp":"うちは**共働き**なので、子供を保育園に預けている。","vi":"Nhà tôi cả hai vợ chồng đều đi làm nên gửi con ở nhà trẻ."},{"jp":"最近は**共働き**の家庭が増えている。","vi":"Gần đây số gia đình có cả vợ lẫn chồng đi làm đang tăng lên."}],
  "31": [{"jp":"毎朝8時に**出勤**します。","vi":"Mỗi sáng tôi đi làm lúc 8 giờ."},{"jp":"土曜日も**出勤**しなければならない。","vi":"Thứ bảy tôi cũng phải đi làm."}],
  "32": [{"jp":"彼は若くして**出世**した。","vi":"Anh ấy đã thăng tiến khi còn trẻ."},{"jp":"**出世**よりも家族との時間が大切だ。","vi":"Thời gian bên gia đình quan trọng hơn chuyện thăng tiến."}],
  "33": [{"jp":"彼は会社で高い**地位**についている。","vi":"Anh ấy giữ một vị trí cao trong công ty."},{"jp":"女性の社会的**地位**が向上した。","vi":"Địa vị xã hội của phụ nữ đã được nâng cao."}],
  "34": [{"jp":"来年、大学を**受験**するつもりです。","vi":"Năm sau tôi định thi vào đại học."},{"jp":"息子は今、**受験**勉強で忙しい。","vi":"Con trai tôi bây giờ đang bận ôn thi."}],
  "35": [{"jp":"大学での**専攻**は経済学です。","vi":"Chuyên ngành của tôi ở đại học là kinh tế học."},{"jp":"彼女は日本文学を**専攻**している。","vi":"Cô ấy đang học chuyên ngành văn học Nhật Bản."}],
  "36": [{"jp":"早く出かける**支度**をしなさい。","vi":"Mau chuẩn bị đi ra ngoài đi."},{"jp":"母は台所で夕食の**支度**をしている。","vi":"Mẹ đang chuẩn bị bữa tối trong bếp."}],
  "37": [{"jp":"運動しすぎて**全身**が痛い。","vi":"Tập thể dục quá sức nên tôi đau khắp người."},{"jp":"鏡で**全身**をチェックしてから出かけた。","vi":"Tôi soi gương kiểm tra toàn thân rồi mới ra ngoài."}],
  "38": [{"jp":"祖母の顔には**しわ**がたくさんある。","vi":"Trên mặt bà tôi có nhiều nếp nhăn."},{"jp":"シャツの**しわ**をアイロンで伸ばした。","vi":"Tôi đã dùng bàn là ủi phẳng nếp nhăn của áo sơ mi."}],
  "39": [{"jp":"面接にはきちんとした**服装**で行きましょう。","vi":"Hãy mặc trang phục chỉnh tề khi đi phỏng vấn."},{"jp":"この会社は**服装**が自由だ。","vi":"Công ty này cho mặc tự do."}],
  "40": [{"jp":"手伝ってくれた友達にお**礼**を言った。","vi":"Tôi đã nói lời cảm ơn người bạn đã giúp mình."},{"jp":"先生に**礼**をしてから教室を出た。","vi":"Tôi cúi chào thầy rồi ra khỏi lớp."},{"jp":"お世話になったお**礼**に、お菓子を贈った。","vi":"Tôi tặng bánh kẹo để cảm ơn vì đã được giúp đỡ."}],
  "41": [{"jp":"彼はお**世辞**が上手だ。","vi":"Anh ta rất giỏi nịnh."},{"jp":"お**世辞**でも褒められるとうれしい。","vi":"Dù chỉ là lời khen xã giao, được khen vẫn thấy vui."}],
  "42": [{"jp":"遅刻の**言い訳**はもう聞きたくない。","vi":"Tôi không muốn nghe lý do biện minh cho việc đi muộn nữa."},{"jp":"失敗しても**言い訳**をしないでください。","vi":"Dù thất bại cũng đừng viện cớ."}],
  "43": [{"jp":"最近、その映画が**話題**になっている。","vi":"Dạo này bộ phim đó đang được bàn tán nhiều."},{"jp":"彼は急に**話題**を変えた。","vi":"Anh ấy đột nhiên đổi chủ đề."}],
  "44": [{"jp":"これは二人だけの**秘密**だよ。","vi":"Đây là bí mật của riêng hai chúng ta nhé."},{"jp":"彼は**秘密**を守れる人だ。","vi":"Anh ấy là người biết giữ bí mật."}],
  "45": [{"jp":"私は父を心から**尊敬**しています。","vi":"Tôi kính trọng cha từ tận đáy lòng."},{"jp":"**尊敬**する人は誰ですか。","vi":"Người bạn kính trọng là ai?"}],
  "46": [{"jp":"彼は成功しても**謙そん**な態度を忘れない。","vi":"Dù thành công, anh ấy vẫn không quên thái độ khiêm tốn."},{"jp":"「まだまだです」と彼女は**謙そん**して言った。","vi":"Cô ấy khiêm tốn nói: \"Tôi vẫn còn kém lắm\"."}],
  "47": [{"jp":"皆さんの**期待**に応えられるよう頑張ります。","vi":"Tôi sẽ cố gắng để đáp lại sự kỳ vọng của mọi người."},{"jp":"新しい映画にはあまり**期待**していない。","vi":"Tôi không mong chờ lắm vào bộ phim mới."}],
  "48": [{"jp":"両親は**苦労**して私を育ててくれた。","vi":"Bố mẹ đã vất vả nuôi nấng tôi."},{"jp":"若い時の**苦労**は買ってでもせよ。","vi":"Lúc còn trẻ, gian khổ có phải mua cũng nên mua."}],
  "49": [{"jp":"彼は**意志**が強い人だ。","vi":"Anh ấy là người có ý chí mạnh mẽ."},{"jp":"本人の**意志**を尊重すべきだ。","vi":"Nên tôn trọng ý chí của chính người đó."}],
  "50": [{"jp":"彼女はすぐ**感情**が顔に出る。","vi":"Cảm xúc của cô ấy lập tức hiện lên mặt."},{"jp":"**感情**的にならずに話し合おう。","vi":"Hãy nói chuyện với nhau mà đừng để cảm xúc chi phối."}],
  "51": [{"jp":"カレーの**材料**を買いに行きます。","vi":"Tôi đi mua nguyên liệu nấu cà ri."},{"jp":"この家具は天然の**材料**で作られている。","vi":"Đồ nội thất này được làm từ vật liệu tự nhiên."}],
  "52": [{"jp":"道に落ちていた**石**につまずいた。","vi":"Tôi vấp phải hòn đá trên đường."},{"jp":"川に**石**を投げてはいけない。","vi":"Không được ném đá xuống sông."}],
  "53": [{"jp":"古新聞を**ひも**で縛った。","vi":"Tôi buộc báo cũ lại bằng dây."},{"jp":"靴の**ひも**がほどけていますよ。","vi":"Dây giày của bạn bị tuột kìa."}],
  "54": [{"jp":"コンサートの**券**を2枚買った。","vi":"Tôi đã mua 2 vé xem hòa nhạc."},{"jp":"食堂では先に食**券**を買ってください。","vi":"Ở nhà ăn, hãy mua phiếu ăn trước."}],
  "55": [{"jp":"参加者の**名簿**を作ってください。","vi":"Hãy lập danh sách người tham gia."},{"jp":"クラスの**名簿**に私の名前がない。","vi":"Trong danh sách lớp không có tên tôi."}],
  "56": [{"jp":"結果を**表**にまとめた。","vi":"Tôi đã tổng hợp kết quả thành bảng."},{"jp":"この**表**を見ると、売り上げの変化がわかる。","vi":"Nhìn bảng này sẽ thấy được sự thay đổi doanh thu."}],
  "57": [{"jp":"**針**に糸を通すのが難しい。","vi":"Xâu chỉ qua kim thật khó."},{"jp":"時計の**針**が12時を指している。","vi":"Kim đồng hồ đang chỉ 12 giờ."}],
  "58": [{"jp":"ワインの**栓**を抜いてください。","vi":"Hãy mở nút chai rượu vang ra."},{"jp":"お風呂の**栓**をするのを忘れた。","vi":"Tôi quên đậy nút bồn tắm."}],
  "59": [{"jp":"やかんから**湯気**が出ている。","vi":"Hơi nước đang bốc ra từ ấm."},{"jp":"**湯気**の立つスープがおいしそうだ。","vi":"Bát súp bốc hơi nghi ngút trông thật ngon."}],
  "60": [{"jp":"この部屋は**日当たり**がいい。","vi":"Căn phòng này đón nắng tốt."},{"jp":"**日当たり**の悪い場所では花が育たない。","vi":"Hoa không mọc được ở chỗ thiếu nắng."}],
  "61": [{"jp":"**空**の箱を捨ててください。","vi":"Hãy vứt cái hộp rỗng đi."},{"jp":"**空**になった瓶を洗って、リサイクルに出した。","vi":"Tôi rửa những cái chai đã rỗng rồi đem đi tái chế."},{"jp":"引き出しを開けたら、中は**空**だった。","vi":"Mở ngăn kéo ra thì bên trong trống không."}],
  "62": [{"jp":"絵が**斜め**になっていますよ。","vi":"Bức tranh đang bị nghiêng đấy."},{"jp":"道を**斜め**に横切るのは危ない。","vi":"Băng chéo qua đường rất nguy hiểm."},{"jp":"ネクタイが少し**斜め**に曲がっている。","vi":"Cà vạt hơi bị lệch."}],
  "63": [{"jp":"面接に**履歴**書を持って行った。","vi":"Tôi mang sơ yếu lý lịch đến buổi phỏng vấn."},{"jp":"ブラウザの**履歴**を削除した。","vi":"Tôi đã xóa lịch sử trình duyệt."}],
  "64": [{"jp":"この町には**娯楽**施設が少ない。","vi":"Thị trấn này ít cơ sở vui chơi giải trí."},{"jp":"昔はラジオが一番の**娯楽**だった。","vi":"Ngày xưa, radio là thú giải trí hàng đầu."}],
  "65": [{"jp":"友人の結婚式で**司会**を務めた。","vi":"Tôi đã làm MC trong đám cưới của bạn."},{"jp":"会議の**司会**は田中さんにお願いします。","vi":"Xin nhờ anh Tanaka chủ trì cuộc họp."}],
  "66": [{"jp":"新入社員の**歓迎**会を開いた。","vi":"Chúng tôi đã tổ chức tiệc chào đón nhân viên mới."},{"jp":"村の人たちに温かく**歓迎**された。","vi":"Tôi được người dân trong làng chào đón nồng hậu."}],
  "67": [{"jp":"切符は駅の**窓口**で買えます。","vi":"Có thể mua vé ở quầy bán vé của nhà ga."},{"jp":"3番の**窓口**へお越しください。","vi":"Xin mời đến quầy số 3."}],
  "68": [{"jp":"市役所で引っ越しの**手続き**をした。","vi":"Tôi đã làm thủ tục chuyển nhà ở tòa thị chính."},{"jp":"ビザの**手続き**に時間がかかる。","vi":"Thủ tục visa mất nhiều thời gian."}],
  "69": [{"jp":"駅から**徒歩**10分です。","vi":"Từ nhà ga đi bộ mất 10 phút."},{"jp":"**徒歩**で通勤している。","vi":"Tôi đi bộ đi làm."}],
  "70": [{"jp":"ここに**駐車**しないでください。","vi":"Xin đừng đỗ xe ở đây."},{"jp":"**駐車**場が見つからなくて困った。","vi":"Tôi gặp khó khăn vì không tìm được bãi đỗ xe."}],
  "71": [{"jp":"スピード**違反**で罰金を払った。","vi":"Tôi đã nộp phạt vì vi phạm tốc độ."},{"jp":"それは法律に**違反**する行為だ。","vi":"Đó là hành vi vi phạm pháp luật."}],
  "72": [{"jp":"**平日**は仕事で忙しい。","vi":"Ngày thường tôi bận làm việc."},{"jp":"この店は**平日**なら空いている。","vi":"Cửa hàng này vào ngày thường thì vắng."}],
  "73": [{"jp":"書類に今日の**日付**を書いてください。","vi":"Hãy ghi ngày hôm nay vào giấy tờ."},{"jp":"写真に**日付**が入っている。","vi":"Trên ảnh có ghi ngày tháng."}],
  "74": [{"jp":"**日中**はまだ暑いですね。","vi":"Ban ngày trời vẫn còn nóng nhỉ."},{"jp":"**日中**は仕事なので、夜に電話してください。","vi":"Ban ngày tôi đi làm nên hãy gọi điện vào buổi tối."}],
  "75": [{"jp":"旅行の**日程**が決まった。","vi":"Lịch trình chuyến du lịch đã được quyết định."},{"jp":"会議の**日程**を変更してもいいですか。","vi":"Tôi thay đổi lịch họp có được không?"}],
  "76": [{"jp":"京都まで**日帰り**で行ってきた。","vi":"Tôi đã đi Kyoto về trong ngày."},{"jp":"**日帰り**旅行なら温泉がいい。","vi":"Nếu đi du lịch trong ngày thì suối nước nóng là hay nhất."}],
  "77": [{"jp":"名前を五十音の**順序**で並べてください。","vi":"Hãy sắp xếp tên theo thứ tự bảng chữ cái tiếng Nhật."},{"jp":"物事には**順序**がある。","vi":"Việc gì cũng có thứ tự của nó."}],
  "78": [{"jp":"今は桜が咲く**時期**です。","vi":"Bây giờ là thời kỳ hoa anh đào nở."},{"jp":"引っ越しの**時期**を考えている。","vi":"Tôi đang cân nhắc thời điểm chuyển nhà."}],
  "79": [{"jp":"**現在**、東京に住んでいます。","vi":"Hiện tại tôi đang sống ở Tokyo."},{"jp":"**現在**の時刻は午後3時です。","vi":"Bây giờ là 3 giờ chiều."}],
  "80": [{"jp":"台風で**臨時**休業となった。","vi":"Cửa hàng tạm nghỉ vì bão."},{"jp":"祭りの日は**臨時**列車が出る。","vi":"Vào ngày lễ hội có chạy tàu tăng cường."}],
  "81": [{"jp":"留学の**費用**は親が出してくれた。","vi":"Bố mẹ đã chi trả chi phí du học cho tôi."},{"jp":"修理にはかなりの**費用**がかかる。","vi":"Việc sửa chữa tốn khá nhiều chi phí."}],
  "82": [{"jp":"この本を**定価**の半額で買った。","vi":"Tôi đã mua cuốn sách này với nửa giá niêm yết."},{"jp":"**定価**より安く売っている店を探す。","vi":"Tôi tìm cửa hàng bán rẻ hơn giá niêm yết."}],
  "83": [{"jp":"学生は2割の**割引**があります。","vi":"Học sinh sinh viên được giảm giá 20%."},{"jp":"閉店前は弁当が**割引**になる。","vi":"Trước giờ đóng cửa, cơm hộp được giảm giá."}],
  "84": [{"jp":"雑誌に**おまけ**が付いている。","vi":"Tạp chí có kèm quà tặng."},{"jp":"店の人がりんごを1個**おまけ**してくれた。","vi":"Người bán hàng đã cho thêm tôi một quả táo."}],
  "85": [{"jp":"子供は入場**無料**です。","vi":"Trẻ em được vào cửa miễn phí."},{"jp":"送料は**無料**になります。","vi":"Phí vận chuyển được miễn phí."}],
  "86": [{"jp":"お支払いは**現金**のみです。","vi":"Chỉ thanh toán bằng tiền mặt."},{"jp":"最近は**現金**をあまり持ち歩かない。","vi":"Dạo này tôi ít mang theo tiền mặt."}],
  "87": [{"jp":"**合計**でいくらになりますか。","vi":"Tổng cộng hết bao nhiêu tiền?"},{"jp":"テストの点数を**合計**した。","vi":"Tôi đã cộng tổng điểm bài kiểm tra."}],
  "88": [{"jp":"今月は**収入**が少なかった。","vi":"Tháng này thu nhập ít."},{"jp":"副業で**収入**を増やしたい。","vi":"Tôi muốn tăng thu nhập bằng nghề tay trái."}],
  "89": [{"jp":"毎月の**支出**を家計簿につけている。","vi":"Tôi ghi chi tiêu hàng tháng vào sổ thu chi."},{"jp":"収入より**支出**のほうが多い。","vi":"Chi tiêu nhiều hơn thu nhập."}],
  "90": [{"jp":"旅行の**予算**は10万円です。","vi":"Ngân sách cho chuyến du lịch là 100.000 yên."},{"jp":"**予算**が足りなくて計画が中止になった。","vi":"Kế hoạch bị hủy vì không đủ ngân sách."}],
  "91": [{"jp":"今年は大きな**利益**が出た。","vi":"Năm nay thu được lợi nhuận lớn."},{"jp":"会社は**利益**を上げるために努力している。","vi":"Công ty đang nỗ lực để tăng lợi nhuận."}],
  "92": [{"jp":"今月は**赤字**になってしまった。","vi":"Tháng này bị lỗ mất rồi."},{"jp":"その会社は3年連続で**赤字**だ。","vi":"Công ty đó thua lỗ 3 năm liên tiếp."}],
  "93": [{"jp":"出張の**経費**は会社が払う。","vi":"Công ty chi trả kinh phí đi công tác."},{"jp":"**経費**を削減しなければならない。","vi":"Phải cắt giảm kinh phí."}],
  "94": [{"jp":"すみません、お**勘定**をお願いします。","vi":"Xin lỗi, cho tôi tính tiền."},{"jp":"**勘定**は私が払います。","vi":"Để tôi thanh toán."}],
  "95": [{"jp":"借りた本を汚したので**弁償**した。","vi":"Tôi làm bẩn cuốn sách mượn nên đã bồi thường."},{"jp":"壊したカメラを**弁償**してください。","vi":"Hãy bồi thường cái máy ảnh đã làm hỏng."}],
  "96": [{"jp":"会社に交通費を**請求**した。","vi":"Tôi đã yêu cầu công ty thanh toán chi phí đi lại."},{"jp":"電気代の**請求**書が届いた。","vi":"Hóa đơn tiền điện đã đến."}],
  "97": [{"jp":"最近、**景気**がよくなってきた。","vi":"Gần đây tình hình kinh tế đã khá lên."},{"jp":"**景気**が悪くて、物が売れない。","vi":"Kinh tế ảm đạm nên hàng hóa không bán được."}],
  "98": [{"jp":"駅前で災害の**募金**を呼びかけている。","vi":"Trước nhà ga đang kêu gọi quyên góp cho vùng thiên tai."},{"jp":"わずかですが**募金**しました。","vi":"Tôi đã quyên góp một chút."}],
  "99": [{"jp":"アルバイトを**募集**しています。","vi":"Chúng tôi đang tuyển nhân viên làm thêm."},{"jp":"ボランティアの**募集**に応募した。","vi":"Tôi đã đăng ký đợt tuyển tình nguyện viên."}],
  "100": [{"jp":"この絵には高い**価値**がある。","vi":"Bức tranh này có giá trị cao."},{"jp":"この映画は一度見る**価値**がある。","vi":"Bộ phim này đáng xem một lần."}],
  "101": [{"jp":"父は甘い物を**好まない**。","vi":"Bố tôi không thích đồ ngọt."},{"jp":"若者が**好む**音楽は時代とともに変わる。","vi":"Âm nhạc giới trẻ ưa thích thay đổi theo thời đại."}],
  "102": [{"jp":"猫は水を**嫌う**。","vi":"Mèo ghét nước."},{"jp":"彼はうそをつく人を**嫌って**いる。","vi":"Anh ấy ghét những người nói dối."}],
  "103": [{"jp":"家族の幸せを**願って**います。","vi":"Tôi cầu mong gia đình hạnh phúc."},{"jp":"早く病気が治ることを**願う**。","vi":"Tôi mong bệnh sớm khỏi."},{"jp":"ご協力を**願います**。","vi":"Xin mọi người hợp tác."}],
  "104": [{"jp":"娘はいつも父親に**甘えて**いる。","vi":"Con gái tôi lúc nào cũng nũng nịu với bố."},{"jp":"では、お言葉に**甘えて**いただきます。","vi":"Vậy thì tôi xin nhận lời ý tốt của anh."}],
  "105": [{"jp":"祖母は孫を**かわいがって**いる。","vi":"Bà rất yêu chiều cháu."},{"jp":"子供のころ、犬を**かわいがって**いた。","vi":"Hồi nhỏ, tôi rất cưng con chó."}],
  "106": [{"jp":"財布を忘れたことに**気付いた**。","vi":"Tôi nhận ra mình đã quên ví."},{"jp":"彼女が髪を切ったのに誰も**気付かなかった**。","vi":"Cô ấy cắt tóc mà không ai nhận ra."}],
  "107": [{"jp":"警察は彼を犯人だと**疑って**いる。","vi":"Cảnh sát nghi ngờ anh ta là thủ phạm."},{"jp":"自分の目を**疑う**ほど驚いた。","vi":"Tôi ngạc nhiên đến mức không tin vào mắt mình."}],
  "108": [{"jp":"多くの人が貧困に**苦しんで**いる。","vi":"Nhiều người đang khổ sở vì nghèo đói."},{"jp":"彼は長い間、病気に**苦しんだ**。","vi":"Anh ấy đã vật vã với bệnh tật trong thời gian dài."}],
  "109": [{"jp":"ペットの死を家族みんなで**悲しんだ**。","vi":"Cả gia đình đều đau buồn trước cái chết của thú cưng."},{"jp":"そんなに**悲しまないで**ください。","vi":"Xin đừng buồn như vậy."}],
  "110": [{"jp":"試験に落ちて**がっかりした**。","vi":"Tôi thất vọng vì trượt kỳ thi."},{"jp":"雨で遠足が中止になり、子供たちは**がっかりして**いる。","vi":"Buổi dã ngoại bị hủy vì mưa nên bọn trẻ rất thất vọng."}],
  "111": [{"jp":"友達が落ち込んでいたので**励ました**。","vi":"Bạn tôi buồn chán nên tôi đã động viên."},{"jp":"先生の言葉に**励まされた**。","vi":"Tôi được khích lệ bởi lời của thầy."}],
  "112": [{"jp":"彼は黙って**うなずいた**。","vi":"Anh ấy im lặng gật đầu."},{"jp":"私の意見に皆が**うなずいて**くれた。","vi":"Mọi người đều gật đầu đồng ý với ý kiến của tôi."}],
  "113": [{"jp":"初めての仕事に**張り切って**いる。","vi":"Tôi đang rất hăng hái với công việc đầu tiên."},{"jp":"あまり**張り切り**すぎないでね。","vi":"Đừng hăng hái quá sức nhé."}],
  "114": [{"jp":"彼は部長になってから**威張って**いる。","vi":"Từ khi lên trưởng phòng, anh ta trở nên kiêu ngạo."},{"jp":"後輩に**威張る**のはよくない。","vi":"Lên mặt với đàn em là không tốt."}],
  "115": [{"jp":"父に大きな声で**怒鳴られた**。","vi":"Tôi bị bố quát mắng rất to."},{"jp":"子供に**怒鳴って**も逆効果だ。","vi":"Có quát con cũng phản tác dụng."}],
  "116": [{"jp":"酔った客が店で**暴れた**。","vi":"Vị khách say rượu đã quậy phá trong quán."},{"jp":"注射を嫌がって子供が**暴れて**いる。","vi":"Đứa trẻ sợ tiêm nên đang giãy giụa ầm ĩ."},{"jp":"犬が**暴れて**ひもが切れた。","vi":"Con chó vùng vẫy làm đứt dây."}],
  "117": [{"jp":"気分が悪くて道に**しゃがみ**込んだ。","vi":"Tôi thấy khó chịu nên ngồi thụp xuống đường."},{"jp":"**しゃがんで**花の写真を撮った。","vi":"Tôi ngồi xổm chụp ảnh hoa."}],
  "118": [{"jp":"邪魔だから、そこを**どいて**。","vi":"Vướng quá, tránh ra chỗ đó đi."},{"jp":"車が来たので道の端に**どいた**。","vi":"Có xe đến nên tôi tránh sang lề đường."}],
  "119": [{"jp":"机の上の荷物を**どけて**ください。","vi":"Hãy dẹp đồ trên bàn đi."},{"jp":"道の石を**どけて**車を通した。","vi":"Tôi dẹp đá trên đường để xe đi qua."}],
  "120": [{"jp":"日差しが強いので帽子を**かぶった**。","vi":"Nắng gắt nên tôi đội mũ."},{"jp":"バイクに乗る時はヘルメットを**かぶって**ください。","vi":"Khi đi xe máy hãy đội mũ bảo hiểm."}],
  "121": [{"jp":"子供に帽子を**かぶせた**。","vi":"Tôi đội mũ cho con."},{"jp":"料理にラップを**かぶせて**おく。","vi":"Tôi bọc màng bọc thực phẩm lên món ăn."},{"jp":"車にカバーを**かぶせた**。","vi":"Tôi trùm bạt lên xe ô tô."}],
  "122": [{"jp":"りんごを丸ごと**かじった**。","vi":"Tôi cắn nguyên quả táo."},{"jp":"ねずみが箱を**かじって**穴を開けた。","vi":"Chuột gặm thủng cái hộp."}],
  "123": [{"jp":"警官が犯人の足を**撃った**。","vi":"Cảnh sát đã bắn vào chân tên tội phạm."},{"jp":"鉄砲で鳥を**撃つ**のは禁止されている。","vi":"Cấm bắn chim bằng súng."}],
  "124": [{"jp":"坂道で自転車を**こぐ**のは大変だ。","vi":"Đạp xe lên dốc thật vất vả."},{"jp":"湖でボートを**漕いだ**。","vi":"Tôi chèo thuyền trên hồ."}],
  "125": [{"jp":"床にカーペットを**敷いた**。","vi":"Tôi trải thảm lên sàn."},{"jp":"寝る前に布団を**敷きます**。","vi":"Trước khi ngủ tôi trải nệm."}],
  "126": [{"jp":"お客さんにお茶を**ついだ**。","vi":"Tôi rót trà cho khách."},{"jp":"コップにビールを**ついで**ください。","vi":"Xin hãy rót bia vào cốc."}],
  "127": [{"jp":"駅前でチラシを**配って**いる。","vi":"Ở trước nhà ga có người đang phát tờ rơi."},{"jp":"先生が試験の問題用紙を**配った**。","vi":"Thầy giáo phát đề thi."}],
  "128": [{"jp":"犬にボールを**放った**。","vi":"Tôi ném quả bóng cho con chó."},{"jp":"仕事を**放って**おいて遊びに行った。","vi":"Bỏ mặc công việc mà đi chơi."},{"jp":"泣いている子を**放って**おけない。","vi":"Không thể bỏ mặc đứa trẻ đang khóc."}],
  "129": [{"jp":"庭に穴を**掘った**。","vi":"Tôi đào một cái hố trong vườn."},{"jp":"この辺りで古い土器が**掘り**出された。","vi":"Đồ gốm cổ đã được khai quật ở khu vực này."}],
  "130": [{"jp":"畑に種を**まいた**。","vi":"Tôi gieo hạt trên ruộng."},{"jp":"暑いので庭に水を**まいた**。","vi":"Trời nóng nên tôi tưới nước ra sân."},{"jp":"節分には豆を**まく**。","vi":"Vào ngày Setsubun, người ta rắc đậu."}],
  "131": [{"jp":"毎朝、体温を**計って**います。","vi":"Mỗi sáng tôi đều đo nhiệt độ cơ thể."},{"jp":"駅まで何分かかるか時間を**計った**。","vi":"Tôi đo xem đến ga mất bao nhiêu phút."}],
  "132": [{"jp":"友達に今年の運勢を**占って**もらった。","vi":"Tôi nhờ bạn bói vận mệnh năm nay."},{"jp":"この試合は今後の日本チームを**占う**大事な一戦だ。","vi":"Trận đấu này là trận quan trọng dự báo tương lai của đội Nhật Bản."}],
  "133": [{"jp":"子供が母親の手を**引っ張った**。","vi":"Đứa trẻ kéo tay mẹ."},{"jp":"彼はチームを**引っ張る**リーダーだ。","vi":"Anh ấy là người lãnh đạo dẫn dắt cả đội."}],
  "134": [{"jp":"指で彼の肩を**突いた**。","vi":"Tôi lấy ngón tay chọc vào vai anh ấy."},{"jp":"ほおづえを**突いて**窓の外を見ていた。","vi":"Tôi chống cằm nhìn ra ngoài cửa sổ."},{"jp":"祖父はつえを**突いて**歩く。","vi":"Ông tôi chống gậy đi bộ."}],
  "135": [{"jp":"この道を**突き当たった**ら右に曲がってください。","vi":"Đi hết con đường này thì rẽ phải."},{"jp":"研究が大きな壁に**突き当たった**。","vi":"Nghiên cứu đã vấp phải trở ngại lớn."}],
  "136": [{"jp":"名前を呼ばれて**立ち止まった**。","vi":"Bị gọi tên nên tôi dừng lại."},{"jp":"ここで**立ち止まら**ないでください。","vi":"Xin đừng dừng lại ở đây."}],
  "137": [{"jp":"危ないから、火に**近寄らない**で。","vi":"Nguy hiểm đấy, đừng lại gần lửa."},{"jp":"猫がゆっくりと**近寄って**きた。","vi":"Con mèo từ từ tiến lại gần."}],
  "138": [{"jp":"目の前を黒い猫が**横切った**。","vi":"Một con mèo đen chạy cắt ngang trước mặt tôi."},{"jp":"道路を**横切る**時は気をつけて。","vi":"Khi băng qua đường hãy cẩn thận."}],
  "139": [{"jp":"雪道で**転んで**けがをした。","vi":"Tôi ngã trên đường tuyết và bị thương."},{"jp":"子供が走って**転んだ**。","vi":"Đứa trẻ chạy rồi bị ngã."}],
  "140": [{"jp":"階段で**つまずいて**転んだ。","vi":"Tôi vấp ở cầu thang và bị ngã."},{"jp":"石に**つまずか**ないように気をつけて。","vi":"Cẩn thận kẻo vấp phải đá."},{"jp":"計画が最初の段階で**つまずいた**。","vi":"Kế hoạch đã gặp trục trặc ngay từ giai đoạn đầu."}],
  "141": [{"jp":"猫が車に**ひかれた**。","vi":"Con mèo bị xe cán."},{"jp":"危うく自転車を**ひく**ところだった。","vi":"Suýt nữa thì tôi cán phải chiếc xe đạp."}],
  "142": [{"jp":"子供が川で**おぼれて**いる。","vi":"Có đứa trẻ đang đuối nước dưới sông."},{"jp":"彼は酒に**おぼれて**仕事を失った。","vi":"Anh ta đắm chìm trong rượu chè nên mất việc."},{"jp":"海で**おぼれ**そうになった。","vi":"Tôi suýt chết đuối ở biển."}],
  "143": [{"jp":"雨の日は古傷が**痛む**。","vi":"Ngày mưa vết thương cũ lại đau."},{"jp":"その話を聞いて胸が**痛んだ**。","vi":"Nghe chuyện đó tôi thấy đau lòng."}],
  "144": [{"jp":"インフルエンザに**かかって**しまった。","vi":"Tôi bị nhiễm cúm mất rồi."},{"jp":"子供は病気に**かかり**やすい。","vi":"Trẻ con dễ mắc bệnh."}],
  "145": [{"jp":"ビールを飲んで**酔って**しまった。","vi":"Uống bia xong tôi bị say."},{"jp":"船に乗るとすぐ**酔う**。","vi":"Tôi cứ đi tàu thủy là bị say sóng."},{"jp":"美しい音楽に**酔った**。","vi":"Tôi say mê trong tiếng nhạc tuyệt đẹp."}],
  "146": [{"jp":"飲みすぎて**吐いて**しまった。","vi":"Tôi uống quá nhiều nên đã nôn ra."},{"jp":"気分が悪くて、**吐き**そうです。","vi":"Tôi thấy khó chịu, như sắp nôn."}],
  "147": [{"jp":"医者に**診て**もらったほうがいいですよ。","vi":"Bạn nên đi khám bác sĩ thì hơn."},{"jp":"先生が患者を丁寧に**診て**くれた。","vi":"Bác sĩ đã khám cho bệnh nhân rất kỹ."}],
  "148": [{"jp":"入院中の友人を**見舞い**に行った。","vi":"Tôi đã đi thăm người bạn đang nằm viện."},{"jp":"祖母を**見舞う**ために病院へ行きます。","vi":"Tôi đến bệnh viện để thăm bà."}],
  "149": [{"jp":"父は銀行に**勤めて**います。","vi":"Bố tôi làm việc ở ngân hàng."},{"jp":"この会社に十年**勤めた**。","vi":"Tôi đã làm việc ở công ty này mười năm."}],
  "150": [{"jp":"アルバイトで学費を**稼いで**いる。","vi":"Tôi đi làm thêm để kiếm tiền học phí."},{"jp":"彼は一か月で50万円**稼いだ**。","vi":"Anh ấy kiếm được 500 nghìn yên trong một tháng."}],
  "151": [{"jp":"代金はカードで**支払います**。","vi":"Tôi sẽ trả tiền bằng thẻ."},{"jp":"家賃は毎月末に**支払う**ことになっている。","vi":"Tiền nhà phải trả vào cuối mỗi tháng."}],
  "152": [{"jp":"荷物を**受け取り**ました。","vi":"Tôi đã nhận được hàng."},{"jp":"彼女はプレゼントを笑顔で**受け取った**。","vi":"Cô ấy mỉm cười nhận món quà."}],
  "153": [{"jp":"授業料を銀行に**払い込んだ**。","vi":"Tôi đã nộp học phí vào ngân hàng."},{"jp":"期限までに会費を**払い込んで**ください。","vi":"Vui lòng nộp hội phí trước hạn."}],
  "154": [{"jp":"中止になったので、チケット代が**払い戻された**。","vi":"Vì bị hủy nên tiền vé đã được hoàn lại."},{"jp":"余分に払った分を**払い戻して**もらった。","vi":"Tôi được hoàn lại phần tiền đã trả thừa."}],
  "155": [{"jp":"ATMでお金を**引き出した**。","vi":"Tôi đã rút tiền ở cây ATM."},{"jp":"先生は生徒の才能を**引き出す**のが上手だ。","vi":"Thầy giáo giỏi khơi dậy tài năng của học sinh."}],
  "156": [{"jp":"この商売はよく**もうかる**。","vi":"Việc kinh doanh này rất có lãi."},{"jp":"株で少し**もうかった**。","vi":"Tôi kiếm được chút lời nhờ cổ phiếu."}],
  "157": [{"jp":"彼は土地を売って大金を**もうけた**。","vi":"Anh ấy bán đất và kiếm được một khoản tiền lớn."},{"jp":"二人は三人の子どもを**もうけた**。","vi":"Hai người đã có ba đứa con."}],
  "158": [{"jp":"不況で売り上げが**落ち込んで**いる。","vi":"Do suy thoái, doanh thu đang giảm sút."},{"jp":"試験に落ちて、すっかり**落ち込んだ**。","vi":"Thi trượt nên tôi hoàn toàn suy sụp."},{"jp":"地震で道路が**落ち込んだ**。","vi":"Do động đất, mặt đường bị sụt xuống."}],
  "159": [{"jp":"この商品はとてもよく**売れて**いる。","vi":"Sản phẩm này đang bán rất chạy."},{"jp":"彼女の新しい本は百万部**売れた**。","vi":"Cuốn sách mới của cô ấy đã bán được một triệu bản."}],
  "160": [{"jp":"人気のパンはすぐに**売り切れる**。","vi":"Bánh mì được ưa chuộng bán hết ngay."},{"jp":"コンサートのチケットは一日で**売り切れた**。","vi":"Vé buổi hòa nhạc đã bán sạch trong một ngày."}],
  "161": [{"jp":"ガムが靴の底に**くっ付いた**。","vi":"Kẹo cao su dính vào đế giày."},{"jp":"子どもが母親に**くっ付いて**離れない。","vi":"Đứa trẻ cứ bám lấy mẹ không rời."}],
  "162": [{"jp":"壊れた皿を接着剤で**くっ付けた**。","vi":"Tôi dùng keo dán lại cái đĩa bị vỡ."},{"jp":"机を二つ**くっ付けて**ください。","vi":"Hãy ghép hai cái bàn lại với nhau."}],
  "163": [{"jp":"ゼリーが冷蔵庫で**固まった**。","vi":"Thạch đã đông lại trong tủ lạnh."},{"jp":"セメントが**固まる**まで触らないでください。","vi":"Đừng chạm vào cho đến khi xi măng cứng lại."},{"jp":"生徒たちが教室の隅に**固まって**いる。","vi":"Học sinh túm tụm lại ở góc lớp."}],
  "164": [{"jp":"雪を**固めて**雪だるまを作った。","vi":"Tôi nén chặt tuyết để làm người tuyết."},{"jp":"留学する決心を**固めた**。","vi":"Tôi đã quyết tâm đi du học."}],
  "165": [{"jp":"洗濯したらセーターが**縮んで**しまった。","vi":"Giặt xong thì chiếc áo len bị co lại."},{"jp":"寒さで体が**縮む**思いだった。","vi":"Lạnh đến mức người như co rúm lại."}],
  "166": [{"jp":"二人の距離が少しずつ**縮まった**。","vi":"Khoảng cách giữa hai người dần được rút ngắn."},{"jp":"トップとの差が3秒に**縮まった**。","vi":"Khoảng cách với người dẫn đầu đã rút xuống còn 3 giây."}],
  "167": [{"jp":"ズボンの丈を少し**縮めて**もらった。","vi":"Tôi nhờ người ta cắt ngắn ống quần một chút."},{"jp":"練習で記録を2秒**縮めた**。","vi":"Nhờ luyện tập, tôi đã rút ngắn thành tích được 2 giây."}],
  "168": [{"jp":"船が嵐で海に**沈んだ**。","vi":"Con tàu đã chìm xuống biển vì bão."},{"jp":"夕日が山の向こうに**沈んで**いく。","vi":"Mặt trời lặn dần sau núi."},{"jp":"悲しい知らせに気持ちが**沈んだ**。","vi":"Nghe tin buồn, lòng tôi chùng xuống."}],
  "169": [{"jp":"体をお湯に**沈めて**ゆっくり休んだ。","vi":"Tôi ngâm mình vào nước nóng và nghỉ ngơi thong thả."},{"jp":"敵の船を**沈めた**。","vi":"Đã đánh chìm tàu địch."}],
  "170": [{"jp":"夜になって気温が**下がった**。","vi":"Về đêm nhiệt độ đã giảm xuống."},{"jp":"薬を飲んだら熱が**下がった**。","vi":"Uống thuốc xong thì hạ sốt."},{"jp":"危ないので、白線の内側まで**下がって**ください。","vi":"Nguy hiểm, xin hãy lùi vào bên trong vạch trắng."}],
  "171": [{"jp":"店は商品の値段を**下げた**。","vi":"Cửa hàng đã hạ giá sản phẩm."},{"jp":"テレビの音を少し**下げて**ください。","vi":"Làm ơn vặn nhỏ tiếng tivi một chút."},{"jp":"彼は深く頭を**下げて**謝った。","vi":"Anh ấy cúi đầu thật sâu xin lỗi."}],
  "172": [{"jp":"ボールが坂を**転がって**いった。","vi":"Quả bóng lăn xuống dốc."},{"jp":"子どもが芝生の上を**転がって**遊んでいる。","vi":"Bọn trẻ đang lăn lộn chơi đùa trên bãi cỏ."}],
  "173": [{"jp":"大きな石を**転がして**運んだ。","vi":"Tôi lăn tảng đá lớn để di chuyển nó."},{"jp":"サイコロを**転がして**ください。","vi":"Hãy lăn xúc xắc đi."}],
  "174": [{"jp":"地震で家が少し**傾いた**。","vi":"Do động đất, ngôi nhà bị nghiêng một chút."},{"jp":"日が西に**傾いて**きた。","vi":"Mặt trời đã ngả về phía tây."},{"jp":"みんなの意見が賛成に**傾いて**いる。","vi":"Ý kiến mọi người đang nghiêng về phía tán thành."}],
  "175": [{"jp":"彼は首を**傾けて**考えていた。","vi":"Anh ấy nghiêng đầu suy nghĩ."},{"jp":"学生たちは先生の話に耳を**傾けた**。","vi":"Các sinh viên lắng nghe lời thầy giáo."},{"jp":"研究に全力を**傾けて**いる。","vi":"Tôi đang dồn toàn lực vào việc nghiên cứu."}],
  "176": [{"jp":"肉を**裏返して**、反対側も焼いてください。","vi":"Hãy lật miếng thịt lại và nướng mặt bên kia."},{"jp":"靴下を**裏返して**洗濯する。","vi":"Lộn trái tất ra rồi giặt."}],
  "177": [{"jp":"弟の部屋はいつも**散らかって**いる。","vi":"Phòng em trai tôi lúc nào cũng bừa bộn."},{"jp":"机の上におもちゃが**散らかって**いる。","vi":"Đồ chơi vứt bừa bộn trên bàn."}],
  "178": [{"jp":"子どもが部屋を**散らかした**。","vi":"Bọn trẻ đã bày bừa khắp phòng."},{"jp":"ごみを**散らかさない**でください。","vi":"Xin đừng vứt rác bừa bãi."}],
  "179": [{"jp":"床にガラスの破片が**散らばって**いる。","vi":"Mảnh thủy tinh văng tung tóe trên sàn."},{"jp":"卒業生は全国に**散らばって**いる。","vi":"Những người tốt nghiệp sống rải rác khắp cả nước."}],
  "180": [{"jp":"玉ねぎを細かく**刻んで**ください。","vi":"Hãy thái nhỏ hành tây."},{"jp":"木に自分の名前を**刻んだ**。","vi":"Tôi đã khắc tên mình lên cây."},{"jp":"先生の言葉を心に**刻んで**いる。","vi":"Tôi khắc ghi lời thầy trong lòng."}],
  "181": [{"jp":"歯に何か**挟まって**いる。","vi":"Có cái gì đó bị giắt vào răng."},{"jp":"電車のドアにかばんが**挟まった**。","vi":"Cái túi bị kẹp vào cửa tàu điện."}],
  "182": [{"jp":"パンにハムを**挟んで**食べた。","vi":"Tôi kẹp giăm bông vào bánh mì để ăn."},{"jp":"ドアに指を**挟んで**しまった。","vi":"Tôi bị kẹp ngón tay vào cửa."},{"jp":"会議中、彼は時々質問を**挟んだ**。","vi":"Trong cuộc họp, anh ấy thỉnh thoảng chen vào vài câu hỏi."}],
  "183": [{"jp":"箱が重みで**つぶれて**しまった。","vi":"Cái hộp bị bẹp dí vì sức nặng."},{"jp":"不景気で多くの会社が**つぶれた**。","vi":"Vì kinh tế đi xuống, nhiều công ty đã phá sản."},{"jp":"雨のせいで計画が**つぶれた**。","vi":"Vì mưa mà kế hoạch đổ bể."}],
  "184": [{"jp":"空き缶を**つぶして**捨ててください。","vi":"Hãy bóp bẹp lon rỗng rồi vứt đi."},{"jp":"駅のカフェで時間を**つぶした**。","vi":"Tôi giết thời gian ở quán cà phê nhà ga."},{"jp":"彼の失敗が会社の顔を**つぶした**。","vi":"Sai lầm của anh ấy đã làm mất mặt công ty."}],
  "185": [{"jp":"ぶつけて車のドアが**へこんだ**。","vi":"Bị va chạm nên cửa xe ô tô bị móp."},{"jp":"先生に注意されて、少し**へこんで**いる。","vi":"Bị thầy nhắc nhở nên tôi hơi buồn xìu."}],
  "186": [{"jp":"歩いていたら靴のひもが**ほどけた**。","vi":"Đang đi thì dây giày bị tuột."},{"jp":"リボンが**ほどけ**ないように強く結んだ。","vi":"Tôi buộc chặt để nơ không bị tuột ra."}],
  "187": [{"jp":"プレゼントのリボンを**ほどいた**。","vi":"Tôi tháo nơ của món quà ra."},{"jp":"絡まった糸を**ほどく**のは大変だ。","vi":"Gỡ sợi chỉ bị rối thật vất vả."}],
  "188": [{"jp":"水をやらなかったので、花が**枯れて**しまった。","vi":"Vì không tưới nước nên hoa đã héo mất."},{"jp":"秋になると木の葉が**枯れる**。","vi":"Đến mùa thu, lá cây úa tàn."}],
  "189": [{"jp":"旅行中に植木を**枯らして**しまった。","vi":"Trong lúc đi du lịch, tôi để cây cảnh chết héo."},{"jp":"肥料のやりすぎは植物を**枯らす**。","vi":"Bón quá nhiều phân sẽ làm cây héo chết."}],
  "190": [{"jp":"夏は食べ物が**傷み**やすい。","vi":"Mùa hè thức ăn dễ bị hỏng."},{"jp":"古い家なので、壁がかなり**傷んで**いる。","vi":"Vì nhà cũ nên tường đã xuống cấp khá nhiều."}],
  "191": [{"jp":"雨で洗濯物が**湿って**いる。","vi":"Vì mưa nên quần áo phơi bị ẩm."},{"jp":"**湿った**タオルで顔をふいた。","vi":"Tôi lau mặt bằng chiếc khăn ẩm."}],
  "192": [{"jp":"寒さで池の水が**凍った**。","vi":"Vì lạnh, nước trong ao đã đóng băng."},{"jp":"**凍った**道で滑って転んだ。","vi":"Tôi trượt ngã trên con đường đóng băng."}],
  "193": [{"jp":"寒くて体が**震えて**いる。","vi":"Lạnh quá nên người tôi run lên."},{"jp":"緊張で声が**震えた**。","vi":"Vì căng thẳng mà giọng tôi run run."}],
  "194": [{"jp":"夜空に星が**輝いて**いる。","vi":"Những vì sao đang lấp lánh trên bầu trời đêm."},{"jp":"優勝した選手の目が**輝いて**いた。","vi":"Đôi mắt của vận động viên vô địch sáng rực."}],
  "195": [{"jp":"大雨で川の水が**あふれた**。","vi":"Do mưa lớn, nước sông đã tràn bờ."},{"jp":"彼女の目に涙が**あふれて**いた。","vi":"Nước mắt trào ra trong mắt cô ấy."},{"jp":"会場は人で**あふれて**いる。","vi":"Hội trường chật kín người."}],
  "196": [{"jp":"料理を作りすぎて、たくさん**余った**。","vi":"Nấu quá nhiều nên còn thừa rất nhiều."},{"jp":"**余った**お金は貯金します。","vi":"Tiền còn dư tôi sẽ để dành."}],
  "197": [{"jp":"彼は背が高いので、どこにいても**目立つ**。","vi":"Anh ấy cao nên ở đâu cũng nổi bật."},{"jp":"このシャツは汚れが**目立た**ない。","vi":"Chiếc áo này không lộ vết bẩn."}],
  "198": [{"jp":"山の上から町を**見下ろした**。","vi":"Tôi nhìn xuống thị trấn từ trên đỉnh núi."},{"jp":"彼は人を**見下ろす**ような態度をとる。","vi":"Anh ta có thái độ như coi thường người khác."}],
  "199": [{"jp":"選手たちは最後まで**戦った**。","vi":"Các cầu thủ đã chiến đấu đến cùng."},{"jp":"彼は長い間、病気と**闘って**いる。","vi":"Anh ấy đã chống chọi với bệnh tật trong thời gian dài."},{"jp":"労働者は賃上げを求めて会社と**闘った**。","vi":"Người lao động đấu tranh với công ty đòi tăng lương."}],
  "200": [{"jp":"日本チームは決勝で**敗れた**。","vi":"Đội Nhật Bản đã thua ở trận chung kết."},{"jp":"彼は選挙に**敗れて**、政界を去った。","vi":"Ông ấy thất cử và rời khỏi chính trường."}],
  "201": [{"jp":"犯人は車で**逃げた**。","vi":"Thủ phạm đã chạy trốn bằng ô tô."},{"jp":"嫌なことから**逃げて**はいけない。","vi":"Không được trốn tránh những điều khó chịu."}],
  "202": [{"jp":"釣った魚を川に**逃がして**やった。","vi":"Tôi thả con cá câu được về sông."},{"jp":"警察は犯人を**逃がして**しまった。","vi":"Cảnh sát đã để tên tội phạm trốn thoát."},{"jp":"せっかくのチャンスを**逃がした**。","vi":"Tôi đã để tuột mất cơ hội hiếm có."}],
  "203": [{"jp":"忘れ物に気づいて、家に**戻った**。","vi":"Nhận ra để quên đồ, tôi quay lại nhà."},{"jp":"電気が**戻る**まで待ちましょう。","vi":"Hãy đợi cho đến khi có điện trở lại."}],
  "204": [{"jp":"使ったはさみは元の場所に**戻して**ください。","vi":"Kéo dùng xong hãy để lại chỗ cũ."},{"jp":"話を最初に**戻しましょう**。","vi":"Chúng ta hãy quay lại câu chuyện từ đầu."}],
  "205": [{"jp":"指輪が指にぴったり**はまった**。","vi":"Chiếc nhẫn vừa khít với ngón tay."},{"jp":"車のタイヤが溝に**はまって**動かない。","vi":"Bánh xe bị sa xuống rãnh, không nhúc nhích được."},{"jp":"最近、韓国ドラマに**はまって**いる。","vi":"Dạo này tôi đang nghiện phim Hàn."}],
  "206": [{"jp":"寒いので手袋を**はめた**。","vi":"Trời lạnh nên tôi đeo găng tay."},{"jp":"窓にガラスを**はめる**作業をした。","vi":"Tôi đã làm công việc lắp kính vào cửa sổ."}],
  "207": [{"jp":"この機械は丁寧に**扱って**ください。","vi":"Hãy sử dụng chiếc máy này cẩn thận."},{"jp":"子どもとして**扱われる**のは嫌だ。","vi":"Tôi không thích bị đối xử như trẻ con."},{"jp":"この店では輸入品を**扱って**いる。","vi":"Cửa hàng này kinh doanh hàng nhập khẩu."}],
  "208": [{"jp":"命に**関わる**病気ではありません。","vi":"Đây không phải bệnh nguy hiểm đến tính mạng."},{"jp":"彼はその事件に**関わって**いたらしい。","vi":"Nghe nói anh ta có dính líu đến vụ việc đó."}],
  "209": [{"jp":"彼は医者を**目指して**勉強している。","vi":"Anh ấy đang học với mục tiêu trở thành bác sĩ."},{"jp":"私たちは優勝を**目指す**。","vi":"Chúng tôi nhắm tới chức vô địch."}],
  "210": [{"jp":"明日の朝、成田を**発ちます**。","vi":"Sáng mai tôi sẽ khởi hành từ Narita."},{"jp":"彼は席を**立って**、部屋を出て行った。","vi":"Anh ấy rời chỗ ngồi và đi ra khỏi phòng."}],
  "211": [{"jp":"空港まで友達を**迎え**に行った。","vi":"Tôi ra sân bay đón bạn."},{"jp":"新しい年を家族と**迎えた**。","vi":"Tôi đón năm mới cùng gia đình."}],
  "212": [{"jp":"彼は優しいので、女性に**持てる**。","vi":"Anh ấy hiền nên được phụ nữ yêu thích."},{"jp":"学生時代、彼女はとても**持てた**。","vi":"Hồi đi học, cô ấy rất được hâm mộ."}],
  "213": [{"jp":"人生はよく旅に**たとえられる**。","vi":"Cuộc đời thường được ví như một chuyến đi."},{"jp":"彼女の美しさは花に**たとえる**ことができる。","vi":"Vẻ đẹp của cô ấy có thể ví như một bông hoa."}],
  "214": [{"jp":"健康の維持に**努めて**います。","vi":"Tôi đang cố gắng giữ gìn sức khỏe."},{"jp":"問題の解決に**努める**つもりです。","vi":"Tôi định nỗ lực giải quyết vấn đề."}],
  "215": [{"jp":"私にリーダーが**務まる**か心配だ。","vi":"Tôi lo không biết mình có đảm nhiệm nổi vai trò trưởng nhóm không."},{"jp":"彼ならその役は十分**務まる**だろう。","vi":"Nếu là anh ấy thì chắc chắn đảm đương tốt vai trò đó."}],
  "216": [{"jp":"彼女は会議の司会を**務めた**。","vi":"Cô ấy đã làm người dẫn chương trình cuộc họp."},{"jp":"父は長年、町長を**務めて**いる。","vi":"Bố tôi giữ chức thị trưởng đã nhiều năm."}],
  "217": [{"jp":"ホテルの予約を**取り消した**。","vi":"Tôi đã hủy đặt phòng khách sạn."},{"jp":"先ほどの発言を**取り消します**。","vi":"Tôi xin rút lại lời phát biểu vừa rồi."}],
  "218": [{"jp":"仕事を**終えて**から、飲みに行った。","vi":"Xong việc, tôi đi uống."},{"jp":"彼は90歳で生涯を**終えた**。","vi":"Ông ấy đã qua đời ở tuổi 90."}],
  "219": [{"jp":"駅前で募金を**呼びかけて**いる。","vi":"Họ đang kêu gọi quyên góp trước nhà ga."},{"jp":"後ろから名前を**呼びかけられた**。","vi":"Tôi bị ai đó gọi tên từ phía sau."}],
  "220": [{"jp":"授業中に騒いで、職員室に**呼び出された**。","vi":"Làm ồn trong giờ học nên tôi bị gọi lên phòng giáo viên."},{"jp":"夜中に電話で**呼び出されて**会社へ行った。","vi":"Nửa đêm bị gọi điện triệu tập nên tôi phải lên công ty."}],
  "221": [{"jp":"手伝っていただけると、本当に**ありがたい**です。","vi":"Nếu anh giúp được thì tôi thật sự biết ơn."},{"jp":"皆さんの温かい言葉が**有難かった**。","vi":"Tôi rất cảm kích trước những lời ấm áp của mọi người."}],
  "222": [{"jp":"遅れてしまって、**申し訳ない**。","vi":"Thật xin lỗi vì đã đến muộn."},{"jp":"ご迷惑をおかけして、**申し訳ありません**。","vi":"Thành thật xin lỗi vì đã gây phiền phức."}],
  "223": [{"jp":"ご結婚、おめでとうございます。本当に**めでたい**ですね。","vi":"Chúc mừng đám cưới. Thật là chuyện đáng mừng."},{"jp":"正月は**めでたい**料理を食べる。","vi":"Ngày Tết người ta ăn những món ăn mang điềm lành."}],
  "224": [{"jp":"けががなくて**幸いでした**。","vi":"Thật may là không bị thương."},{"jp":"お役に立てれば**幸いです**。","vi":"Nếu giúp ích được cho anh thì tôi rất vui."}],
  "225": [{"jp":"外国に住んでいると、母の料理が**恋しく**なる。","vi":"Sống ở nước ngoài, tôi nhớ món ăn mẹ nấu."},{"jp":"寒い日はこたつが**恋しい**。","vi":"Những ngày lạnh lại nhớ cái bàn sưởi kotatsu."}],
  "226": [{"jp":"この歌を聞くと、学生時代が**懐かしく**なる。","vi":"Nghe bài hát này tôi lại hoài niệm thời đi học."},{"jp":"久しぶりに**懐かしい**友人に会った。","vi":"Lâu lắm rồi tôi mới gặp lại người bạn cũ thân thương."}],
  "227": [{"jp":"**幼い**頃、よくこの公園で遊んだ。","vi":"Hồi bé, tôi hay chơi ở công viên này."},{"jp":"彼の考え方はまだ**幼い**。","vi":"Cách suy nghĩ của cậu ấy vẫn còn non nớt."}],
  "228": [{"jp":"一人で外国に行くのは**心細い**。","vi":"Một mình đi nước ngoài thật thấy chơi vơi lo lắng."},{"jp":"財布の中が**心細く**なってきた。","vi":"Tiền trong ví đã bắt đầu vơi đi đáng lo."}],
  "229": [{"jp":"雨の中で鳴いている子猫が**かわいそうだ**。","vi":"Con mèo con kêu trong mưa trông thật tội nghiệp."},{"jp":"そんなことを言ったら彼が**かわいそうです**よ。","vi":"Nói như thế thì tội cho anh ấy lắm."}],
  "230": [{"jp":"事故で家を失うなんて、**気の毒な**話だ。","vi":"Mất nhà vì tai nạn, thật là chuyện đáng thương."},{"jp":"お待たせして、**気の毒な**ことをしました。","vi":"Để anh phải chờ, tôi thấy thật áy náy."}],
  "231": [{"jp":"彼は**貧しい**家庭に生まれた。","vi":"Anh ấy sinh ra trong một gia đình nghèo."},{"jp":"知識が**貧しい**と、判断を誤りやすい。","vi":"Kiến thức nghèo nàn thì dễ phán đoán sai."}],
  "232": [{"jp":"あと一点で負けた。本当に**惜しかった**。","vi":"Thua chỉ vì một điểm. Thật đáng tiếc."},{"jp":"まだ使えるのに捨てるのは**惜しい**。","vi":"Vẫn còn dùng được mà vứt đi thì tiếc."}],
  "233": [{"jp":"雨なら、中止しても**仕方がない**。","vi":"Nếu mưa thì đành phải hủy thôi."},{"jp":"過ぎたことを悔やんでも**仕方ない**。","vi":"Hối tiếc chuyện đã qua cũng chẳng ích gì."}],
  "234": [{"jp":"**やむを得ない**事情で欠席します。","vi":"Vì hoàn cảnh bất đắc dĩ nên tôi xin vắng mặt."},{"jp":"台風なので、運休も**やむを得ない**。","vi":"Vì có bão nên việc tạm ngừng chạy tàu là bất khả kháng."}],
  "235": [{"jp":"毎日料理をするのは**面倒臭い**。","vi":"Ngày nào cũng nấu ăn thật phiền phức."},{"jp":"**面倒臭そうな**顔をしないでください。","vi":"Đừng làm mặt như thấy phiền thế."}],
  "236": [{"jp":"同じことを何度も聞かれて、**しつこい**と思った。","vi":"Bị hỏi đi hỏi lại một chuyện, tôi thấy thật lằng nhằng."},{"jp":"**しつこい**勧誘の電話に困っている。","vi":"Tôi khổ sở vì những cuộc gọi chào mời dai dẳng."},{"jp":"この料理は味が**しつこくて**苦手だ。","vi":"Món này vị quá đậm ngấy nên tôi không thích."}],
  "237": [{"jp":"部長の話は**くどくて**長い。","vi":"Bài nói của trưởng phòng dài dòng lê thê."},{"jp":"**くどい**ようですが、明日は遅れないでください。","vi":"Có thể tôi nói nhiều, nhưng mai đừng đến muộn nhé."}],
  "238": [{"jp":"たき火の近くは**煙い**。","vi":"Gần đống lửa trại thì đầy khói."},{"jp":"タバコの煙で部屋が**煙くて**目が痛い。","vi":"Phòng ngập khói thuốc lá nên tôi cay mắt."}],
  "239": [{"jp":"通路に置いた荷物が**邪魔だ**。","vi":"Hành lý để ở lối đi thật vướng víu."},{"jp":"**邪魔な**物は片付けてください。","vi":"Hãy dọn những thứ vướng víu đi."}],
  "240": [{"jp":"工事の音が**うるさくて**眠れない。","vi":"Tiếng công trình ồn ào quá nên tôi không ngủ được."},{"jp":"母は勉強しろと**うるさい**。","vi":"Mẹ cứ cằn nhằn bắt tôi học."},{"jp":"父は味に**うるさい**人だ。","vi":"Bố tôi là người khó tính về khẩu vị."}],
  "241": [{"jp":"外が**騒々しい**が、何かあったのだろうか。","vi":"Bên ngoài ồn ào quá, không biết có chuyện gì."},{"jp":"最近、世の中が**騒々しい**。","vi":"Dạo này thế giới thật nhiều biến động ồn ào."}],
  "242": [{"jp":"年末は毎日**慌ただしい**。","vi":"Cuối năm ngày nào cũng bận túi bụi."},{"jp":"彼は**慌ただしく**部屋を出て行った。","vi":"Anh ấy vội vã rời khỏi phòng."}],
  "243": [{"jp":"彼は**そそっかしくて**、よく忘れ物をする。","vi":"Anh ấy hấp tấp nên hay để quên đồ."},{"jp":"**そそっかしい**ミスを減らしたい。","vi":"Tôi muốn giảm những lỗi do cẩu thả."}],
  "244": [{"jp":"**思いがけない**ところで友人に会った。","vi":"Tôi gặp bạn ở một nơi không ngờ tới."},{"jp":"**思いがけない**プレゼントをもらった。","vi":"Tôi nhận được món quà bất ngờ."}],
  "245": [{"jp":"**何気ない**一言が彼女を傷つけた。","vi":"Một câu nói vô tình đã làm cô ấy tổn thương."},{"jp":"**何気なく**窓の外を見ると、雪が降っていた。","vi":"Tình cờ nhìn ra ngoài cửa sổ, tôi thấy tuyết đang rơi."}],
  "246": [{"jp":"**とんでもない**ことをしてしまった。","vi":"Tôi đã gây ra một chuyện tày đình."},{"jp":"そんな**とんでもない**話、信じられない。","vi":"Câu chuyện vô lý như thế, tôi không tin nổi."},{"jp":"「ありがとう」「いいえ、**とんでもない**です」","vi":"\"Cảm ơn nhé.\" \"Không, có gì đâu ạ.\""}],
  "247": [{"jp":"そんな**くだらない**ことで喧嘩するな。","vi":"Đừng cãi nhau vì chuyện vớ vẩn như thế."},{"jp":"この番組は**くだらない**。","vi":"Chương trình này thật vô bổ."}],
  "248": [{"jp":"そんな**ばかばかしい**話は聞きたくない。","vi":"Tôi không muốn nghe câu chuyện ngớ ngẩn như vậy."},{"jp":"一時間も並ぶなんて**ばかばかしい**。","vi":"Xếp hàng cả tiếng đồng hồ thật là vớ vẩn."}],
  "249": [{"jp":"彼の言うことは**でたらめだ**。","vi":"Những gì anh ta nói toàn là bịa đặt."},{"jp":"**でたらめな**答えを書いてしまった。","vi":"Tôi đã viết câu trả lời linh tinh."}],
  "250": [{"jp":"彼は服装が**だらしない**。","vi":"Anh ấy ăn mặc luộm thuộm."},{"jp":"お金に**だらしない**人とは付き合いたくない。","vi":"Tôi không muốn chơi với người tiêu tiền bừa bãi."}],
  "251": [{"jp":"彼は**ずうずうしく**も、また金を借りに来た。","vi":"Anh ta trơ trẽn lại đến vay tiền nữa."},{"jp":"列に割り込むなんて**ずうずうしい**人だ。","vi":"Chen ngang hàng, đúng là người trơ trẽn."}],
  "252": [{"jp":"自分だけ先に帰るなんて**ずるい**よ。","vi":"Về trước một mình thế là chơi xấu đấy."},{"jp":"試験で**ずるい**ことをしてはいけない。","vi":"Không được gian lận trong kỳ thi."}],
  "253": [{"jp":"あの子はいつも**憎らしい**ことを言う。","vi":"Đứa bé đó lúc nào cũng nói những câu đáng ghét."},{"jp":"彼は**憎らしい**ほど何でもできる。","vi":"Anh ấy giỏi mọi thứ đến mức phát ghét."}],
  "254": [{"jp":"家族を傷つけた犯人が**憎い**。","vi":"Tôi căm ghét kẻ đã làm hại gia đình mình."},{"jp":"戦争を起こした者が**憎い**。","vi":"Tôi căm ghét những kẻ đã gây ra chiến tranh."}],
  "255": [{"jp":"**険しい**山道を登った。","vi":"Tôi đã leo con đường núi dốc đứng."},{"jp":"父は**険しい**顔で話を聞いていた。","vi":"Bố nghe chuyện với vẻ mặt nghiêm khắc."},{"jp":"優勝への道は**険しい**。","vi":"Con đường đến chức vô địch đầy gian nan."}],
  "256": [{"jp":"友達と別れるのは**辛い**。","vi":"Chia tay bạn bè thật đau lòng."},{"jp":"毎朝早く起きるのが**辛い**です。","vi":"Mỗi sáng dậy sớm thật khổ sở."}],
  "257": [{"jp":"太ったので、このズボンは**きつい**。","vi":"Vì tăng cân nên chiếc quần này chật."},{"jp":"この仕事は体力的に**きつい**。","vi":"Công việc này vất vả về mặt thể lực."},{"jp":"彼女は**きつい**言い方をする。","vi":"Cô ấy có cách nói gay gắt."}],
  "258": [{"jp":"ベルトが**緩い**ので、穴を一つ増やした。","vi":"Thắt lưng lỏng nên tôi đục thêm một lỗ."},{"jp":"この道は**緩い**坂になっている。","vi":"Con đường này là con dốc thoai thoải."},{"jp":"おかゆを**緩く**作った。","vi":"Tôi nấu cháo loãng."}],
  "259": [{"jp":"このナイフは切れ味が**鈍い**。","vi":"Con dao này cùn."},{"jp":"彼は人の気持ちに**鈍い**。","vi":"Anh ấy chậm hiểu cảm xúc của người khác."},{"jp":"頭に**鈍い**痛みを感じる。","vi":"Tôi thấy đau âm ỉ ở đầu."}],
  "260": [{"jp":"猫は**鋭い**爪を持っている。","vi":"Mèo có móng vuốt sắc nhọn."},{"jp":"彼女は**鋭い**質問をした。","vi":"Cô ấy đã đặt một câu hỏi sắc sảo."},{"jp":"犬は鼻が**鋭い**。","vi":"Chó có khứu giác nhạy bén."}],
  "261": [{"jp":"彼は金遣いが**荒い**。","vi":"Anh ấy tiêu tiền hoang phí."},{"jp":"台風で波が**荒く**なってきた。","vi":"Do bão, sóng ngày càng dữ dội."},{"jp":"走った後で、息が**荒い**。","vi":"Chạy xong nên hơi thở gấp gáp."}],
  "262": [{"jp":"彼は**強引に**自分の意見を通した。","vi":"Anh ấy cưỡng ép để ý kiến của mình được thông qua."},{"jp":"**強引な**勧誘には注意してください。","vi":"Hãy cảnh giác với những lời chào mời ép buộc."}],
  "263": [{"jp":"人の物を**勝手に**使わないで。","vi":"Đừng tự ý dùng đồ của người khác."},{"jp":"彼はいつも**勝手な**ことばかり言う。","vi":"Anh ta lúc nào cũng chỉ nói những điều tùy tiện."}],
  "264": [{"jp":"彼女は交渉で**強気な**態度を崩さなかった。","vi":"Cô ấy giữ vững thái độ cứng rắn trong đàm phán."},{"jp":"社長は来年の売り上げに**強気だ**。","vi":"Giám đốc rất tự tin vào doanh thu năm sau."}],
  "265": [{"jp":"祖父は**頑固で**、人の意見を聞かない。","vi":"Ông tôi bảo thủ, không nghe ý kiến của người khác."},{"jp":"**頑固な**汚れがなかなか落ちない。","vi":"Vết bẩn cứng đầu mãi không sạch."}],
  "266": [{"jp":"**過剰な**ダイエットは体に悪い。","vi":"Ăn kiêng quá mức có hại cho sức khỏe."},{"jp":"彼は自分の能力に**過剰な**自信を持っている。","vi":"Anh ấy tự tin thái quá vào năng lực của mình."}],
  "267": [{"jp":"それは会社にとって**重大な**問題だ。","vi":"Đó là vấn đề hệ trọng đối với công ty."},{"jp":"彼は**重大な**ミスを犯した。","vi":"Anh ấy đã phạm một sai lầm nghiêm trọng."}],
  "268": [{"jp":"水不足が**深刻な**問題になっている。","vi":"Thiếu nước đang trở thành vấn đề nghiêm trọng."},{"jp":"彼は**深刻な**顔で相談に来た。","vi":"Anh ấy đến xin lời khuyên với vẻ mặt nặng nề."}],
  "269": [{"jp":"一人暮らしは**気楽だ**。","vi":"Sống một mình thật thoải mái."},{"jp":"どうぞ**気楽に**してください。","vi":"Xin cứ tự nhiên thoải mái."}],
  "270": [{"jp":"**安易な**考えで仕事を辞めるべきではない。","vi":"Không nên bỏ việc chỉ vì suy nghĩ dễ dãi."},{"jp":"**安易に**人を信じてはいけない。","vi":"Không được dễ dàng tin người."}],
  "271": [{"jp":"宝くじに当たるなんて、**運**がいいね。","vi":"Trúng xổ số, đúng là may mắn nhỉ."},{"jp":"最後は**運**に任せるしかない。","vi":"Cuối cùng chỉ còn cách phó mặc cho số phận."}],
  "272": [{"jp":"私の**勘**が当たった。","vi":"Linh cảm của tôi đã đúng."},{"jp":"彼は**勘**がいいので、すぐに気づいた。","vi":"Anh ấy nhạy bén nên nhận ra ngay."}],
  "273": [{"jp":"寒さで指の**感覚**がなくなった。","vi":"Vì lạnh mà ngón tay mất hết cảm giác."},{"jp":"彼女は色の**感覚**が優れている。","vi":"Cô ấy có cảm quan màu sắc rất tốt."}],
  "274": [{"jp":"歯の**神経**を抜く治療をした。","vi":"Tôi đã điều trị rút tủy răng."},{"jp":"試験の前は**神経**が高ぶって眠れない。","vi":"Trước kỳ thi thần kinh căng thẳng nên tôi không ngủ được."},{"jp":"彼は細かいことに**神経**を使う。","vi":"Anh ấy để tâm đến cả những chuyện nhỏ nhặt."}],
  "275": [{"jp":"子どもの頃の**記憶**はほとんどない。","vi":"Tôi hầu như không còn ký ức thời thơ ấu."},{"jp":"祖母は最近**記憶**力が落ちてきた。","vi":"Gần đây trí nhớ của bà tôi đã suy giảm."}],
  "276": [{"jp":"彼の**様子**が少しおかしい。","vi":"Trạng thái của anh ấy hơi lạ."},{"jp":"しばらく**様子**を見ましょう。","vi":"Hãy theo dõi tình hình thêm một thời gian."}],
  "277": [{"jp":"この店は**雰囲気**がいい。","vi":"Quán này có bầu không khí dễ chịu."},{"jp":"会議は重い**雰囲気**だった。","vi":"Cuộc họp có bầu không khí nặng nề."}],
  "278": [{"jp":"この町の**魅力**は自然の美しさだ。","vi":"Sức hấp dẫn của thị trấn này là vẻ đẹp thiên nhiên."},{"jp":"彼女は**魅力**的な笑顔の持ち主だ。","vi":"Cô ấy có nụ cười quyến rũ."}],
  "279": [{"jp":"今日は部長の**機嫌**が悪い。","vi":"Hôm nay tâm trạng trưởng phòng không tốt."},{"jp":"子どもはお菓子をもらって**機嫌**を直した。","vi":"Đứa trẻ được cho kẹo nên vui vẻ trở lại."}],
  "280": [{"jp":"若者の政治への**関心**が低い。","vi":"Giới trẻ ít quan tâm đến chính trị."},{"jp":"彼は環境問題に強い**関心**を持っている。","vi":"Anh ấy rất quan tâm đến vấn đề môi trường."}],
  "281": [{"jp":"彼は仕事への**意欲**にあふれている。","vi":"Anh ấy tràn đầy nhiệt huyết với công việc."},{"jp":"学生の学習**意欲**を高めたい。","vi":"Tôi muốn nâng cao ý chí học tập của sinh viên."}],
  "282": [{"jp":"試合では**全力**を尽くします。","vi":"Tôi sẽ dốc toàn lực trong trận đấu."},{"jp":"ゴールまで**全力**で走った。","vi":"Tôi chạy hết sức về đích."}],
  "283": [{"jp":"冗談ではなく、**本気**で言っているんだ。","vi":"Không phải đùa đâu, tôi nói nghiêm túc đấy."},{"jp":"彼はやっと**本気**で勉強を始めた。","vi":"Cuối cùng cậu ấy cũng bắt đầu học thật sự nghiêm túc."}],
  "284": [{"jp":"事故の後、彼は**意識**を失った。","vi":"Sau tai nạn, anh ấy đã bất tỉnh."},{"jp":"環境問題への**意識**が高まっている。","vi":"Ý thức về vấn đề môi trường đang được nâng cao."}],
  "285": [{"jp":"ファンの応援に**感激**しました。","vi":"Tôi rất xúc động trước sự cổ vũ của người hâm mộ."},{"jp":"彼は**感激**のあまり泣き出した。","vi":"Anh ấy xúc động đến bật khóc."}],
  "286": [{"jp":"被害者に**同情**する声が多い。","vi":"Có nhiều tiếng nói đồng cảm với nạn nhân."},{"jp":"**同情**なんかいらない。","vi":"Tôi không cần sự thương hại."}],
  "287": [{"jp":"親の**同意**を得て、留学を決めた。","vi":"Được bố mẹ đồng ý, tôi quyết định đi du học."},{"jp":"その案にはみんなが**同意**した。","vi":"Mọi người đều đồng ý với phương án đó."}],
  "288": [{"jp":"あなたの意見に**同感**です。","vi":"Tôi đồng quan điểm với ý kiến của bạn."},{"jp":"彼の話に多くの人が**同感**した。","vi":"Nhiều người có cùng suy nghĩ với câu chuyện của anh ấy."}],
  "289": [{"jp":"二つの国が**対立**している。","vi":"Hai quốc gia đang đối đầu nhau."},{"jp":"会議で意見が**対立**した。","vi":"Ý kiến đã đối lập nhau trong cuộc họp."}],
  "290": [{"jp":"彼は自分の無実を**主張**した。","vi":"Anh ấy khẳng định mình vô tội."},{"jp":"相手の**主張**にも耳を傾けるべきだ。","vi":"Nên lắng nghe cả quan điểm của đối phương."}],
  "291": [{"jp":"組合は会社に賃上げを**要求**した。","vi":"Công đoàn đã yêu cầu công ty tăng lương."},{"jp":"客の**要求**にすべて応えるのは難しい。","vi":"Đáp ứng mọi yêu cầu của khách hàng là điều khó."}],
  "292": [{"jp":"まとめて買ったほうが**得**ですよ。","vi":"Mua gộp một lần thì có lợi hơn đấy."},{"jp":"早起きは三文の**得**と言います。","vi":"Người ta nói dậy sớm thì được lợi."}],
  "293": [{"jp":"株で大きな**損**をしてしまった。","vi":"Tôi đã bị lỗ nặng vì chứng khoán."},{"jp":"このチャンスを逃すと**損**ですよ。","vi":"Bỏ lỡ cơ hội này là thiệt đấy."}],
  "294": [{"jp":"明日の試合で**勝負**をつけよう。","vi":"Hãy phân thắng bại trong trận đấu ngày mai."},{"jp":"彼は**勝負**にこだわらない性格だ。","vi":"Anh ấy là người không câu nệ chuyện hơn thua."},{"jp":"どちらが速いか**勝負**しよう。","vi":"Thi xem ai nhanh hơn nào."}],
  "295": [{"jp":"川の水が**勢い**よく流れている。","vi":"Nước sông đang chảy cuồn cuộn."},{"jp":"あのチームは今、**勢い**がある。","vi":"Đội đó hiện đang có khí thế mạnh."},{"jp":"その場の**勢い**で言ってしまった。","vi":"Tôi đã lỡ nói ra theo cảm xúc lúc đó."}],
  "296": [{"jp":"工場でガスが**爆発**した。","vi":"Khí ga đã phát nổ tại nhà máy."},{"jp":"ついに彼の怒りが**爆発**した。","vi":"Cuối cùng cơn giận của anh ấy đã bùng nổ."}],
  "297": [{"jp":"日本は自然**災害**が多い国だ。","vi":"Nhật Bản là đất nước có nhiều thiên tai."},{"jp":"**災害**に備えて水を用意しておく。","vi":"Chuẩn bị sẵn nước để phòng thiên tai."}],
  "298": [{"jp":"**天候**が悪いため、試合は中止です。","vi":"Do thời tiết xấu nên trận đấu bị hủy."},{"jp":"山の**天候**は変わりやすい。","vi":"Thời tiết trên núi dễ thay đổi."}],
  "299": [{"jp":"冬は空気が**乾燥**している。","vi":"Mùa đông không khí khô hanh."},{"jp":"洗濯物を**乾燥**機に入れた。","vi":"Tôi đã cho quần áo vào máy sấy."},{"jp":"肌の**乾燥**が気になる。","vi":"Tôi lo về tình trạng da bị khô."}],
  "300": [{"jp":"今夜は流れ星が**観測**できるそうだ。","vi":"Nghe nói tối nay có thể quan sát sao băng."},{"jp":"気象台が雨量を**観測**している。","vi":"Đài khí tượng đang quan trắc lượng mưa."},{"jp":"それは希望的**観測**にすぎない。","vi":"Đó chỉ là dự đoán mang tính mong muốn mà thôi."}],
  "301": [{"jp":"冬山で登山者が**遭難**した。","vi":"Người leo núi đã gặp nạn trên núi mùa đông."},{"jp":"**遭難**した船の救助が続いている。","vi":"Việc cứu hộ con tàu gặp nạn vẫn đang tiếp tục."}],
  "302": [{"jp":"台風が南の海上で**発生**した。","vi":"Bão đã hình thành trên biển phía nam."},{"jp":"システムにトラブルが**発生**しました。","vi":"Hệ thống đã phát sinh sự cố."}],
  "303": [{"jp":"主人公が舞台に**登場**した。","vi":"Nhân vật chính đã xuất hiện trên sân khấu."},{"jp":"新しいスマホが**登場**した。","vi":"Mẫu điện thoại mới đã ra mắt."}],
  "304": [{"jp":"父の体調はすっかり**回復**した。","vi":"Sức khỏe của bố tôi đã hồi phục hoàn toàn."},{"jp":"景気がなかなか**回復**しない。","vi":"Nền kinh tế mãi không hồi phục."}],
  "305": [{"jp":"被災地に食料を**援助**する。","vi":"Viện trợ lương thực cho vùng bị thiên tai."},{"jp":"親から経済的な**援助**を受けている。","vi":"Tôi đang nhận được sự hỗ trợ tài chính từ bố mẹ."}],
  "306": [{"jp":"車を買ったら**保険**に入ってください。","vi":"Mua xe rồi thì hãy tham gia bảo hiểm."},{"jp":"**保険**証を忘れずに持ってきてください。","vi":"Đừng quên mang theo thẻ bảo hiểm y tế."}],
  "307": [{"jp":"ビールを一本**追加**してください。","vi":"Cho tôi gọi thêm một chai bia."},{"jp":"資料に新しいデータを**追加**した。","vi":"Tôi đã bổ sung dữ liệu mới vào tài liệu."}],
  "308": [{"jp":"基本を覚えれば**応用**がきく。","vi":"Nắm được cơ bản thì có thể ứng dụng linh hoạt."},{"jp":"この技術は医療にも**応用**されている。","vi":"Kỹ thuật này cũng được ứng dụng trong y tế."}],
  "309": [{"jp":"試験の**解答**を用紙に書いてください。","vi":"Hãy viết đáp án bài thi vào giấy."},{"jp":"アンケートへのご**回答**をお願いします。","vi":"Xin vui lòng trả lời bảng khảo sát."},{"jp":"質問に対する**回答**がまだ来ない。","vi":"Vẫn chưa có câu trả lời cho câu hỏi."}],
  "310": [{"jp":"会議で**結論**が出なかった。","vi":"Cuộc họp đã không đi đến kết luận."},{"jp":"急いで**結論**を出す必要はない。","vi":"Không cần vội đưa ra kết luận."}],
  "311": [{"jp":"何かいい**案**はありませんか。","vi":"Có ý tưởng nào hay không?"},{"jp":"部長が私の**案**を採用してくれた。","vi":"Trưởng phòng đã chấp nhận phương án của tôi."}],
  "312": [{"jp":"うるさくて勉強に**集中**できない。","vi":"Ồn quá nên tôi không thể tập trung học."},{"jp":"人口が都市に**集中**している。","vi":"Dân số đang tập trung vào các thành phố."}],
  "313": [{"jp":"公私の**区別**をつけるべきだ。","vi":"Nên phân biệt rõ việc công và việc tư."},{"jp":"双子なので**区別**がつかない。","vi":"Vì là sinh đôi nên không phân biệt được."}],
  "314": [{"jp":"性別による**差別**は許されない。","vi":"Không thể chấp nhận sự phân biệt đối xử theo giới tính."},{"jp":"人を外見で**差別**してはいけない。","vi":"Không được phân biệt đối xử với người khác qua vẻ bề ngoài."}],
  "315": [{"jp":"駅と学校の**中間**に公園がある。","vi":"Có một công viên ở giữa nhà ga và trường học."},{"jp":"来週、**中間**試験があります。","vi":"Tuần sau có kỳ thi giữa kỳ."},{"jp":"二人の意見の**中間**をとろう。","vi":"Hãy lấy điểm dung hòa giữa ý kiến của hai người."}],
  "316": [{"jp":"駅とは**逆**の方向に歩いてしまった。","vi":"Tôi đã đi bộ ngược hướng với nhà ga."},{"jp":"期待とは**逆**の結果になった。","vi":"Kết quả lại trái ngược với kỳ vọng."}],
  "317": [{"jp":"ここが混んでいたら、**よそ**へ行こう。","vi":"Nếu chỗ này đông thì đi chỗ khác thôi."},{"jp":"**よそ**の家ではお行儀よくしなさい。","vi":"Ở nhà người khác thì phải cư xử lễ phép."}],
  "318": [{"jp":"**外**に質問はありませんか。","vi":"Còn câu hỏi nào khác không?"},{"jp":"この**外**にも問題がいくつかある。","vi":"Ngoài điều này ra còn vài vấn đề khác nữa."}],
  "319": [{"jp":"川が二つの町の**境**になっている。","vi":"Con sông là ranh giới giữa hai thị trấn."},{"jp":"生死の**境**をさまよった。","vi":"Đã từng lơ lửng giữa ranh giới sống và chết."}],
  "320": [{"jp":"四月**半ば**に桜が満開になった。","vi":"Hoa anh đào nở rộ vào giữa tháng Tư."},{"jp":"彼は話の**半ば**で席を立った。","vi":"Anh ấy rời ghế giữa chừng câu chuyện."},{"jp":"**半ば**あきらめていた。","vi":"Tôi đã gần như bỏ cuộc rồi."}],
  "321": [{"jp":"**普段**は電車で通勤しています。","vi":"Bình thường tôi đi làm bằng tàu điện."},{"jp":"**普段**着のまま出かけた。","vi":"Tôi ra ngoài trong bộ đồ thường ngày."}],
  "322": [{"jp":"**日常**生活に困ることはない。","vi":"Không gặp khó khăn gì trong sinh hoạt hằng ngày."},{"jp":"スマホは**日常**的に使うものだ。","vi":"Điện thoại là thứ dùng hằng ngày."}],
  "323": [{"jp":"この施設は**一般**の人も利用できる。","vi":"Cơ sở này người bình thường cũng có thể sử dụng."},{"jp":"**一般**的に、女性のほうが長生きだ。","vi":"Nói chung, phụ nữ sống thọ hơn."}],
  "324": [{"jp":"時間を守るのは社会人の**常識**だ。","vi":"Đúng giờ là lẽ thường của người đi làm."},{"jp":"彼は少し**常識**に欠けている。","vi":"Anh ấy hơi thiếu hiểu biết thông thường."}],
  "325": [{"jp":"「急がば回れ」という**ことわざ**がある。","vi":"Có câu tục ngữ 'Dục tốc bất đạt'."},{"jp":"この**ことわざ**の意味を知っていますか。","vi":"Bạn có biết ý nghĩa của câu tục ngữ này không?"}],
  "326": [{"jp":"誰にでも意見を言う**権利**がある。","vi":"Ai cũng có quyền nêu ý kiến."},{"jp":"十八歳から選挙の**権利**が与えられる。","vi":"Từ 18 tuổi sẽ được trao quyền bầu cử."}],
  "327": [{"jp":"納税は国民の**義務**です。","vi":"Nộp thuế là nghĩa vụ của công dân."},{"jp":"権利を主張するなら**義務**も果たすべきだ。","vi":"Nếu đòi quyền lợi thì cũng phải làm tròn nghĩa vụ."}],
  "328": [{"jp":"留学が日本語を学ぶ**きっかけ**になった。","vi":"Du học đã trở thành cơ duyên để tôi học tiếng Nhật."},{"jp":"話しかける**きっかけ**がつかめない。","vi":"Tôi không tìm được dịp để bắt chuyện."}],
  "329": [{"jp":"考えるより先に**行動**するタイプだ。","vi":"Tôi là kiểu người hành động trước khi suy nghĩ."},{"jp":"団体で**行動**してください。","vi":"Hãy hành động theo nhóm."}],
  "330": [{"jp":"この部屋は今**使用**中です。","vi":"Phòng này hiện đang được sử dụng."},{"jp":"会場内での携帯電話の**使用**は禁止です。","vi":"Cấm sử dụng điện thoại di động trong hội trường."}],
  "331": [{"jp":"レポートを金曜までに**提出**してください。","vi":"Hãy nộp báo cáo trước thứ Sáu."},{"jp":"国会に法案が**提出**された。","vi":"Dự luật đã được đệ trình lên Quốc hội."}],
  "332": [{"jp":"申し込みの**期限**は明日までです。","vi":"Hạn đăng ký là đến ngày mai."},{"jp":"この牛乳は賞味**期限**が切れている。","vi":"Hộp sữa này đã hết hạn sử dụng."}],
  "333": [{"jp":"雨で運動会が**延期**になった。","vi":"Hội thao bị hoãn lại vì mưa."},{"jp":"出発を来週に**延期**しました。","vi":"Tôi đã hoãn chuyến khởi hành sang tuần sau."}],
  "334": [{"jp":"試合は**延長**戦にもつれ込んだ。","vi":"Trận đấu đã kéo sang hiệp phụ."},{"jp":"ビザの期間を**延長**したい。","vi":"Tôi muốn gia hạn thời hạn visa."}],
  "335": [{"jp":"新幹線で移動時間が**短縮**された。","vi":"Nhờ tàu cao tốc mà thời gian di chuyển được rút ngắn."},{"jp":"今日は**短縮**授業です。","vi":"Hôm nay học rút ngắn giờ."}],
  "336": [{"jp":"このテレビは**映像**がとてもきれいだ。","vi":"Chiếc tivi này hình ảnh rất đẹp."},{"jp":"事故の**映像**がニュースで流れた。","vi":"Hình ảnh vụ tai nạn đã được phát trên bản tin."}],
  "337": [{"jp":"館内での**撮影**はご遠慮ください。","vi":"Xin vui lòng không chụp ảnh trong bảo tàng."},{"jp":"映画の**撮影**が京都で行われた。","vi":"Việc quay phim đã được tiến hành ở Kyoto."}],
  "338": [{"jp":"富士山を**背景**に写真を撮った。","vi":"Tôi đã chụp ảnh với phông nền là núi Phú Sĩ."},{"jp":"事件の**背景**には貧困がある。","vi":"Bối cảnh của vụ án là sự nghèo đói."}],
  "339": [{"jp":"就職して親から**独立**した。","vi":"Đi làm rồi tôi đã độc lập khỏi bố mẹ."},{"jp":"その国は1945年に**独立**した。","vi":"Đất nước đó giành độc lập năm 1945."}],
  "340": [{"jp":"市長選には三人の**候補**者がいる。","vi":"Cuộc bầu cử thị trưởng có ba ứng cử viên."},{"jp":"旅行先の**候補**をいくつか挙げた。","vi":"Tôi đã nêu ra vài địa điểm du lịch dự kiến."},{"jp":"彼女は優勝**候補**の一人だ。","vi":"Cô ấy là một trong những ứng viên vô địch."}],
  "341": [{"jp":"多くの国民がその政策を**支持**している。","vi":"Nhiều người dân ủng hộ chính sách đó."},{"jp":"あの政党の**支持**率が下がった。","vi":"Tỷ lệ ủng hộ của đảng đó đã giảm."},{"jp":"柱が屋根を**支持**している。","vi":"Những cây cột đang chống đỡ mái nhà."}],
  "342": [{"jp":"日曜日に**投票**に行きました。","vi":"Chủ nhật tôi đã đi bỏ phiếu."},{"jp":"クラス委員を**投票**で決めた。","vi":"Chúng tôi quyết định cán bộ lớp bằng cách bỏ phiếu."}],
  "343": [{"jp":"彼は選挙で見事に**当選**した。","vi":"Anh ấy đã trúng cử một cách ngoạn mục."},{"jp":"宝くじが**当選**したら何をしますか。","vi":"Nếu trúng xổ số thì bạn sẽ làm gì?"}],
  "344": [{"jp":"**抽選**で十名様にプレゼントします。","vi":"Sẽ tặng quà cho 10 người qua bốc thăm."},{"jp":"コンサートのチケットは**抽選**です。","vi":"Vé buổi hòa nhạc được phân bằng cách rút thăm."}],
  "345": [{"jp":"駅前でチラシを**配布**している。","vi":"Người ta đang phát tờ rơi trước nhà ga."},{"jp":"会議の資料を全員に**配布**した。","vi":"Tôi đã phát tài liệu cuộc họp cho mọi người."}],
  "346": [{"jp":"彼はフライングで**失格**になった。","vi":"Anh ấy bị truất quyền thi đấu vì xuất phát sớm."},{"jp":"こんなことでは親として**失格**だ。","vi":"Thế này thì không xứng đáng làm cha mẹ."}],
  "347": [{"jp":"**余暇**を利用して絵を習っている。","vi":"Tôi tận dụng thời gian rảnh để học vẽ."},{"jp":"**余暇**の過ごし方は人それぞれだ。","vi":"Mỗi người có cách sử dụng thời gian rảnh khác nhau."}],
  "348": [{"jp":"学校の**行事**に親も参加した。","vi":"Phụ huynh cũng tham gia sự kiện của trường."},{"jp":"お正月は日本の大切な**行事**だ。","vi":"Tết là lễ hội quan trọng của Nhật Bản."}],
  "349": [{"jp":"**理想**の結婚相手はどんな人ですか。","vi":"Người bạn đời lý tưởng của bạn là người như thế nào?"},{"jp":"**理想**と現実は違う。","vi":"Lý tưởng và thực tế thì khác nhau."}],
  "350": [{"jp":"夢ばかり見ないで**現実**を見なさい。","vi":"Đừng chỉ mơ mộng, hãy nhìn vào thực tế."},{"jp":"**現実**には、そんなにうまくいかない。","vi":"Trên thực tế, mọi chuyện không suôn sẻ như vậy."}],
  "351": [{"jp":"農業を**体験**するツアーに参加した。","vi":"Tôi đã tham gia tour trải nghiệm làm nông."},{"jp":"それは貴重な**体験**だった。","vi":"Đó là một trải nghiệm quý giá."}],
  "352": [{"jp":"子供のころはよく**空想**にふけった。","vi":"Hồi nhỏ tôi hay chìm đắm trong mơ mộng."},{"jp":"これは**空想**上の生き物です。","vi":"Đây là sinh vật tưởng tượng."}],
  "353": [{"jp":"**実物**は写真よりずっと大きかった。","vi":"Đồ thật lớn hơn nhiều so với trong ảnh."},{"jp":"**実物**を見てから買うつもりだ。","vi":"Tôi định xem tận mắt đồ thật rồi mới mua."}],
  "354": [{"jp":"長年の夢がついに**実現**した。","vi":"Ước mơ nhiều năm cuối cùng đã thành hiện thực."},{"jp":"その計画を**実現**するのは難しい。","vi":"Thực hiện kế hoạch đó là điều khó."}],
  "355": [{"jp":"来月、全国で調査が**実施**される。","vi":"Tháng sau cuộc khảo sát sẽ được tiến hành trên toàn quốc."},{"jp":"新しい制度を**実施**することになった。","vi":"Đã quyết định áp dụng chế độ mới."}],
  "356": [{"jp":"先生の**許可**を得て早退した。","vi":"Tôi được thầy cho phép nên về sớm."},{"jp":"**許可**なく入らないでください。","vi":"Xin đừng vào khi chưa được phép."}],
  "357": [{"jp":"クラス**全体**で意見をまとめた。","vi":"Cả lớp đã tổng hợp ý kiến."},{"jp":"**全体**的にいい出来だ。","vi":"Nhìn chung làm khá tốt."}],
  "358": [{"jp":"この**部分**をもう一度説明してください。","vi":"Xin hãy giải thích lại phần này một lần nữa."},{"jp":"壊れた**部分**だけ交換した。","vi":"Tôi chỉ thay phần bị hỏng."}],
  "359": [{"jp":"書類の形式を**統一**しましょう。","vi":"Hãy thống nhất định dạng hồ sơ."},{"jp":"その国は百年前に**統一**された。","vi":"Đất nước đó đã được thống nhất từ 100 năm trước."}],
  "360": [{"jp":"写真を**拡大**して印刷した。","vi":"Tôi phóng to ảnh rồi in ra."},{"jp":"会社は海外へ事業を**拡大**した。","vi":"Công ty đã mở rộng kinh doanh ra nước ngoài."}],
  "361": [{"jp":"コピーを70%に**縮小**してください。","vi":"Hãy thu nhỏ bản sao xuống 70%."},{"jp":"不況で事業を**縮小**した。","vi":"Vì suy thoái nên đã thu hẹp kinh doanh."}],
  "362": [{"jp":"朝八時に駅前に**集合**してください。","vi":"Hãy tập trung trước nhà ga lúc 8 giờ sáng."},{"jp":"**集合**場所を確認しておこう。","vi":"Hãy xác nhận trước địa điểm tập trung."}],
  "363": [{"jp":"駅はどちらの**方向**ですか。","vi":"Nhà ga ở hướng nào vậy?"},{"jp":"将来の**方向**がまだ決まらない。","vi":"Tôi vẫn chưa định hướng được tương lai."}],
  "364": [{"jp":"バスは十分**間隔**で来ます。","vi":"Xe buýt đến cách nhau 10 phút."},{"jp":"前の車との**間隔**をあけて運転する。","vi":"Lái xe giữ khoảng cách với xe phía trước."}],
  "365": [{"jp":"道の**脇**に車を止めた。","vi":"Tôi đỗ xe bên lề đường."},{"jp":"本を**脇**に抱えて歩く。","vi":"Đi bộ với cuốn sách kẹp dưới nách."},{"jp":"体温計を**脇**にはさんでください。","vi":"Hãy kẹp nhiệt kế vào nách."}],
  "366": [{"jp":"この電車は次の駅を**通過**します。","vi":"Chuyến tàu này sẽ chạy qua ga tiếp theo mà không dừng."},{"jp":"法案が国会を**通過**した。","vi":"Dự luật đã được Quốc hội thông qua."}],
  "367": [{"jp":"バスで会場へ**移動**します。","vi":"Chúng ta sẽ di chuyển đến hội trường bằng xe buýt."},{"jp":"机を窓のそばに**移動**した。","vi":"Tôi đã dời cái bàn ra cạnh cửa sổ."}],
  "368": [{"jp":"地震で電車が**停止**した。","vi":"Tàu điện dừng lại do động đất."},{"jp":"彼は三日間の出場**停止**になった。","vi":"Anh ấy bị đình chỉ thi đấu ba ngày."}],
  "369": [{"jp":"最近、視力が**低下**してきた。","vi":"Gần đây thị lực của tôi bị giảm sút."},{"jp":"夜になって気温が**低下**した。","vi":"Về đêm nhiệt độ giảm xuống."}],
  "370": [{"jp":"荷物の重さが制限を**超過**した。","vi":"Trọng lượng hành lý đã vượt quá giới hạn."},{"jp":"予算を三万円**超過**してしまった。","vi":"Đã vượt ngân sách 30.000 yên."},{"jp":"会議が時間を**超過**した。","vi":"Cuộc họp đã kéo dài quá giờ."}],
  "371": [{"jp":"彼はいすから**立ち上がった**。","vi":"Anh ấy đứng dậy khỏi ghế."},{"jp":"住民たちが反対運動に**立ち上がった**。","vi":"Cư dân đã đứng lên phản đối."}],
  "372": [{"jp":"合格の知らせに**飛び上がって**喜んだ。","vi":"Nghe tin đỗ, tôi nhảy cẫng lên vì vui sướng."},{"jp":"鳥が空へ**飛び上がった**。","vi":"Con chim bay vút lên trời."},{"jp":"大きな音に驚いて**飛び上がった**。","vi":"Tôi giật bắn mình vì tiếng động lớn."}],
  "373": [{"jp":"霧の中に山の姿が**浮かび上がった**。","vi":"Bóng dáng ngọn núi hiện lên trong sương mù."},{"jp":"捜査で新たな事実が**浮かび上がった**。","vi":"Qua điều tra, sự thật mới đã lộ ra."}],
  "374": [{"jp":"風でほこりが**舞い上がった**。","vi":"Gió làm bụi bay tung lên."},{"jp":"ほめられて、すっかり**舞い上がって**しまった。","vi":"Được khen nên tôi lâng lâng bay bổng."}],
  "375": [{"jp":"火は一気に**燃え上がった**。","vi":"Ngọn lửa bùng cháy lên trong chớp mắt."},{"jp":"二人の恋が**燃え上がった**。","vi":"Tình yêu của hai người bùng cháy."}],
  "376": [{"jp":"パーティーはとても**盛り上がった**。","vi":"Bữa tiệc rất sôi động."},{"jp":"決勝戦で会場が**盛り上がって**いる。","vi":"Hội trường đang sôi sục vì trận chung kết."},{"jp":"地面が**盛り上がって**いる。","vi":"Mặt đất đang nhô lên."}],
  "377": [{"jp":"会場から拍手が**沸き上がった**。","vi":"Tiếng vỗ tay vang dội khắp hội trường."},{"jp":"怒りが**沸き上がって**きた。","vi":"Cơn giận trào dâng lên."}],
  "378": [{"jp":"台風が過ぎて空が**晴れ上がった**。","vi":"Bão qua đi, bầu trời trong xanh trở lại."},{"jp":"今日は雲一つなく**晴れ上がって**いる。","vi":"Hôm nay trời quang đãng không một gợn mây."}],
  "379": [{"jp":"怖い話を聞いて**震え上がった**。","vi":"Nghe chuyện ma, tôi run bắn cả người."},{"jp":"寒さに**震え上がる**。","vi":"Run cầm cập vì lạnh."}],
  "380": [{"jp":"先生に怒鳴られて**縮み上がった**。","vi":"Bị thầy quát, tôi co rúm người lại."},{"jp":"寒さで体が**縮み上がる**。","vi":"Người co quắp lại vì lạnh."}],
  "381": [{"jp":"日照りで池が**干上がった**。","vi":"Do hạn hán, cái ao đã khô cạn."},{"jp":"仕事がなくて、あごが**干上がり**そうだ。","vi":"Không có việc làm, sắp chết đói đến nơi."}],
  "382": [{"jp":"やっと作品が**でき上がった**。","vi":"Cuối cùng tác phẩm cũng đã hoàn thành."},{"jp":"料理が**でき上がったら**呼んでね。","vi":"Nấu xong thì gọi mình nhé."}],
  "383": [{"jp":"重い箱を一人で**持ち上げた**。","vi":"Tôi đã một mình nhấc cái hộp nặng lên."},{"jp":"彼はみんなに**持ち上げられて**いい気になった。","vi":"Anh ta được mọi người tâng bốc nên đắc ý."}],
  "384": [{"jp":"夜空を**見上げる**と星がきれいだった。","vi":"Ngước nhìn bầu trời đêm, sao thật đẹp."},{"jp":"彼の努力は**見上げた**ものだ。","vi":"Sự nỗ lực của anh ấy thật đáng khâm phục."}],
  "385": [{"jp":"机の上に本が**積み上げて**ある。","vi":"Sách được chất đống trên bàn."},{"jp":"長年**積み上げた**信頼を失った。","vi":"Đã đánh mất sự tin tưởng gây dựng bao năm."}],
  "386": [{"jp":"夏祭りで花火が**打ち上げられた**。","vi":"Pháo hoa được bắn lên trong lễ hội mùa hè."},{"jp":"人工衛星が**打ち上げられた**。","vi":"Vệ tinh nhân tạo đã được phóng lên."},{"jp":"仕事が終わったらみんなで**打ち上げ**をしよう。","vi":"Xong việc thì cả nhóm cùng tiệc mừng hoàn thành nhé."}],
  "387": [{"jp":"パソコンを**立ち上げて**ください。","vi":"Hãy khởi động máy tính."},{"jp":"友人と新しい会社を**立ち上げた**。","vi":"Tôi đã cùng bạn thành lập công ty mới."}],
  "388": [{"jp":"今日の仕事は早めに**切り上げよう**。","vi":"Hôm nay hãy kết thúc công việc sớm thôi."},{"jp":"小数点以下を**切り上げる**。","vi":"Làm tròn lên phần thập phân."}],
  "389": [{"jp":"出発の時間を一時間**繰り上げた**。","vi":"Đã dời giờ khởi hành sớm lên một tiếng."},{"jp":"欠員が出て補欠が**繰り上げ**当選した。","vi":"Có chỗ trống nên người dự bị được đôn lên trúng cử."}],
  "390": [{"jp":"床をピカピカに**磨き上げた**。","vi":"Tôi đã đánh bóng sàn nhà sáng loáng."},{"jp":"職人が技を**磨き上げる**。","vi":"Người thợ trau dồi tay nghề đến hoàn hảo."}],
  "391": [{"jp":"毎日の練習で体を**鍛え上げた**。","vi":"Tôi đã rèn luyện cơ thể qua luyện tập mỗi ngày."},{"jp":"コーチが選手を**鍛え上げた**。","vi":"Huấn luyện viên đã rèn giũa các tuyển thủ."}],
  "392": [{"jp":"一晩でレポートを**書き上げた**。","vi":"Tôi đã viết xong bản báo cáo trong một đêm."},{"jp":"三年かけて小説を**書き上げた**。","vi":"Mất ba năm để hoàn thành cuốn tiểu thuyết."}],
  "393": [{"jp":"母は一人で五人の子を**育て上げた**。","vi":"Mẹ một mình nuôi lớn năm người con."},{"jp":"彼は若手を一流の職人に**育て上げた**。","vi":"Ông ấy đã đào tạo người trẻ thành thợ hàng đầu."}],
  "394": [{"jp":"名前を**読み上げられた**人は前に出てください。","vi":"Ai được đọc tên xin hãy bước lên phía trước."},{"jp":"先生が合格者を**読み上げた**。","vi":"Thầy giáo đọc to danh sách người đỗ."}],
  "395": [{"jp":"彼の欠点を**数え上げたら**きりがない。","vi":"Kể ra khuyết điểm của anh ta thì không bao giờ hết."},{"jp":"この町の魅力を**数え上げて**みた。","vi":"Tôi thử liệt kê những điểm hấp dẫn của thị trấn này."}],
  "396": [{"jp":"彼は仕事を途中で**投げ出した**。","vi":"Anh ta bỏ dở công việc giữa chừng."},{"jp":"転んでかばんを**投げ出して**しまった。","vi":"Bị ngã nên tôi làm văng cái cặp ra."},{"jp":"足を**投げ出して**座る。","vi":"Ngồi duỗi thẳng chân ra."}],
  "397": [{"jp":"図書館の本は**持ち出し**禁止です。","vi":"Sách thư viện cấm mang ra ngoài."},{"jp":"会社の書類を勝手に**持ち出して**はいけない。","vi":"Không được tự ý mang tài liệu công ty ra ngoài."},{"jp":"彼は昔の話を**持ち出した**。","vi":"Anh ấy lôi chuyện cũ ra nói."}],
  "398": [{"jp":"家賃を払わず、アパートを**追い出された**。","vi":"Không trả tiền nhà nên bị đuổi khỏi căn hộ."},{"jp":"部屋に入ってきた虫を**追い出した**。","vi":"Tôi đuổi con côn trùng bay vào phòng ra ngoài."}],
  "399": [{"jp":"宿題を**放り出して**遊びに行った。","vi":"Bỏ mặc bài tập để đi chơi."},{"jp":"急ブレーキで乗客が**放り出された**。","vi":"Hành khách bị văng ra do phanh gấp."}],
  "400": [{"jp":"この図書館は本を二週間**貸し出して**いる。","vi":"Thư viện này cho mượn sách trong hai tuần."},{"jp":"銀行が企業に資金を**貸し出す**。","vi":"Ngân hàng cho doanh nghiệp vay vốn."}],
  "401": [{"jp":"彼女から本当の理由を**聞き出した**。","vi":"Tôi đã gặng hỏi được lý do thật từ cô ấy."},{"jp":"警察は犯人の居場所を**聞き出そう**とした。","vi":"Cảnh sát cố moi thông tin về nơi ẩn náu của thủ phạm."}],
  "402": [{"jp":"病気の母を散歩に**連れ出した**。","vi":"Tôi dẫn mẹ đang ốm ra ngoài đi dạo."},{"jp":"友達に夜の町へ**連れ出された**。","vi":"Tôi bị bạn kéo ra phố chơi buổi tối."}],
  "403": [{"jp":"押し入れから扇風機を**引っ張り出した**。","vi":"Tôi lôi chiếc quạt máy từ trong tủ âm tường ra."},{"jp":"嫌がる弟を外へ**引っ張り出した**。","vi":"Kéo đứa em không muốn đi ra ngoài."}],
  "404": [{"jp":"猫がかごから**逃げ出した**。","vi":"Con mèo đã chạy trốn khỏi lồng."},{"jp":"つらくても**逃げ出さない**でほしい。","vi":"Dù khó khăn cũng mong bạn đừng bỏ chạy."}],
  "405": [{"jp":"子供が道路に**飛び出して**きた。","vi":"Đứa trẻ lao ra đường."},{"jp":"彼は家を**飛び出した**。","vi":"Anh ấy đã bỏ nhà ra đi."}],
  "406": [{"jp":"問題の原因を**見つけ出した**。","vi":"Đã tìm ra nguyên nhân của vấn đề."},{"jp":"人ごみの中から友達を**見つけ出した**。","vi":"Tôi đã tìm thấy bạn giữa đám đông."}],
  "407": [{"jp":"なくした指輪をやっと**探し出した**。","vi":"Cuối cùng tôi đã tìm ra chiếc nhẫn bị mất."},{"jp":"警察が犯人を**探し出した**。","vi":"Cảnh sát đã truy tìm ra thủ phạm."}],
  "408": [{"jp":"やるべきことを紙に**書き出した**。","vi":"Tôi viết ra giấy những việc cần làm."},{"jp":"大事な点を**書き出して**おこう。","vi":"Hãy ghi ra những điểm quan trọng."}],
  "409": [{"jp":"子供たちがプールに**飛び込んだ**。","vi":"Bọn trẻ nhảy ùm xuống hồ bơi."},{"jp":"彼は芸能界に**飛び込んだ**。","vi":"Anh ấy lao vào giới giải trí."}],
  "410": [{"jp":"発車直前の電車に**駆け込んだ**。","vi":"Tôi chạy vội lên chuyến tàu sắp chạy."},{"jp":"雨が降り出して店に**駆け込んだ**。","vi":"Trời bắt đầu mưa nên tôi chạy vội vào cửa hàng."}],
  "411": [{"jp":"列に**割り込まない**でください。","vi":"Xin đừng chen ngang vào hàng."},{"jp":"人の話に**割り込む**のは失礼だ。","vi":"Chen ngang vào câu chuyện của người khác là bất lịch sự."}],
  "412": [{"jp":"鍵を**差し込んで**回してください。","vi":"Hãy cắm chìa khóa vào rồi xoay."},{"jp":"プラグをコンセントに**差し込んだ**。","vi":"Tôi cắm phích vào ổ điện."},{"jp":"窓から朝日が**差し込んで**いる。","vi":"Ánh nắng ban mai rọi vào qua cửa sổ."}],
  "413": [{"jp":"雨水が壁に**染み込んだ**。","vi":"Nước mưa đã thấm vào tường."},{"jp":"味がよく**染み込んで**おいしい。","vi":"Gia vị ngấm đều nên rất ngon."}],
  "414": [{"jp":"彼は自分の部屋に**引っ込んだ**。","vi":"Anh ấy lui vào phòng riêng."},{"jp":"引退して田舎に**引っ込んだ**。","vi":"Nghỉ hưu rồi lui về sống ở quê."},{"jp":"関係ない人は**引っ込んで**いて。","vi":"Người không liên quan thì tránh ra."}],
  "415": [{"jp":"かばんに荷物を**詰め込んだ**。","vi":"Tôi nhét đồ đạc vào túi."},{"jp":"試験前に知識を**詰め込む**。","vi":"Nhồi nhét kiến thức trước kỳ thi."}],
  "416": [{"jp":"薬を水で**飲み込んだ**。","vi":"Tôi nuốt thuốc cùng với nước."},{"jp":"彼は仕事の要領をすぐ**飲み込んだ**。","vi":"Anh ấy nhanh chóng nắm được cách làm việc."},{"jp":"言いたいことを**飲み込んだ**。","vi":"Tôi đã nuốt lại điều muốn nói."}],
  "417": [{"jp":"新しい家具を部屋に**運び込んだ**。","vi":"Tôi đã chuyển đồ nội thất mới vào phòng."},{"jp":"けが人が病院に**運び込まれた**。","vi":"Người bị thương đã được đưa vào bệnh viện."}],
  "418": [{"jp":"壁に釘を**打ち込んだ**。","vi":"Tôi đóng đinh vào tường."},{"jp":"彼は研究に**打ち込んで**いる。","vi":"Anh ấy đang dốc toàn lực vào nghiên cứu."},{"jp":"データをパソコンに**打ち込む**。","vi":"Nhập dữ liệu vào máy tính."}],
  "419": [{"jp":"彼は全財産を事業に**注ぎ込んだ**。","vi":"Anh ấy đã dồn toàn bộ tài sản vào kinh doanh."},{"jp":"鍋にスープを**注ぎ込む**。","vi":"Đổ súp vào nồi."}],
  "420": [{"jp":"その小説に**引き込まれて**一晩で読んだ。","vi":"Bị cuốn hút vào cuốn tiểu thuyết đó nên tôi đọc hết trong một đêm."},{"jp":"彼を仲間に**引き込もう**。","vi":"Hãy lôi kéo anh ấy vào nhóm mình."},{"jp":"川から水を田んぼに**引き込む**。","vi":"Dẫn nước từ sông vào ruộng."}],
  "421": [{"jp":"予定を手帳に**書き込んだ**。","vi":"Tôi ghi lịch trình vào sổ tay."},{"jp":"ネットの掲示板に**書き込む**。","vi":"Viết bình luận lên diễn đàn mạng."}],
  "422": [{"jp":"機械に服が**巻き込まれた**。","vi":"Quần áo bị cuốn vào máy."},{"jp":"事件に**巻き込まれて**しまった。","vi":"Tôi đã bị liên lụy vào vụ việc."}],
  "423": [{"jp":"犬が羊を囲いに**追い込んだ**。","vi":"Con chó lùa đàn cừu vào chuồng."},{"jp":"会社は倒産に**追い込まれた**。","vi":"Công ty bị dồn đến bờ phá sản."}],
  "424": [{"jp":"店員が客を店に**呼び込んで**いる。","vi":"Nhân viên đang mời gọi khách vào tiệm."},{"jp":"観光客を**呼び込む**ためにイベントを開く。","vi":"Tổ chức sự kiện để thu hút khách du lịch."}],
  "425": [{"jp":"疲れて道に**座り込んで**しまった。","vi":"Mệt quá nên tôi ngồi bệt xuống đường."},{"jp":"住民が役所の前に**座り込んだ**。","vi":"Cư dân ngồi lì trước trụ sở chính quyền."}],
  "426": [{"jp":"風邪で三日間**寝込んだ**。","vi":"Tôi bị cảm nằm liệt giường ba ngày."},{"jp":"疲れてぐっすり**寝込んで**しまった。","vi":"Mệt quá nên tôi ngủ say như chết."}],
  "427": [{"jp":"友達と夜中まで**話し込んだ**。","vi":"Tôi say sưa trò chuyện với bạn đến nửa đêm."},{"jp":"つい**話し込んで**電車に乗り遅れた。","vi":"Mải nói chuyện nên tôi lỡ chuyến tàu."}],
  "428": [{"jp":"質問されると彼は**黙り込んだ**。","vi":"Bị hỏi thì anh ấy im bặt."},{"jp":"二人は**黙り込んだ**まま歩いた。","vi":"Hai người cứ im lặng mà bước đi."}],
  "429": [{"jp":"締め切り前は会社に**泊まり込む**。","vi":"Trước hạn chót thì tôi ở lại qua đêm tại công ty."},{"jp":"母の看病で病院に**泊まり込んだ**。","vi":"Tôi ở lại bệnh viện để chăm mẹ."}],
  "430": [{"jp":"彼は旅館に**住み込んで**働いている。","vi":"Anh ấy làm việc và ăn ở luôn tại nhà trọ."},{"jp":"**住み込み**のアルバイトを探している。","vi":"Tôi đang tìm việc làm thêm có bao ăn ở."}],
  "431": [{"jp":"牛肉を赤ワインで**煮込んだ**。","vi":"Tôi ninh thịt bò với rượu vang đỏ."},{"jp":"カレーは一晩**煮込む**とおいしい。","vi":"Cà ri hầm một đêm sẽ ngon hơn."}],
  "432": [{"jp":"新商品を取引先に**売り込んだ**。","vi":"Tôi đã chào hàng sản phẩm mới cho đối tác."},{"jp":"面接で自分を**売り込む**。","vi":"Quảng bá bản thân trong buổi phỏng vấn."}],
  "433": [{"jp":"友人に**頼み込んで**お金を借りた。","vi":"Tôi nài nỉ bạn để vay tiền."},{"jp":"何度も**頼み込んで**やっと許してもらった。","vi":"Nhờ vả mãi mới được cho phép."}],
  "434": [{"jp":"犬にお座りを**教え込んだ**。","vi":"Tôi đã dạy con chó biết ngồi."},{"jp":"祖母に礼儀を**教え込まれた**。","vi":"Tôi được bà dạy dỗ kỹ về lễ nghĩa."}],
  "435": [{"jp":"家族で旅行の計画を**話し合った**。","vi":"Cả gia đình đã bàn bạc kế hoạch du lịch."},{"jp":"問題はよく**話し合って**解決しよう。","vi":"Hãy trao đổi kỹ để giải quyết vấn đề."}],
  "436": [{"jp":"兄弟が大声で**言い合って**いる。","vi":"Hai anh em đang cãi nhau ầm ĩ."},{"jp":"つまらないことで友達と**言い合い**になった。","vi":"Tôi đã cãi nhau với bạn vì chuyện vặt vãnh."}],
  "437": [{"jp":"昔の仲間と朝まで**語り合った**。","vi":"Tôi đã trò chuyện với bạn cũ đến tận sáng."},{"jp":"将来の夢について**語り合い**ましょう。","vi":"Chúng ta hãy cùng nhau trò chuyện về ước mơ tương lai."}],
  "438": [{"jp":"二人は黙って**見つめ合った**。","vi":"Hai người im lặng nhìn nhau chăm chú."},{"jp":"恋人同士が**見つめ合って**ほほえんでいる。","vi":"Đôi tình nhân nhìn nhau đắm đuối và mỉm cười."}],
  "439": [{"jp":"テーブルを挟んで**向かい合って**座った。","vi":"Chúng tôi ngồi đối diện nhau qua chiếc bàn."},{"jp":"駅と銀行が**向かい合って**いる。","vi":"Nhà ga và ngân hàng nằm đối diện nhau."}],
  "440": [{"jp":"困ったときは**助け合い**ましょう。","vi":"Khi gặp khó khăn hãy giúp đỡ lẫn nhau nhé."},{"jp":"家族で**助け合って**生活している。","vi":"Cả gia đình sống nương tựa, giúp đỡ lẫn nhau."}],
  "441": [{"jp":"一つのケーキを三人で**分け合った**。","vi":"Ba người chia nhau một chiếc bánh."},{"jp":"喜びも悲しみも**分け合う**のが夫婦だ。","vi":"Vợ chồng là cùng nhau sẻ chia cả niềm vui lẫn nỗi buồn."}],
  "442": [{"jp":"みんなでお金を**出し合って**プレゼントを買った。","vi":"Mọi người góp tiền mua quà."},{"jp":"会議でアイデアを**出し合った**。","vi":"Trong cuộc họp, mọi người cùng đóng góp ý tưởng."}],
  "443": [{"jp":"遅刻しないよう全員で**申し合わせた**。","vi":"Mọi người đã thỏa thuận với nhau là không đi muộn."},{"jp":"**申し合わせた**ように皆黒い服で来た。","vi":"Mọi người đều mặc đồ đen như thể đã hẹn trước."}],
  "444": [{"jp":"友達と**誘い合わせて**花火大会に行った。","vi":"Tôi rủ bạn bè cùng đi xem pháo hoa."},{"jp":"近所の人と**誘い合わせて**運動会に参加した。","vi":"Tôi rủ hàng xóm cùng tham gia hội thao."}],
  "445": [{"jp":"電車で偶然先生と**隣り合わせた**。","vi":"Trên tàu tôi tình cờ ngồi cạnh thầy giáo."},{"jp":"二人の家は**隣り合わせて**建っている。","vi":"Nhà của hai người nằm sát cạnh nhau."}],
  "446": [{"jp":"色を上手に**組み合わせる**とおしゃれに見える。","vi":"Phối màu khéo léo sẽ trông sành điệu hơn."},{"jp":"数字と文字を**組み合わせて**パスワードを作る。","vi":"Kết hợp số và chữ để tạo mật khẩu."},{"jp":"部品を**組み合わせて**棚を作った。","vi":"Tôi ghép các bộ phận lại để làm một cái kệ."}],
  "447": [{"jp":"果物を箱に**詰め合わせて**贈った。","vi":"Tôi xếp nhiều loại trái cây vào hộp rồi đem tặng."},{"jp":"お菓子の**詰め合わせ**をもらった。","vi":"Tôi nhận được một hộp bánh kẹo tổng hợp."}],
  "448": [{"jp":"二枚の紙を**重ね合わせて**切る。","vi":"Chồng hai tờ giấy lên nhau rồi cắt."},{"jp":"主人公に自分を**重ね合わせて**読んだ。","vi":"Tôi đọc truyện mà thấy mình như nhân vật chính."}],
  "449": [{"jp":"事故の現場に偶然**居合わせた**。","vi":"Tôi tình cờ có mặt tại hiện trường vụ tai nạn."},{"jp":"その場に**居合わせた**人が救急車を呼んだ。","vi":"Người tình cờ có mặt ở đó đã gọi xe cấp cứu."}],
  "450": [{"jp":"同じバスに昔の友達が**乗り合わせて**いた。","vi":"Bạn cũ tình cờ đi cùng chuyến xe buýt với tôi."},{"jp":"飛行機に**乗り合わせた**人と仲良くなった。","vi":"Tôi đã kết thân với người tình cờ đi cùng chuyến bay."}],
  "451": [{"jp":"今、細かいお金を**持ち合わせて**いない。","vi":"Bây giờ tôi không mang theo tiền lẻ."},{"jp":"彼は優しさと強さを**持ち合わせて**いる。","vi":"Anh ấy có cả sự dịu dàng lẫn sức mạnh."}],
  "452": [{"jp":"電話で営業時間を**問い合わせた**。","vi":"Tôi đã gọi điện hỏi giờ mở cửa."},{"jp":"詳しくは事務所に**問い合わせて**ください。","vi":"Để biết chi tiết, xin vui lòng liên hệ văn phòng."}],
  "453": [{"jp":"答えを解答と**照らし合わせた**。","vi":"Tôi đã đối chiếu câu trả lời với đáp án."},{"jp":"二つの資料を**照らし合わせて**確認する。","vi":"So sánh hai tài liệu để kiểm tra."}],
  "454": [{"jp":"聞き取れなかったので**聞き直した**。","vi":"Vì nghe không rõ nên tôi đã hỏi lại."},{"jp":"名前をもう一度**聞き直して**もいいですか。","vi":"Tôi hỏi lại tên anh một lần nữa được không?"}],
  "455": [{"jp":"間違えたので最初から**やり直した**。","vi":"Vì làm sai nên tôi đã làm lại từ đầu."},{"jp":"人生は何度でも**やり直せる**。","vi":"Cuộc đời có thể làm lại bao nhiêu lần cũng được."}],
  "456": [{"jp":"今忙しいので後で**かけ直します**。","vi":"Bây giờ tôi đang bận nên sẽ gọi lại sau."},{"jp":"電話が切れたので**かけ直した**。","vi":"Điện thoại bị ngắt nên tôi đã gọi lại."}],
  "457": [{"jp":"担当者が留守なので、明日**出直します**。","vi":"Người phụ trách vắng mặt nên mai tôi sẽ quay lại."},{"jp":"失敗したが、一から**出直す**つもりだ。","vi":"Tuy đã thất bại nhưng tôi định làm lại từ đầu."}],
  "458": [{"jp":"父の病状がだいぶ**持ち直した**。","vi":"Bệnh tình của bố tôi đã chuyển biến tốt nhiều."},{"jp":"景気が少しずつ**持ち直して**いる。","vi":"Nền kinh tế đang dần dần hồi phục."}],
  "459": [{"jp":"その計画はもう一度**考え直した**ほうがいい。","vi":"Kế hoạch đó nên suy nghĩ lại một lần nữa."},{"jp":"**考え直して**、別の方法を選んだ。","vi":"Sau khi xem xét lại, tôi đã chọn cách khác."}],
  "460": [{"jp":"会社を辞めようと思ったが、**思い直した**。","vi":"Tôi đã định nghỉ việc nhưng rồi lại đổi ý."},{"jp":"彼女は**思い直して**留学することにした。","vi":"Cô ấy nghĩ lại và quyết định đi du học."}],
  "461": [{"jp":"屋根にテレビの**アンテナ**を付けた。","vi":"Tôi đã lắp ăng-ten tivi trên mái nhà."},{"jp":"**アンテナ**が倒れて映りが悪い。","vi":"Ăng-ten bị đổ nên hình ảnh bị nhiễu."}],
  "462": [{"jp":"電車では**イヤホン**で音楽を聞く。","vi":"Trên tàu tôi nghe nhạc bằng tai nghe."},{"jp":"**イヤホン**を片方なくしてしまった。","vi":"Tôi làm mất một bên tai nghe rồi."}],
  "463": [{"jp":"遠くで救急車の**サイレン**が鳴っている。","vi":"Xa xa có tiếng còi xe cấp cứu đang hú."},{"jp":"正午に工場の**サイレン**が鳴る。","vi":"Đúng trưa, còi hú của nhà máy vang lên."}],
  "464": [{"jp":"掃除機の**コード**が短くて不便だ。","vi":"Dây điện của máy hút bụi ngắn nên bất tiện."},{"jp":"**コード**に足を引っかけて転んだ。","vi":"Tôi vấp phải dây điện và ngã."}],
  "465": [{"jp":"パソコンの**モニター**を大きいものに替えた。","vi":"Tôi đã đổi màn hình máy tính sang loại to hơn."},{"jp":"**モニター**に患者の様子が映っている。","vi":"Tình trạng của bệnh nhân hiện lên trên màn hình."}],
  "466": [{"jp":"ガスの**メーター**を確認する。","vi":"Kiểm tra đồng hồ đo ga."},{"jp":"タクシーの**メーター**がどんどん上がる。","vi":"Đồng hồ tính tiền taxi cứ tăng vùn vụt."}],
  "467": [{"jp":"二人一組の**ペア**になってください。","vi":"Hãy chia thành từng cặp hai người."},{"jp":"夫婦で**ペア**のカップを買った。","vi":"Hai vợ chồng đã mua một cặp cốc đôi."}],
  "468": [{"jp":"音楽の**リズム**に合わせて踊る。","vi":"Nhảy theo nhịp điệu của âm nhạc."},{"jp":"生活の**リズム**が乱れている。","vi":"Nhịp sinh hoạt đang bị đảo lộn."}],
  "469": [{"jp":"日本語の**アクセント**は難しい。","vi":"Ngữ điệu trọng âm tiếng Nhật thật khó."},{"jp":"彼の話し方には関西の**アクセント**がある。","vi":"Cách nói chuyện của anh ấy mang giọng vùng Kansai."},{"jp":"このスカーフが服の**アクセント**になる。","vi":"Chiếc khăn này tạo điểm nhấn cho bộ trang phục."}],
  "470": [{"jp":"子供が**アルファベット**を覚えた。","vi":"Đứa trẻ đã thuộc bảng chữ cái."},{"jp":"名前を**アルファベット**で書いてください。","vi":"Hãy viết tên bằng chữ cái La-tinh."}],
  "471": [{"jp":"メール**アドレス**を教えてください。","vi":"Hãy cho tôi biết địa chỉ email của bạn."},{"jp":"**アドレス**を間違えてメールが届かなかった。","vi":"Tôi ghi nhầm địa chỉ nên email không gửi đến được."}],
  "472": [{"jp":"大事なことは**メモ**しておきましょう。","vi":"Những điều quan trọng hãy ghi chú lại."},{"jp":"机の上に母の**メモ**が置いてあった。","vi":"Trên bàn có tờ ghi chú của mẹ."}],
  "473": [{"jp":"重要な所に**マーク**を付けた。","vi":"Tôi đã đánh dấu vào chỗ quan trọng."},{"jp":"この**マーク**は非常口を示している。","vi":"Ký hiệu này chỉ lối thoát hiểm."}],
  "474": [{"jp":"この本は**イラスト**が多くてわかりやすい。","vi":"Cuốn sách này có nhiều hình minh họa nên dễ hiểu."},{"jp":"彼女はかわいい**イラスト**を描く。","vi":"Cô ấy vẽ tranh minh họa rất dễ thương."}],
  "475": [{"jp":"書類に**サイン**をお願いします。","vi":"Xin vui lòng ký vào giấy tờ."},{"jp":"好きな歌手に**サイン**をもらった。","vi":"Tôi đã xin được chữ ký của ca sĩ yêu thích."},{"jp":"監督が選手に**サイン**を送った。","vi":"Huấn luyện viên ra ám hiệu cho cầu thủ."}],
  "476": [{"jp":"彼は一夜にして**スター**になった。","vi":"Anh ấy trở thành ngôi sao chỉ sau một đêm."},{"jp":"映画**スター**が空港に到着した。","vi":"Ngôi sao điện ảnh đã đến sân bay."}],
  "477": [{"jp":"観客の**アンコール**に応えて、もう一曲歌った。","vi":"Đáp lại lời yêu cầu của khán giả, ca sĩ hát thêm một bài."},{"jp":"コンサートの最後に**アンコール**が起こった。","vi":"Cuối buổi hòa nhạc, khán giả hô vang đòi hát thêm."}],
  "478": [{"jp":"この車は今年の新しい**モデル**だ。","vi":"Chiếc xe này là mẫu mới của năm nay."},{"jp":"姉はファッション**モデル**をしている。","vi":"Chị tôi làm người mẫu thời trang."},{"jp":"この小説の主人公には**モデル**がいる。","vi":"Nhân vật chính của tiểu thuyết này có nguyên mẫu ngoài đời."}],
  "479": [{"jp":"化粧品の**サンプル**をもらった。","vi":"Tôi được tặng hàng mẫu mỹ phẩm."},{"jp":"店の前に料理の**サンプル**が並んでいる。","vi":"Trước cửa hàng có bày các mẫu món ăn."}],
  "480": [{"jp":"彼女は**スタイル**がいい。","vi":"Cô ấy có vóc dáng đẹp."},{"jp":"自分の**スタイル**で仕事を進める。","vi":"Tôi làm việc theo phong cách của riêng mình."},{"jp":"最新の**スタイル**の服が人気だ。","vi":"Quần áo theo kiểu mới nhất đang được ưa chuộng."}],
  "481": [{"jp":"最近**ウエスト**が太くなった。","vi":"Dạo này vòng eo của tôi to ra."},{"jp":"このズボンは**ウエスト**がきつい。","vi":"Cái quần này bị chật phần eo."}],
  "482": [{"jp":"この料理は**カロリー**が高い。","vi":"Món ăn này nhiều calo."},{"jp":"ダイエット中なので**カロリー**を気にしている。","vi":"Đang ăn kiêng nên tôi để ý đến lượng calo."}],
  "483": [{"jp":"予算を一万円**オーバー**してしまった。","vi":"Tôi đã vượt ngân sách mười nghìn yên."},{"jp":"彼の話はいつも**オーバー**だ。","vi":"Anh ta lúc nào cũng nói quá lên."},{"jp":"会議が時間を**オーバー**した。","vi":"Cuộc họp đã kéo dài quá giờ."}],
  "484": [{"jp":"怒りを**コントロール**するのは難しい。","vi":"Kiểm soát cơn giận thật khó."},{"jp":"このピッチャーはボールの**コントロール**がいい。","vi":"Cầu thủ ném bóng này điều khiển bóng rất tốt."}],
  "485": [{"jp":"この先は急な**カーブ**が続く。","vi":"Phía trước là những khúc cua gấp liên tiếp."},{"jp":"ボールが大きく**カーブ**した。","vi":"Quả bóng đã đi theo đường cong lớn."}],
  "486": [{"jp":"初心者向けの**コース**に申し込んだ。","vi":"Tôi đã đăng ký khóa học dành cho người mới bắt đầu."},{"jp":"マラソンの**コース**を下見した。","vi":"Tôi đã đi xem trước lộ trình chạy marathon."},{"jp":"ディナーは五千円の**コース**にした。","vi":"Bữa tối tôi đã chọn set món giá năm nghìn yên."}],
  "487": [{"jp":"ボートの**レース**で優勝した。","vi":"Tôi đã vô địch cuộc đua thuyền."},{"jp":"自動車**レース**を見に行った。","vi":"Tôi đã đi xem đua ô tô."}],
  "488": [{"jp":"前半は我がチームが二点**リード**している。","vi":"Hiệp một đội chúng tôi đang dẫn trước hai điểm."},{"jp":"彼が会議を上手に**リード**した。","vi":"Anh ấy đã dẫn dắt cuộc họp rất khéo."}],
  "489": [{"jp":"彼はクラスで**トップ**の成績だ。","vi":"Cậu ấy có thành tích đứng đầu lớp."},{"jp":"会社の**トップ**が記者会見をした。","vi":"Người đứng đầu công ty đã tổ chức họp báo."}],
  "490": [{"jp":"彼は最初に**ゴール**した。","vi":"Anh ấy đã về đích đầu tiên."},{"jp":"試合終了直前に**ゴール**を決めた。","vi":"Ngay trước khi hết giờ, anh ấy đã ghi bàn."},{"jp":"結婚は人生の**ゴール**ではない。","vi":"Kết hôn không phải là đích đến của cuộc đời."}],
  "491": [{"jp":"一次試験を無事に**パス**した。","vi":"Tôi đã vượt qua kỳ thi vòng một suôn sẻ."},{"jp":"仲間にボールを**パス**する。","vi":"Chuyền bóng cho đồng đội."},{"jp":"今日の飲み会は**パス**します。","vi":"Buổi nhậu hôm nay tôi xin kiếu."}],
  "492": [{"jp":"試合では**ベスト**を尽くします。","vi":"Tôi sẽ cố gắng hết sức trong trận đấu."},{"jp":"自己**ベスト**の記録を出した。","vi":"Tôi đã lập thành tích tốt nhất của bản thân."}],
  "493": [{"jp":"ガソリンは**レギュラー**を入れてください。","vi":"Hãy đổ xăng loại thường."},{"jp":"やっと**レギュラー**の選手になれた。","vi":"Cuối cùng tôi đã trở thành cầu thủ chính thức."},{"jp":"彼はその番組の**レギュラー**だ。","vi":"Anh ấy là gương mặt thường xuyên của chương trình đó."}],
  "494": [{"jp":"**コーチ**の指導で上手になった。","vi":"Nhờ sự chỉ dạy của huấn luyện viên mà tôi đã giỏi lên."},{"jp":"引退後はテニスの**コーチ**をしている。","vi":"Sau khi giải nghệ, anh ấy làm huấn luyện viên quần vợt."}],
  "495": [{"jp":"彼はサッカー部の**キャプテン**だ。","vi":"Cậu ấy là đội trưởng câu lạc bộ bóng đá."},{"jp":"**キャプテン**がチームをまとめている。","vi":"Đội trưởng gắn kết cả đội."}],
  "496": [{"jp":"大学で写真の**サークル**に入った。","vi":"Ở đại học tôi đã tham gia câu lạc bộ nhiếp ảnh."},{"jp":"地面に大きな**サークル**を描いた。","vi":"Tôi đã vẽ một vòng tròn lớn trên mặt đất."}],
  "497": [{"jp":"大学の**キャンパス**はとても広い。","vi":"Khuôn viên trường đại học rất rộng."},{"jp":"**キャンパス**内にコンビニがある。","vi":"Trong khuôn viên trường có cửa hàng tiện lợi."}],
  "498": [{"jp":"新入生の**オリエンテーション**に出席した。","vi":"Tôi đã tham dự buổi định hướng cho tân sinh viên."},{"jp":"入社後、一週間の**オリエンテーション**がある。","vi":"Sau khi vào công ty có một tuần định hướng."}],
  "499": [{"jp":"来年から**カリキュラム**が変わる。","vi":"Từ năm sau chương trình giảng dạy sẽ thay đổi."},{"jp":"この学校は**カリキュラム**が充実している。","vi":"Trường này có chương trình học rất phong phú."}],
  "500": [{"jp":"コンサートの**プログラム**を受け取った。","vi":"Tôi nhận được tờ chương trình buổi hòa nhạc."},{"jp":"新しい研修**プログラム**が始まった。","vi":"Chương trình đào tạo mới đã bắt đầu."},{"jp":"パソコンの**プログラム**を作る。","vi":"Viết chương trình máy tính."}],
  "501": [{"jp":"週に一回ピアノの**レッスン**を受けている。","vi":"Tôi học piano mỗi tuần một buổi."},{"jp":"今日の**レッスン**はここまでです。","vi":"Bài học hôm nay đến đây là hết."}],
  "502": [{"jp":"社員旅行で**レクリエーション**を楽しんだ。","vi":"Chúng tôi vui chơi giải trí trong chuyến du lịch công ty."},{"jp":"**レクリエーション**の時間にゲームをした。","vi":"Trong giờ sinh hoạt giải trí, chúng tôi đã chơi trò chơi."}],
  "503": [{"jp":"夏は**レジャー**に出かける人が多い。","vi":"Mùa hè có nhiều người đi chơi giải trí."},{"jp":"**レジャー**施設が新しくできた。","vi":"Một khu vui chơi giải trí mới đã được xây dựng."}],
  "504": [{"jp":"**ガイド**の説明を聞きながら見学した。","vi":"Chúng tôi vừa tham quan vừa nghe hướng dẫn viên giải thích."},{"jp":"京都の**ガイド**ブックを買った。","vi":"Tôi đã mua sách hướng dẫn du lịch Kyoto."}],
  "505": [{"jp":"もうすぐスキーの**シーズン**だ。","vi":"Sắp đến mùa trượt tuyết rồi."},{"jp":"観光**シーズン**はホテルが高い。","vi":"Vào mùa du lịch giá khách sạn cao."}],
  "506": [{"jp":"事故で電車の**ダイヤ**が乱れている。","vi":"Do tai nạn, lịch chạy tàu bị xáo trộn."},{"jp":"来月から**ダイヤ**が改正される。","vi":"Từ tháng sau lịch chạy tàu sẽ được điều chỉnh."}],
  "507": [{"jp":"**ウイークデー**は仕事で忙しい。","vi":"Ngày thường trong tuần tôi bận làm việc."},{"jp":"**ウイークデー**なら店はすいている。","vi":"Nếu là ngày thường thì cửa hàng vắng khách."}],
  "508": [{"jp":"あのホテルは**サービス**がいい。","vi":"Khách sạn đó phục vụ tốt."},{"jp":"コーヒーは**サービス**です。","vi":"Cà phê là miễn phí ạ."},{"jp":"新しい**サービス**が始まった。","vi":"Dịch vụ mới đã bắt đầu."}],
  "509": [{"jp":"**アルコール**で手を消毒する。","vi":"Sát khuẩn tay bằng cồn."},{"jp":"私は**アルコール**に弱い。","vi":"Tôi uống rượu bia kém."}],
  "510": [{"jp":"ケーキの**デコレーション**がきれいだ。","vi":"Phần trang trí của chiếc bánh thật đẹp."},{"jp":"クリスマスの**デコレーション**を飾った。","vi":"Tôi đã treo đồ trang trí Giáng sinh."}],
  "511": [{"jp":"富士山は日本で**最も**高い山だ。","vi":"Núi Phú Sĩ là ngọn núi cao nhất Nhật Bản."},{"jp":"これが**最も**大切なことです。","vi":"Đây là điều quan trọng nhất."}],
  "512": [{"jp":"工事は**ほぼ**終わった。","vi":"Công trình gần như đã xong."},{"jp":"二人は**ほぼ**同じ年齢だ。","vi":"Hai người gần như bằng tuổi nhau."}],
  "513": [{"jp":"彼は**相当**疲れているようだ。","vi":"Có vẻ anh ấy khá mệt."},{"jp":"百万円に**相当**する賞品が当たった。","vi":"Tôi trúng giải thưởng trị giá tương đương một triệu yên."}],
  "514": [{"jp":"今日は**割合**暖かい。","vi":"Hôm nay tương đối ấm."},{"jp":"このクラスは女性の**割合**が高い。","vi":"Lớp này có tỉ lệ nữ cao."}],
  "515": [{"jp":"英語なら**多少**話せます。","vi":"Tiếng Anh thì tôi nói được chút ít."},{"jp":"**多少**高くても、品質のいい物を買う。","vi":"Dù đắt hơn một chút, tôi vẫn mua đồ chất lượng tốt."}],
  "516": [{"jp":"**少々**お待ちください。","vi":"Xin vui lòng đợi một chút."},{"jp":"塩を**少々**加えてください。","vi":"Hãy cho thêm một chút muối."}],
  "517": [{"jp":"宿題は**すべて**終わった。","vi":"Tôi đã làm xong toàn bộ bài tập."},{"jp":"財産の**すべて**を失った。","vi":"Anh ta đã mất toàn bộ tài sản."}],
  "518": [{"jp":"火事で**何もかも**なくしてしまった。","vi":"Vì hỏa hoạn mà tôi đã mất hết mọi thứ."},{"jp":"**何もかも**嫌になった。","vi":"Tôi chán ghét tất cả mọi thứ."}],
  "519": [{"jp":"時間は**たっぷり**あるから急がなくていい。","vi":"Thời gian còn nhiều nên không cần vội."},{"jp":"クリームを**たっぷり**塗る。","vi":"Phết thật nhiều kem."}],
  "520": [{"jp":"**できるだけ**早く返事をください。","vi":"Hãy trả lời tôi càng sớm càng tốt."},{"jp":"**できるだけ**のことはしました。","vi":"Tôi đã làm hết sức có thể."}],
  "521": [{"jp":"風が**次第に**強くなってきた。","vi":"Gió dần dần mạnh lên."},{"jp":"新しい生活に**次第に**慣れてきた。","vi":"Tôi dần quen với cuộc sống mới."}],
  "522": [{"jp":"病気は**徐々に**良くなっている。","vi":"Bệnh đang dần dần khá lên."},{"jp":"スピードを**徐々に**上げる。","vi":"Tăng tốc độ từ từ."}],
  "523": [{"jp":"雨は夜になって**さらに**強くなった。","vi":"Về đêm mưa càng nặng hạt hơn."},{"jp":"**さらに**詳しく説明します。","vi":"Tôi sẽ giải thích chi tiết hơn nữa."}],
  "524": [{"jp":"これから**一層**努力します。","vi":"Từ nay tôi sẽ nỗ lực hơn nữa."},{"jp":"雨で寒さが**一層**厳しくなった。","vi":"Vì mưa nên trời càng lạnh hơn."}],
  "525": [{"jp":"髪を切って**一段と**きれいになったね。","vi":"Cắt tóc xong, trông bạn đẹp hẳn lên đấy."},{"jp":"今朝は**一段と**冷え込んだ。","vi":"Sáng nay trời lạnh hơn hẳn."}],
  "526": [{"jp":"**より**良いサービスを目指します。","vi":"Chúng tôi hướng tới dịch vụ tốt hơn."},{"jp":"**より**多くの人に知ってもらいたい。","vi":"Tôi muốn nhiều người biết đến hơn."}],
  "527": [{"jp":"長い間迷ったが、**結局**行かなかった。","vi":"Tôi đã phân vân lâu, nhưng rốt cuộc không đi."},{"jp":"**結局**、何が言いたいの？","vi":"Rốt cuộc là bạn muốn nói gì?"}],
  "528": [{"jp":"三時間待って、**ようやく**順番が来た。","vi":"Đợi ba tiếng, cuối cùng cũng đến lượt tôi."},{"jp":"**ようやく**春らしくなってきた。","vi":"Cuối cùng trời cũng ra dáng mùa xuân."}],
  "529": [{"jp":"**再び**この町を訪れたい。","vi":"Tôi muốn lại đến thăm thị trấn này lần nữa."},{"jp":"同じ失敗を**再び**繰り返さない。","vi":"Tôi sẽ không lặp lại thất bại tương tự nữa."}],
  "530": [{"jp":"その噂は**たちまち**広まった。","vi":"Tin đồn đó lan ra ngay lập tức."},{"jp":"空が**たちまち**暗くなった。","vi":"Bầu trời chẳng mấy chốc đã tối sầm lại."}],
  "531": [{"jp":"**今度**の試験は難しかった。","vi":"Kỳ thi lần này khó."},{"jp":"**今度**一緒に食事しましょう。","vi":"Lần tới chúng ta cùng đi ăn nhé."}],
  "532": [{"jp":"**今後**ともよろしくお願いします。","vi":"Từ nay về sau mong được anh chị giúp đỡ."},{"jp":"**今後**は気をつけます。","vi":"Từ giờ trở đi tôi sẽ chú ý."}],
  "533": [{"jp":"晴れ**のち**雨の予報だ。","vi":"Dự báo trời nắng, sau đó có mưa."},{"jp":"彼は**後に**有名な画家になった。","vi":"Về sau anh ấy trở thành một họa sĩ nổi tiếng."}],
  "534": [{"jp":"**まもなく**電車が参ります。","vi":"Tàu sắp đến."},{"jp":"日本に来て**まもなく**一年になる。","vi":"Sắp tròn một năm kể từ khi tôi đến Nhật."}],
  "535": [{"jp":"**そのうち**遊びに来てください。","vi":"Hôm nào đó hãy đến chơi nhé."},{"jp":"心配しなくても、**そのうちに**慣れるよ。","vi":"Đừng lo, chẳng mấy chốc bạn sẽ quen thôi."}],
  "536": [{"jp":"**やがて**雨もやむだろう。","vi":"Chẳng mấy chốc mưa sẽ tạnh thôi."},{"jp":"二人は**やがて**結婚した。","vi":"Cuối cùng hai người đã kết hôn."}],
  "537": [{"jp":"**いずれ**またお会いしましょう。","vi":"Lúc nào đó chúng ta lại gặp nhau nhé."},{"jp":"うそは**いずれ**ばれる。","vi":"Lời nói dối sớm muộn gì cũng bị lộ."},{"jp":"**いずれ**の方法も問題がある。","vi":"Phương pháp nào cũng có vấn đề."}],
  "538": [{"jp":"**先ほど**お電話した田中です。","vi":"Tôi là Tanaka, người vừa gọi điện lúc nãy."},{"jp":"**先ほど**の件ですが、了解しました。","vi":"Về việc lúc nãy, tôi đã hiểu rồi."}],
  "539": [{"jp":"その店なら**とっくに**閉店したよ。","vi":"Cửa hàng đó đã đóng cửa từ lâu rồi."},{"jp":"締め切りは**とっくに**過ぎている。","vi":"Hạn chót đã qua từ lâu rồi."}],
  "540": [{"jp":"着いたときには会議は**すでに**始まっていた。","vi":"Khi tôi đến thì cuộc họp đã bắt đầu rồi."},{"jp":"その問題は**すでに**解決している。","vi":"Vấn đề đó đã được giải quyết rồi."}],
  "541": [{"jp":"欠席する場合は**事前に**連絡してください。","vi":"Nếu vắng mặt, hãy liên lạc trước."},{"jp":"**事前に**資料を読んでおいた。","vi":"Tôi đã đọc tài liệu từ trước."}],
  "542": [{"jp":"チケットは**当日**でも買えます。","vi":"Vé có thể mua ngay trong ngày diễn ra."},{"jp":"試験の**当日**に熱が出た。","vi":"Đúng hôm thi thì tôi bị sốt."}],
  "543": [{"jp":"**当時**はまだ携帯電話がなかった。","vi":"Hồi đó vẫn chưa có điện thoại di động."},{"jp":"**当時**のことをよく覚えている。","vi":"Tôi còn nhớ rõ chuyện hồi ấy."}],
  "544": [{"jp":"大雨で電車が**一時**止まった。","vi":"Vì mưa lớn, tàu đã tạm thời ngừng chạy."},{"jp":"**一時**はどうなるかと思った。","vi":"Có lúc tôi đã nghĩ không biết sẽ ra sao."}],
  "545": [{"jp":"**至急**連絡してください。","vi":"Hãy liên lạc gấp."},{"jp":"この書類を**至急**送ってほしい。","vi":"Tôi muốn anh gửi tài liệu này ngay lập tức."}],
  "546": [{"jp":"けが人は**直ちに**病院へ運ばれた。","vi":"Người bị thương lập tức được đưa đến bệnh viện."},{"jp":"**直ちに**避難してください。","vi":"Hãy sơ tán ngay lập tức."}],
  "547": [{"jp":"買ったばかりの服を**早速**着てみた。","vi":"Tôi mặc thử ngay bộ quần áo vừa mua."},{"jp":"では、**早速**始めましょう。","vi":"Vậy thì, chúng ta bắt đầu ngay thôi."}],
  "548": [{"jp":"子供が**いきなり**道に飛び出した。","vi":"Đứa trẻ bất ngờ lao ra đường."},{"jp":"**いきなり**名前を呼ばれて驚いた。","vi":"Tôi giật mình vì đột nhiên bị gọi tên."}],
  "549": [{"jp":"彼は**常に**冷静だ。","vi":"Anh ấy lúc nào cũng bình tĩnh."},{"jp":"安全には**常に**注意しなければならない。","vi":"Phải luôn chú ý đến an toàn."}],
  "550": [{"jp":"この町では**絶えず**工事が行われている。","vi":"Ở thị trấn này liên tục có công trình thi công."},{"jp":"川の水は**絶えず**流れている。","vi":"Nước sông chảy không ngừng."}],
  "551": [{"jp":"彼は**しばしば**会議に遅れる。","vi":"Anh ấy thường xuyên đến họp muộn."},{"jp":"この道では**しばしば**事故が起こる。","vi":"Trên con đường này thường xuyên xảy ra tai nạn."}],
  "552": [{"jp":"**たびたび**ご迷惑をおかけしてすみません。","vi":"Xin lỗi vì đã nhiều lần làm phiền anh."},{"jp":"彼女は**たびたび**この店に来る。","vi":"Cô ấy hay đến cửa hàng này."}],
  "553": [{"jp":"弟は**しょっちゅう**忘れ物をする。","vi":"Em trai tôi suốt ngày quên đồ."},{"jp":"あの二人は**しょっちゅう**けんかしている。","vi":"Hai người đó lúc nào cũng cãi nhau."}],
  "554": [{"jp":"**たまに**外で食事をする。","vi":"Thỉnh thoảng tôi ăn ở ngoài."},{"jp":"**たまに**は連絡してね。","vi":"Thỉnh thoảng nhớ liên lạc nhé."}],
  "555": [{"jp":"父は**めったに**怒らない。","vi":"Bố tôi hầu như không bao giờ nổi giận."},{"jp":"この地方では**めったに**雪が降らない。","vi":"Ở vùng này hiếm khi có tuyết rơi."}],
  "556": [{"jp":"彼女はいつも**にこにこ**している。","vi":"Cô ấy lúc nào cũng tươi cười."},{"jp":"赤ちゃんが**にこにこ**笑っている。","vi":"Em bé đang cười toe toét."}],
  "557": [{"jp":"彼は一人で**にやにや**している。","vi":"Anh ta đang cười tủm tỉm một mình."},{"jp":"何を**にやにや**笑っているの？","vi":"Cậu cười tủm tỉm cái gì thế?"}],
  "558": [{"jp":"発表の前は胸が**どきどき**する。","vi":"Trước khi thuyết trình, tim tôi đập thình thịch."},{"jp":"結果を聞くまで**どきどき**した。","vi":"Tôi hồi hộp cho đến khi nghe kết quả."}],
  "559": [{"jp":"子供の危ない遊びを**はらはら**しながら見ていた。","vi":"Tôi thấp thỏm lo lắng nhìn bọn trẻ chơi trò nguy hiểm."},{"jp":"**はらはら**する試合だった。","vi":"Đó là một trận đấu làm người xem nín thở lo lắng."}],
  "560": [{"jp":"約束を破ったので、父は**かんかん**だ。","vi":"Vì tôi thất hứa nên bố giận sôi lên."},{"jp":"夏の日が**かんかん**照っている。","vi":"Nắng hè chói chang gay gắt."}],
  "561": [{"jp":"急に雨が降って**びしょびしょ**になった。","vi":"Trời đổ mưa bất chợt nên tôi ướt sũng."},{"jp":"汗でシャツが**びしょびしょ**だ。","vi":"Áo sơ mi ướt đẫm mồ hôi."}],
  "562": [{"jp":"道に迷って駅の周りを**うろうろ**した。","vi":"Bị lạc đường, tôi đi loanh quanh nhà ga."},{"jp":"家の前を変な人が**うろうろ**している。","vi":"Có người lạ cứ lảng vảng trước nhà."}],
  "563": [{"jp":"渋滞で車が**のろのろ**進んでいる。","vi":"Vì tắc đường, xe cộ nhích từng chút một."},{"jp":"**のろのろ**しないで早く準備しなさい。","vi":"Đừng lề mề nữa, chuẩn bị nhanh lên."}],
  "564": [{"jp":"熱があって頭が**ふらふら**する。","vi":"Tôi bị sốt nên đầu choáng váng."},{"jp":"徹夜したので**ふらふら**だ。","vi":"Thức trắng đêm nên tôi lảo đảo."},{"jp":"考えが**ふらふら**して決められない。","vi":"Suy nghĩ cứ chao đảo nên không quyết được."}],
  "565": [{"jp":"休日は町を**ぶらぶら**歩いた。","vi":"Ngày nghỉ tôi đi dạo lang thang trong phố."},{"jp":"仕事もしないで**ぶらぶら**している。","vi":"Anh ta không làm việc mà cứ lông bông."},{"jp":"子供が足を**ぶらぶら**させている。","vi":"Đứa trẻ đang đung đưa chân."}],
  "566": [{"jp":"雨が降った。**したがって**試合は中止だ。","vi":"Trời mưa. Vì vậy trận đấu bị hủy."},{"jp":"応募者が多い。**したがって**選考は厳しい。","vi":"Số người ứng tuyển đông. Do đó việc tuyển chọn rất khắt khe."}],
  "567": [{"jp":"彼は頭がいい。**だが**、努力しない。","vi":"Anh ta thông minh. Tuy nhiên lại không chịu nỗ lực."},{"jp":"急いだ。**だが**、間に合わなかった。","vi":"Tôi đã vội. Thế nhưng vẫn không kịp."}],
  "568": [{"jp":"簡単だと思った。**ところが**、とても難しかった。","vi":"Tôi tưởng là dễ. Vậy mà lại rất khó."},{"jp":"晴れると言っていた。**ところが**、雨が降った。","vi":"Dự báo là trời nắng. Thế mà trời lại mưa."}],
  "569": [{"jp":"この店は安くて、**しかも**おいしい。","vi":"Quán này rẻ mà lại còn ngon."},{"jp":"彼は遅刻した。**しかも**宿題を忘れた。","vi":"Cậu ta đi muộn. Hơn nữa còn quên bài tập."}],
  "570": [{"jp":"ボタンを押した。**すると**ドアが開いた。","vi":"Tôi bấm nút. Thế là cửa mở ra."},{"jp":"窓を開けた。**すると**涼しい風が入ってきた。","vi":"Tôi mở cửa sổ, thế là gió mát lùa vào."},{"jp":"「明日は休みです。」「**すると**、会議は延期ですね。」","vi":"\"Mai là ngày nghỉ.\" \"Vậy thì cuộc họp sẽ hoãn nhỉ.\""}],
  "571": [{"jp":"行けません。**なぜなら**仕事があるからです。","vi":"Tôi không đi được. Bởi vì tôi có việc."},{"jp":"賛成できない。**なぜなら**費用が高すぎるからだ。","vi":"Tôi không thể tán thành. Bởi vì chi phí quá cao."}],
  "572": [{"jp":"「なぜ食べないの？」「**だって**まずいんだもん。」","vi":"\"Sao con không ăn?\" \"Tại vì dở lắm mà.\""},{"jp":"**だって**時間がなかったんだよ。","vi":"Chả là tôi không có thời gian mà."}],
  "573": [{"jp":"**要するに**、お金が足りないということだ。","vi":"Tóm lại là không đủ tiền."},{"jp":"**要するに**何が言いたいんですか。","vi":"Tóm lại anh muốn nói gì?"}],
  "574": [{"jp":"日本の首都、**すなわち**東京に住んでいる。","vi":"Tôi sống ở thủ đô Nhật Bản, tức là Tokyo."},{"jp":"沈黙は**すなわち**反対を意味する。","vi":"Im lặng có nghĩa là phản đối."}],
  "575": [{"jp":"電話**あるいは**メールで連絡してください。","vi":"Hãy liên lạc bằng điện thoại hoặc email."},{"jp":"**あるいは**彼の言う通りかもしれない。","vi":"Có lẽ đúng như anh ấy nói."}],
  "576": [{"jp":"**さて**、次の議題に移りましょう。","vi":"Nào, chúng ta chuyển sang chủ đề tiếp theo."},{"jp":"**さて**、これからどうしようか。","vi":"Giờ thì, từ đây làm gì tiếp đây?"}],
  "577": [{"jp":"**では**、始めましょう。","vi":"Thế thì, chúng ta bắt đầu thôi."},{"jp":"雨ですか。**では**、試合は中止ですね。","vi":"Trời mưa à? Vậy thì trận đấu hủy rồi nhỉ."}],
  "578": [{"jp":"**ところで**、お父さんはお元気ですか。","vi":"Nhân tiện, bố bạn có khỏe không?"},{"jp":"**ところで**、あの件はどうなりましたか。","vi":"Mà này, việc kia thế nào rồi?"}],
  "579": [{"jp":"**そう言えば**、明日は彼の誕生日だ。","vi":"Nhắc mới nhớ, mai là sinh nhật anh ấy."},{"jp":"**そう言えば**、最近彼女を見ないね。","vi":"Nói mới nhớ, dạo này không thấy cô ấy nhỉ."}],
  "580": [{"jp":"いい店だ。**ただ**、少し高い。","vi":"Quán tốt đấy. Có điều hơi đắt."},{"jp":"参加してもいい。**ただ**、遅れるかもしれない。","vi":"Tôi có thể tham gia. Chỉ là có thể sẽ đến muộn."}],
  "581": [{"jp":"災害に備えて**食料**を買っておく。","vi":"Mua sẵn thực phẩm để phòng thiên tai."},{"jp":"この国は**食料**の多くを輸入に頼っている。","vi":"Nước này phụ thuộc vào nhập khẩu phần lớn lương thực."}],
  "582": [{"jp":"この薬は一日三**粒**飲んでください。","vi":"Thuốc này hãy uống ba viên mỗi ngày."},{"jp":"ご飯は一**粒**も残さず食べなさい。","vi":"Hãy ăn hết, đừng để sót lại một hạt cơm nào."},{"jp":"大**粒**の雨が降ってきた。","vi":"Mưa hạt to bắt đầu rơi."}],
  "583": [{"jp":"床にパンの**くず**が落ちている。","vi":"Vụn bánh mì rơi trên sàn."},{"jp":"紙**くず**はゴミ箱に捨ててください。","vi":"Hãy vứt giấy vụn vào thùng rác."}],
  "584": [{"jp":"祖父は畑で野菜を**栽培**している。","vi":"Ông tôi trồng rau ngoài ruộng."},{"jp":"この地方ではお茶の**栽培**が盛んだ。","vi":"Vùng này trồng chè rất phát triển."}],
  "585": [{"jp":"今年は米の**収穫**が多かった。","vi":"Năm nay thu hoạch lúa được nhiều."},{"jp":"秋になるとりんごを**収穫**します。","vi":"Đến mùa thu thì thu hoạch táo."},{"jp":"今回の旅行は大きな**収穫**があった。","vi":"Chuyến đi lần này thu được nhiều điều bổ ích."}],
  "586": [{"jp":"青森はりんごの**産地**として有名だ。","vi":"Aomori nổi tiếng là vùng sản xuất táo."},{"jp":"買う前に野菜の**産地**を確認する。","vi":"Kiểm tra nơi sản xuất của rau trước khi mua."}],
  "587": [{"jp":"都心は**土地**の値段が高い。","vi":"Ở trung tâm thành phố giá đất cao."},{"jp":"この**土地**は米作りに向いている。","vi":"Mảnh đất này thích hợp để trồng lúa."}],
  "588": [{"jp":"古い家具を**倉庫**にしまった。","vi":"Tôi đã cất đồ đạc cũ vào kho."},{"jp":"商品は**倉庫**から直接発送されます。","vi":"Hàng hóa được gửi đi trực tiếp từ kho."}],
  "589": [{"jp":"彼は土地をたくさん**所有**している。","vi":"Anh ấy sở hữu rất nhiều đất đai."},{"jp":"この絵は美術館の**所有**です。","vi":"Bức tranh này thuộc sở hữu của bảo tàng mỹ thuật."}],
  "590": [{"jp":"趣味で古い切手を**収集**している。","vi":"Tôi sưu tầm tem cổ theo sở thích."},{"jp":"ゴミの**収集**は毎週月曜日です。","vi":"Việc thu gom rác vào thứ Hai hàng tuần."},{"jp":"必要な情報を**収集**してください。","vi":"Hãy thu thập những thông tin cần thiết."}],
  "591": [{"jp":"京都に三日間**滞在**する予定です。","vi":"Tôi dự định lưu trú ở Kyoto ba ngày."},{"jp":"日本での**滞在**期間は一年です。","vi":"Thời gian lưu trú ở Nhật là một năm."}],
  "592": [{"jp":"このアパートは交通の**便**がいい。","vi":"Căn hộ này giao thông thuận tiện."},{"jp":"駅が遠くて**便**が悪い。","vi":"Ga xa nên bất tiện."}],
  "593": [{"jp":"大阪行きの最終**便**に乗った。","vi":"Tôi đã lên chuyến bay cuối cùng đi Osaka."},{"jp":"荷物は航空**便**で送りました。","vi":"Tôi đã gửi hành lý bằng đường hàng không."},{"jp":"このバスは一時間に一**便**しかない。","vi":"Xe buýt này mỗi giờ chỉ có một chuyến."}],
  "594": [{"jp":"このホテルは**設備**が整っている。","vi":"Khách sạn này trang thiết bị đầy đủ."},{"jp":"工場の**設備**を新しくした。","vi":"Đã thay mới thiết bị của nhà máy."}],
  "595": [{"jp":"この家は有名な建築家が**設計**した。","vi":"Ngôi nhà này do một kiến trúc sư nổi tiếng thiết kế."},{"jp":"将来の生活**設計**を立てる。","vi":"Lập kế hoạch cho cuộc sống tương lai."}],
  "596": [{"jp":"学生たちが短い映画を**制作**した。","vi":"Các sinh viên đã sản xuất một bộ phim ngắn."},{"jp":"この机は父が**製作**したものだ。","vi":"Chiếc bàn này là do bố tôi làm ra."}],
  "597": [{"jp":"この工場では車の部品を**製造**している。","vi":"Nhà máy này sản xuất linh kiện ô tô."},{"jp":"**製造**年月日を確認してください。","vi":"Hãy kiểm tra ngày tháng sản xuất."}],
  "598": [{"jp":"駅前に新しいビルを**建築**中だ。","vi":"Một tòa nhà mới đang được xây trước nhà ga."},{"jp":"大学で**建築**を学んでいます。","vi":"Tôi đang học kiến trúc ở đại học."}],
  "599": [{"jp":"この湖は**人工**のものです。","vi":"Hồ này là hồ nhân tạo."},{"jp":"**人工**知能の研究が進んでいる。","vi":"Nghiên cứu trí tuệ nhân tạo đang tiến triển."}],
  "600": [{"jp":"タイヤの空気の**圧力**を調べる。","vi":"Kiểm tra áp suất không khí của lốp xe."},{"jp":"周りからの**圧力**に負けないでほしい。","vi":"Mong bạn đừng khuất phục trước áp lực từ xung quanh."}],
  "601": [{"jp":"辛い料理は胃に**刺激**が強い。","vi":"Món cay kích thích dạ dày mạnh."},{"jp":"留学生活はとても**刺激**になった。","vi":"Cuộc sống du học đã là nguồn kích thích lớn với tôi."},{"jp":"犯人を**刺激**しないように注意する。","vi":"Cẩn thận để không kích động tên tội phạm."}],
  "602": [{"jp":"手をこすると**摩擦**で温かくなる。","vi":"Xoa tay vào nhau thì ấm lên nhờ ma sát."},{"jp":"両国の間に貿易**摩擦**が起きている。","vi":"Giữa hai nước đang xảy ra xung đột thương mại."}],
  "603": [{"jp":"相手の**立場**になって考えてみよう。","vi":"Hãy thử đặt mình vào vị trí của đối phương mà suy nghĩ."},{"jp":"私の**立場**では何も言えません。","vi":"Ở vị trí của tôi thì không thể nói gì được."}],
  "604": [{"jp":"親としての**役割**を果たしたい。","vi":"Tôi muốn làm tròn vai trò của một người cha mẹ."},{"jp":"会議で一人ずつ**役割**を決めた。","vi":"Trong cuộc họp đã phân vai trò cho từng người."}],
  "605": [{"jp":"夫婦で家事を**分担**している。","vi":"Hai vợ chồng chia nhau làm việc nhà."},{"jp":"費用は全員で**分担**しましょう。","vi":"Chi phí hãy để mọi người cùng chia nhau gánh."}],
  "606": [{"jp":"このクラスは山田先生が**担当**している。","vi":"Lớp này do thầy Yamada phụ trách."},{"jp":"**担当**の者にお繋ぎします。","vi":"Tôi sẽ nối máy cho người phụ trách."}],
  "607": [{"jp":"夜は二人で**交代**で運転した。","vi":"Buổi tối hai người thay phiên nhau lái xe."},{"jp":"後半から選手が**交代**した。","vi":"Từ hiệp hai, cầu thủ đã được thay ra."}],
  "608": [{"jp":"部長の**代理**で会議に出席した。","vi":"Tôi dự họp thay mặt trưởng phòng."},{"jp":"旅行**代理**店でチケットを買った。","vi":"Tôi đã mua vé ở đại lý du lịch."}],
  "609": [{"jp":"**審判**の判定に選手が抗議した。","vi":"Cầu thủ phản đối quyết định của trọng tài."},{"jp":"最後は法の**審判**を受けることになった。","vi":"Cuối cùng anh ta phải chịu sự phán xét của pháp luật."}],
  "610": [{"jp":"あの映画の**監督**は女性だ。","vi":"Đạo diễn của bộ phim đó là phụ nữ."},{"jp":"チームの**監督**が選手を集めた。","vi":"Huấn luyện viên đội đã tập hợp các cầu thủ."},{"jp":"試験中は先生が**監督**をする。","vi":"Trong giờ thi giáo viên sẽ giám sát."}],
  "611": [{"jp":"来年の売り上げを**予測**するのは難しい。","vi":"Dự đoán doanh thu năm sau rất khó."},{"jp":"**予測**どおり雨が降り出した。","vi":"Trời bắt đầu mưa đúng như dự đoán."}],
  "612": [{"jp":"**予期**しない出来事が起こった。","vi":"Một sự việc không lường trước đã xảy ra."},{"jp":"**予期**していた以上に良い結果だった。","vi":"Kết quả tốt hơn cả dự tính."}],
  "613": [{"jp":"どちらが正しいか**判断**できない。","vi":"Tôi không thể phán đoán bên nào đúng."},{"jp":"医者の**判断**に任せます。","vi":"Tôi giao cho bác sĩ quyết định."}],
  "614": [{"jp":"彼の仕事は高く**評価**されている。","vi":"Công việc của anh ấy được đánh giá cao."},{"jp":"学期末に成績の**評価**がある。","vi":"Cuối học kỳ có đánh giá thành tích."}],
  "615": [{"jp":"上司の**指示**に従って作業する。","vi":"Làm việc theo chỉ thị của cấp trên."},{"jp":"係員が避難の方向を**指示**した。","vi":"Nhân viên đã chỉ dẫn hướng sơ tán."}],
  "616": [{"jp":"信号を**無視**するのは危険だ。","vi":"Vượt đèn đỏ thì nguy hiểm."},{"jp":"挨拶したのに**無視**された。","vi":"Tôi đã chào mà bị ngó lơ."}],
  "617": [{"jp":"**無断**で会社を休んではいけない。","vi":"Không được nghỉ làm khi chưa xin phép."},{"jp":"写真の**無断**使用は禁止です。","vi":"Cấm sử dụng ảnh khi chưa được phép."}],
  "618": [{"jp":"はい、**承知**しました。","vi":"Vâng, tôi đã rõ ạ."},{"jp":"危険は**承知**の上で挑戦する。","vi":"Biết rõ là nguy hiểm nhưng vẫn thử thách."}],
  "619": [{"jp":"彼の説明に**納得**した。","vi":"Tôi đã được thuyết phục bởi lời giải thích của anh ấy."},{"jp":"その結果にはどうも**納得**できない。","vi":"Tôi không tài nào chấp nhận được kết quả đó."}],
  "620": [{"jp":"何か**疑問**があれば質問してください。","vi":"Nếu có thắc mắc gì hãy đặt câu hỏi."},{"jp":"その計画には**疑問**を感じる。","vi":"Tôi thấy nghi ngờ về kế hoạch đó."}],
  "621": [{"jp":"それはあなたの**推測**にすぎない。","vi":"Đó chỉ là phỏng đoán của bạn thôi."},{"jp":"彼の表情から気持ちを**推測**した。","vi":"Tôi phỏng đoán cảm xúc của anh ấy qua nét mặt."}],
  "622": [{"jp":"彼はその噂を**肯定**も否定もしなかった。","vi":"Anh ấy không khẳng định cũng không phủ nhận tin đồn đó."},{"jp":"自分を**肯定**することが大切だ。","vi":"Việc khẳng định giá trị bản thân là quan trọng."}],
  "623": [{"jp":"先輩の意見を**参考**にした。","vi":"Tôi đã tham khảo ý kiến của tiền bối."},{"jp":"この本はとても**参考**になる。","vi":"Cuốn sách này rất đáng để tham khảo."}],
  "624": [{"jp":"けがは軽い**程度**で済んだ。","vi":"Vết thương chỉ ở mức độ nhẹ."},{"jp":"一日一時間**程度**勉強しています。","vi":"Tôi học khoảng một tiếng mỗi ngày."},{"jp":"中学生**程度**の英語なら話せる。","vi":"Tôi nói được tiếng Anh ở trình độ học sinh cấp hai."}],
  "625": [{"jp":"この店はおいしいと**評判**だ。","vi":"Quán này nổi tiếng là ngon."},{"jp":"新しい映画の**評判**はあまり良くない。","vi":"Bộ phim mới bị đánh giá không tốt lắm."}],
  "626": [{"jp":"新聞で作品が厳しく**批評**された。","vi":"Tác phẩm bị phê bình gay gắt trên báo."},{"jp":"友達の作文を**批評**し合った。","vi":"Chúng tôi nhận xét bài văn của nhau."}],
  "627": [{"jp":"先生に**推薦**状を書いてもらった。","vi":"Tôi được thầy viết cho thư giới thiệu."},{"jp":"彼をリーダーに**推薦**します。","vi":"Tôi tiến cử anh ấy làm trưởng nhóm."}],
  "628": [{"jp":"あの人の言うことは**信用**できない。","vi":"Lời người đó nói không thể tin được."},{"jp":"一度失った**信用**は取り戻せない。","vi":"Lòng tin một khi đã mất thì không lấy lại được."}],
  "629": [{"jp":"彼は部下から**信頼**されている。","vi":"Anh ấy được cấp dưới tin cậy."},{"jp":"**信頼**できる医者を見つけた。","vi":"Tôi đã tìm được một bác sĩ đáng tin cậy."}],
  "630": [{"jp":"相手の意見を**尊重**しましょう。","vi":"Hãy tôn trọng ý kiến của đối phương."},{"jp":"子どもの気持ちを**尊重**したい。","vi":"Tôi muốn tôn trọng cảm xúc của con."}],
  "631": [{"jp":"午後から**作業**を再開します。","vi":"Từ buổi chiều sẽ tiếp tục công việc."},{"jp":"この**作業**は慎重に行ってください。","vi":"Hãy thực hiện thao tác này một cách cẩn thận."}],
  "632": [{"jp":"狭い部屋を広く使う**工夫**をした。","vi":"Tôi đã nghĩ cách để dùng căn phòng hẹp một cách rộng rãi."},{"jp":"もう少し**工夫**すれば良くなるよ。","vi":"Nếu chịu khó nghĩ cách thêm chút nữa thì sẽ tốt hơn đấy."}],
  "633": [{"jp":"おかゆは**消化**がいい。","vi":"Cháo dễ tiêu hóa."},{"jp":"一日で予定を全部**消化**した。","vi":"Trong một ngày tôi đã hoàn thành hết lịch trình."},{"jp":"授業の内容を**消化**しきれない。","vi":"Tôi không tiếp thu hết được nội dung bài học."}],
  "634": [{"jp":"このタオルは水をよく**吸収**する。","vi":"Chiếc khăn này thấm nước tốt."},{"jp":"子どもは新しい知識をすぐ**吸収**する。","vi":"Trẻ con tiếp thu kiến thức mới rất nhanh."}],
  "635": [{"jp":"駅に防犯カメラが**設置**された。","vi":"Camera an ninh đã được lắp đặt ở nhà ga."},{"jp":"調査委員会を**設置**することになった。","vi":"Đã quyết định thành lập ủy ban điều tra."}],
  "636": [{"jp":"スマホの言語を日本語に**設定**した。","vi":"Tôi đã cài đặt ngôn ngữ điện thoại sang tiếng Nhật."},{"jp":"目標を高く**設定**しすぎた。","vi":"Tôi đã đặt mục tiêu quá cao."}],
  "637": [{"jp":"エアコンの温度を**調節**する。","vi":"Điều chỉnh nhiệt độ máy lạnh."},{"jp":"テレビの音量を**調節**してください。","vi":"Hãy điều chỉnh âm lượng tivi."}],
  "638": [{"jp":"会議の日程を**調整**します。","vi":"Tôi sẽ sắp xếp lịch cuộc họp."},{"jp":"機械の**調整**に時間がかかった。","vi":"Việc điều chỉnh máy móc mất nhiều thời gian."},{"jp":"両者の意見を**調整**するのは難しい。","vi":"Dung hòa ý kiến của hai bên rất khó."}],
  "639": [{"jp":"やっと試験から**解放**された。","vi":"Cuối cùng tôi cũng thoát khỏi kỳ thi."},{"jp":"人質が無事に**解放**された。","vi":"Con tin đã được thả an toàn."}],
  "640": [{"jp":"**総合**病院で検査を受けた。","vi":"Tôi đã được khám tại bệnh viện đa khoa."},{"jp":"みんなの意見を**総合**して決める。","vi":"Tổng hợp ý kiến của mọi người rồi quyết định."}],
  "641": [{"jp":"三日**連続**で雨が降っている。","vi":"Trời mưa liên tục ba ngày."},{"jp":"このチームは**連続**して優勝した。","vi":"Đội này đã liên tiếp vô địch."}],
  "642": [{"jp":"この薬は効果が長く**持続**する。","vi":"Thuốc này có tác dụng kéo dài."},{"jp":"やる気を**持続**させるのは難しい。","vi":"Duy trì động lực là điều khó."}],
  "643": [{"jp":"雨で試合が**中断**された。","vi":"Trận đấu bị gián đoạn do mưa."},{"jp":"仕事を**中断**して電話に出た。","vi":"Tôi tạm dừng công việc để nghe điện thoại."}],
  "644": [{"jp":"**安定**した仕事に就きたい。","vi":"Tôi muốn có một công việc ổn định."},{"jp":"患者の状態は**安定**している。","vi":"Tình trạng bệnh nhân đang ổn định."}],
  "645": [{"jp":"事故で駅は**混乱**していた。","vi":"Nhà ga hỗn loạn vì tai nạn."},{"jp":"急に言われて頭が**混乱**した。","vi":"Bị nói đột ngột nên đầu óc tôi rối tung."}],
  "646": [{"jp":"気温が急に**上昇**した。","vi":"Nhiệt độ tăng lên đột ngột."},{"jp":"物価の**上昇**が続いている。","vi":"Giá cả tiếp tục tăng."}],
  "647": [{"jp":"ついに目標を**達成**した。","vi":"Cuối cùng tôi đã đạt được mục tiêu."},{"jp":"**達成**感を味わった。","vi":"Tôi đã cảm nhận được cảm giác thành tựu."}],
  "648": [{"jp":"家庭の**事情**で会社を辞めた。","vi":"Tôi nghỉ việc vì hoàn cảnh gia đình."},{"jp":"彼は日本の**事情**に詳しい。","vi":"Anh ấy am hiểu tình hình Nhật Bản."}],
  "649": [{"jp":"**事態**はますます悪くなった。","vi":"Tình hình ngày càng tệ hơn."},{"jp":"緊急**事態**が発生しました。","vi":"Đã xảy ra tình trạng khẩn cấp."}],
  "650": [{"jp":"電波**障害**でテレビが映らない。","vi":"Tivi không lên hình do nhiễu sóng."},{"jp":"どんな**障害**があっても諦めない。","vi":"Dù có trở ngại nào tôi cũng không bỏ cuộc."}],
  "651": [{"jp":"**福祉**の仕事に興味がある。","vi":"Tôi quan tâm đến công việc phúc lợi xã hội."},{"jp":"この国は社会**福祉**が充実している。","vi":"Nước này có phúc lợi xã hội đầy đủ."}],
  "652": [{"jp":"来年から**社会**に出る。","vi":"Từ năm sau tôi sẽ bước ra xã hội."},{"jp":"高齢化は大きな**社会**問題だ。","vi":"Già hóa dân số là vấn đề xã hội lớn."}],
  "653": [{"jp":"**都会**の生活に疲れた。","vi":"Tôi đã mệt mỏi với cuộc sống thành thị."},{"jp":"若者は**都会**に集まりやすい。","vi":"Giới trẻ dễ tập trung về thành phố."}],
  "654": [{"jp":"**世論**調査の結果が発表された。","vi":"Kết quả thăm dò dư luận đã được công bố."},{"jp":"政府は**世論**を無視できない。","vi":"Chính phủ không thể làm ngơ dư luận."}],
  "655": [{"jp":"この国には多くの**民族**が住んでいる。","vi":"Ở nước này có nhiều dân tộc sinh sống."},{"jp":"**民族**衣装を着て写真を撮った。","vi":"Tôi mặc trang phục dân tộc và chụp ảnh."}],
  "656": [{"jp":"医療費が年々**増大**している。","vi":"Chi phí y tế tăng lên hàng năm."},{"jp":"仕事の負担が**増大**した。","vi":"Gánh nặng công việc đã tăng thêm."}],
  "657": [{"jp":"今だけ二割**増量**で販売中です。","vi":"Hiện đang bán tăng thêm 20% lượng, chỉ trong dịp này."},{"jp":"薬を**増量**することになった。","vi":"Đã quyết định tăng liều thuốc."}],
  "658": [{"jp":"来年から**増税**されるそうだ。","vi":"Nghe nói từ năm sau sẽ tăng thuế."},{"jp":"**増税**に反対する人が多い。","vi":"Có nhiều người phản đối tăng thuế."}],
  "659": [{"jp":"忙しい時期は店員を**増員**する。","vi":"Vào mùa bận rộn sẽ tăng thêm nhân viên cửa hàng."},{"jp":"警察官の**増員**が決まった。","vi":"Đã quyết định tăng thêm cảnh sát."}],
  "660": [{"jp":"字が汚いと**減点**されます。","vi":"Chữ xấu thì sẽ bị trừ điểm."},{"jp":"反則で二点**減点**された。","vi":"Bị trừ hai điểm vì phạm luật."}],
  "661": [{"jp":"夏は食欲が**減退**しがちだ。","vi":"Mùa hè thường hay bị giảm cảm giác thèm ăn."},{"jp":"年を取って体力が**減退**した。","vi":"Già đi nên thể lực giảm sút."}],
  "662": [{"jp":"健康のために**減量**している。","vi":"Tôi đang giảm cân vì sức khỏe."},{"jp":"ボクサーは試合前に**減量**する。","vi":"Võ sĩ quyền anh giảm cân trước trận đấu."},{"jp":"ゴミの**減量**に取り組んでいる。","vi":"Chúng tôi đang nỗ lực giảm lượng rác."}],
  "663": [{"jp":"新しい薬の**開発**に成功した。","vi":"Đã thành công trong việc phát triển loại thuốc mới."},{"jp":"この地域は**開発**が進んでいる。","vi":"Khu vực này đang được phát triển mạnh."}],
  "664": [{"jp":"駅前にパン屋が**開店**した。","vi":"Một tiệm bánh mì đã khai trương trước ga."},{"jp":"この店は朝十時に**開店**します。","vi":"Cửa hàng này mở cửa lúc mười giờ sáng."}],
  "665": [{"jp":"兄は去年歯科医院を**開業**した。","vi":"Năm ngoái anh tôi đã mở phòng khám nha khoa."},{"jp":"新しい路線が来月**開業**する。","vi":"Tuyến đường mới sẽ đi vào hoạt động vào tháng sau."}],
  "666": [{"jp":"オリンピックは東京で**開催**された。","vi":"Thế vận hội đã được tổ chức tại Tokyo."},{"jp":"説明会は毎月**開催**しています。","vi":"Buổi giới thiệu được tổ chức hàng tháng."}],
  "667": [{"jp":"夏休みは校庭を一般に**開放**する。","vi":"Kỳ nghỉ hè sân trường được mở cửa cho mọi người."},{"jp":"その国は市場を**開放**した。","vi":"Nước đó đã mở cửa thị trường."}],
  "668": [{"jp":"事故のため道路が**閉鎖**された。","vi":"Con đường bị phong tỏa vì tai nạn."},{"jp":"工場は来年**閉鎖**される予定だ。","vi":"Nhà máy dự kiến sẽ đóng cửa vào năm sau."}],
  "669": [{"jp":"食品は**密閉**容器に入れて保存する。","vi":"Bảo quản thực phẩm trong hộp kín."},{"jp":"瓶のふたをしっかり**密閉**した。","vi":"Tôi đã đậy kín nắp lọ."}],
  "670": [{"jp":"生活習慣を**改善**しよう。","vi":"Hãy cải thiện thói quen sinh hoạt."},{"jp":"職場の環境が**改善**された。","vi":"Môi trường làm việc đã được cải thiện."}],
  "671": [{"jp":"品種を**改良**して甘いトマトを作った。","vi":"Cải tiến giống để tạo ra cà chua ngọt."},{"jp":"この製品は何度も**改良**されている。","vi":"Sản phẩm này đã được cải tiến nhiều lần."}],
  "672": [{"jp":"政府は教育**改革**を進めている。","vi":"Chính phủ đang thúc đẩy cải cách giáo dục."},{"jp":"会社の制度を大きく**改革**した。","vi":"Đã cải cách lớn chế độ của công ty."}],
  "673": [{"jp":"法律が**改正**された。","vi":"Luật đã được sửa đổi."},{"jp":"規則の**改正**について話し合う。","vi":"Thảo luận về việc sửa đổi quy định."}],
  "674": [{"jp":"来月から運賃が**改定**される。","vi":"Từ tháng sau giá vé sẽ được điều chỉnh."},{"jp":"料金**改定**のお知らせです。","vi":"Đây là thông báo về việc thay đổi giá."}],
  "675": [{"jp":"古いお寺を**改修**している。","vi":"Đang tu sửa ngôi chùa cũ."},{"jp":"橋の**改修**工事が始まった。","vi":"Công trình sửa chữa cây cầu đã bắt đầu."}],
  "676": [{"jp":"二人の意見が**一致**した。","vi":"Ý kiến của hai người đã nhất trí."},{"jp":"全員**一致**で賛成した。","vi":"Mọi người nhất trí tán thành."}],
  "677": [{"jp":"兄は明るい。**一方**、弟はおとなしい。","vi":"Anh trai vui vẻ. Mặt khác, em trai thì trầm tính."},{"jp":"物価は上がる**一方**だ。","vi":"Giá cả cứ tăng mãi."}],
  "678": [{"jp":"部屋の温度を**一定**に保つ。","vi":"Giữ nhiệt độ phòng ở mức không đổi."},{"jp":"**一定**の条件を満たせば参加できる。","vi":"Nếu đáp ứng điều kiện nhất định thì có thể tham gia."}],
  "679": [{"jp":"すし**一人前**を注文した。","vi":"Tôi đã gọi một suất sushi."},{"jp":"彼もやっと**一人前**の大人になった。","vi":"Cậu ấy cuối cùng cũng thành người trưởng thành."},{"jp":"**一人前**の料理人になるには十年かかる。","vi":"Để thành đầu bếp thành thạo phải mất mười năm."}],
  "680": [{"jp":"彼は**一流**の会社に就職した。","vi":"Anh ấy vào làm ở một công ty hàng đầu."},{"jp":"**一流**のホテルに泊まってみたい。","vi":"Tôi muốn thử ở khách sạn hạng nhất."}],
  "681": [{"jp":"湖に山が**映って**いる。","vi":"Ngọn núi phản chiếu trên mặt hồ."},{"jp":"このテレビはよく**映らない**。","vi":"Cái tivi này lên hình không rõ."},{"jp":"鏡に自分の顔が**映った**。","vi":"Khuôn mặt tôi hiện lên trong gương."}],
  "682": [{"jp":"鏡に姿を**映して**みる。","vi":"Soi bóng mình vào gương."},{"jp":"スクリーンに写真を**映した**。","vi":"Đã chiếu ảnh lên màn hình."}],
  "683": [{"jp":"大雨で家が水に**つかった**。","vi":"Nhà bị ngập nước vì mưa lớn."},{"jp":"温泉にゆっくり**つかる**。","vi":"Ngâm mình thong thả trong suối nước nóng."},{"jp":"この漬物はよく**つかって**いる。","vi":"Món dưa muối này đã ngấm kỹ."}],
  "684": [{"jp":"汚れた服を水に**つけて**おく。","vi":"Ngâm quần áo bẩn vào nước."},{"jp":"刺身をしょうゆに**つけて**食べる。","vi":"Chấm sashimi vào xì dầu để ăn."}],
  "685": [{"jp":"空に白い雲が**浮かんで**いる。","vi":"Mây trắng lơ lửng trên bầu trời."},{"jp":"いいアイデアが**浮かんだ**。","vi":"Tôi đã nghĩ ra một ý tưởng hay."},{"jp":"池に落ち葉が**浮かんで**いる。","vi":"Lá rụng nổi trên mặt ao."}],
  "686": [{"jp":"子どもたちが川に笹舟を**浮かべた**。","vi":"Bọn trẻ thả thuyền lá tre trôi trên sông."},{"jp":"彼女は目に涙を**浮かべて**いた。","vi":"Cô ấy rưng rưng nước mắt."},{"jp":"彼は笑みを**浮かべて**答えた。","vi":"Anh ấy mỉm cười trả lời."}],
  "687": [{"jp":"木は水に**浮く**。","vi":"Gỗ nổi trên nước."},{"jp":"風船が空中に**浮いて**いる。","vi":"Quả bóng bay lơ lửng trên không."},{"jp":"彼はクラスで少し**浮いて**いる。","vi":"Cậu ấy hơi lạc lõng trong lớp."}],
  "688": [{"jp":"海に**潜って**魚を見た。","vi":"Tôi lặn xuống biển ngắm cá."},{"jp":"寒いので布団に**潜った**。","vi":"Lạnh nên tôi chui vào chăn."},{"jp":"犯人は地下に**潜って**いる。","vi":"Tên tội phạm đang lẩn trốn."}],
  "689": [{"jp":"天ぷらを揚げていたら油が**はねた**。","vi":"Đang chiên tempura thì dầu bắn ra."},{"jp":"車が通って泥が**跳ねた**。","vi":"Xe chạy qua làm bùn bắn lên."},{"jp":"子どもがうれしそうに**跳ねて**いる。","vi":"Đứa trẻ đang nhảy nhót vui vẻ."}],
  "690": [{"jp":"母は赤ちゃんを**背負って**いた。","vi":"Mẹ đang cõng em bé."},{"jp":"重いリュックを**背負って**山に登る。","vi":"Đeo ba lô nặng trên lưng để leo núi."},{"jp":"彼は家族の生活を**背負って**いる。","vi":"Anh ấy gánh vác cuộc sống của cả gia đình."}],
  "691": [{"jp":"警察が犯人を**追って**いる。","vi":"Cảnh sát đang truy đuổi tên tội phạm."},{"jp":"夢を**追って**東京に来た。","vi":"Tôi đến Tokyo để theo đuổi ước mơ."},{"jp":"毎日仕事に**追われて**いる。","vi":"Ngày nào tôi cũng bị công việc cuốn đi, bận tối mắt."}],
  "692": [{"jp":"犬が猫を**追いかけて**いる。","vi":"Con chó đang đuổi theo con mèo."},{"jp":"忘れ物を届けに彼を**追いかけた**。","vi":"Tôi chạy theo anh ấy để đưa đồ để quên."}],
  "693": [{"jp":"走って前の人に**追いついた**。","vi":"Tôi chạy và đuổi kịp người phía trước."},{"jp":"授業に**追いつく**ために勉強する。","vi":"Học để theo kịp bài giảng."}],
  "694": [{"jp":"前の車を**追い越して**はいけない。","vi":"Không được vượt xe phía trước."},{"jp":"息子に背を**追い越された**。","vi":"Tôi bị con trai vượt chiều cao."}],
  "695": [{"jp":"名前を呼ばれて**振り向いた**。","vi":"Bị gọi tên nên tôi quay lại."},{"jp":"彼は一度も**振り向かず**に去った。","vi":"Anh ấy bỏ đi mà không ngoảnh lại lần nào."}],
  "696": [{"jp":"川で魚を**捕った**。","vi":"Tôi đã bắt cá ở sông."},{"jp":"今年は新入社員を十人**採る**予定だ。","vi":"Năm nay dự định tuyển mười nhân viên mới."},{"jp":"社長自ら指揮を**執った**。","vi":"Giám đốc đích thân đảm nhận việc chỉ huy."}],
  "697": [{"jp":"床の本を**取り上げた**。","vi":"Tôi nhặt cuốn sách trên sàn lên."},{"jp":"授業中に漫画を**取り上げられた**。","vi":"Tôi bị tịch thu truyện tranh trong giờ học."},{"jp":"その問題は新聞で**取り上げられた**。","vi":"Vấn đề đó đã được đưa lên báo."}],
  "698": [{"jp":"雨が降る前に洗濯物を**取り入れた**。","vi":"Tôi thu quần áo vào trước khi trời mưa."},{"jp":"外国の技術を**取り入れる**。","vi":"Áp dụng kỹ thuật nước ngoài."},{"jp":"秋に稲を**取り入れる**。","vi":"Thu hoạch lúa vào mùa thu."}],
  "699": [{"jp":"ナイフで鉛筆を**削る**。","vi":"Gọt bút chì bằng dao."},{"jp":"予算を大幅に**削られた**。","vi":"Ngân sách bị cắt giảm mạnh."}],
  "700": [{"jp":"古新聞をひもで**縛った**。","vi":"Tôi buộc báo cũ bằng dây."},{"jp":"規則に**縛られる**のは嫌だ。","vi":"Tôi ghét bị gò bó bởi quy tắc."}],
  "701": [{"jp":"レモンを**搾って**ジュースを作る。","vi":"Vắt chanh làm nước ép."},{"jp":"濡れたタオルを**絞る**。","vi":"Vắt khăn ướt."},{"jp":"候補を三つに**絞った**。","vi":"Đã thu hẹp ứng viên xuống còn ba."}],
  "702": [{"jp":"地球は太陽の周りを**回って**いる。","vi":"Trái đất quay quanh mặt trời."},{"jp":"休みの日に京都のお寺を**回った**。","vi":"Ngày nghỉ tôi đã đi một vòng các chùa ở Kyoto."},{"jp":"裏口に**回って**ください。","vi":"Hãy vòng ra cửa sau."}],
  "703": [{"jp":"ハンドルを右に**回す**。","vi":"Xoay vô lăng sang phải."},{"jp":"読んだら資料を隣の人に**回して**ください。","vi":"Đọc xong hãy chuyển tài liệu cho người bên cạnh."},{"jp":"利益の一部を研究費に**回す**。","vi":"Dành một phần lợi nhuận cho chi phí nghiên cứu."}],
  "704": [{"jp":"文を単語ごとに**区切って**読む。","vi":"Ngắt câu theo từng từ để đọc."},{"jp":"部屋をカーテンで二つに**区切った**。","vi":"Ngăn căn phòng làm hai bằng rèm."}],
  "705": [{"jp":"旅行のスケジュールを**組んだ**。","vi":"Đã lên lịch trình chuyến du lịch."},{"jp":"彼と**組んで**新しい会社を作った。","vi":"Hợp tác với anh ấy lập công ty mới."},{"jp":"木を**組んで**小屋を作る。","vi":"Ghép gỗ để dựng túp lều."}],
  "706": [{"jp":"買ってきた本棚を自分で**組み立てた**。","vi":"Tôi tự lắp ráp kệ sách vừa mua."},{"jp":"話を**組み立てて**から書き始める。","vi":"Sắp xếp bố cục câu chuyện rồi mới bắt đầu viết."}],
  "707": [{"jp":"新しいメンバーがチームに**加わった**。","vi":"Thành viên mới đã gia nhập đội."},{"jp":"十二月に入り、寒さが一段と**加わった**。","vi":"Bước sang tháng Mười hai, cái lạnh càng tăng thêm."}],
  "708": [{"jp":"スープに塩を少し**加えて**ください。","vi":"Hãy thêm một chút muối vào súp."},{"jp":"彼を仲間に**加えよう**。","vi":"Hãy cho anh ấy vào nhóm."}],
  "709": [{"jp":"ドレスがきれいに**仕上がった**。","vi":"Chiếc váy đã được hoàn thành đẹp đẽ."},{"jp":"論文は来週**仕上がる**予定だ。","vi":"Luận văn dự kiến tuần sau sẽ xong."}],
  "710": [{"jp":"徹夜してレポートを**仕上げた**。","vi":"Tôi thức trắng đêm để hoàn thành báo cáo."},{"jp":"明日までにこの絵を**仕上げたい**。","vi":"Tôi muốn hoàn thành bức tranh này trước ngày mai."}],
  "711": [{"jp":"公園の前を**通りかかった**ときに友達に会った。","vi":"Khi đi ngang qua công viên tôi đã gặp bạn."},{"jp":"**通りかかった**人が助けてくれた。","vi":"Một người đi ngang qua đã giúp tôi."}],
  "712": [{"jp":"蝶が花の間を**飛び回って**いる。","vi":"Bướm đang bay lượn quanh những bông hoa."},{"jp":"彼は仕事で世界中を**飛び回って**いる。","vi":"Anh ấy bay khắp thế giới vì công việc."},{"jp":"資金集めに一日中**飛び回った**。","vi":"Tôi chạy ngược chạy xuôi cả ngày để gom vốn."}],
  "713": [{"jp":"また春が**巡って**きた。","vi":"Mùa xuân lại trở về."},{"jp":"遺産を**巡って**兄弟が争った。","vi":"Anh em tranh chấp xoay quanh chuyện thừa kế."},{"jp":"バスで名所を**巡る**ツアーに参加した。","vi":"Tôi tham gia tour đi xe buýt vòng quanh các danh lam."}],
  "714": [{"jp":"睡眠不足を昼寝で**補う**。","vi":"Bù đắp việc thiếu ngủ bằng giấc ngủ trưa."},{"jp":"足りない説明を**補って**ください。","vi":"Hãy bổ sung phần giải thích còn thiếu."},{"jp":"会社が損害を**補った**。","vi":"Công ty đã đền bù thiệt hại."}],
  "715": [{"jp":"手を洗って風邪を**防ぐ**。","vi":"Rửa tay để phòng cảm."},{"jp":"事故を**防ぐ**ために注意しよう。","vi":"Hãy chú ý để phòng tránh tai nạn."}],
  "716": [{"jp":"彼はおぼれた子どもを**救った**。","vi":"Anh ấy đã cứu đứa trẻ bị đuối nước."},{"jp":"あなたの言葉に**救われ**ました。","vi":"Tôi đã được cứu rỗi nhờ lời nói của bạn."}],
  "717": [{"jp":"日曜日を**除いて**毎日営業しています。","vi":"Mở cửa hàng ngày trừ Chủ nhật."},{"jp":"野菜の汚れを丁寧に**除く**。","vi":"Loại bỏ cẩn thận vết bẩn trên rau."}],
  "718": [{"jp":"詳しい説明は**省きます**。","vi":"Tôi xin lược bỏ phần giải thích chi tiết."},{"jp":"無駄を**省いて**費用を減らす。","vi":"Cắt bỏ lãng phí để giảm chi phí."}],
  "719": [{"jp":"操作を**誤って**データを消してしまった。","vi":"Thao tác nhầm nên đã xóa mất dữ liệu."},{"jp":"判断を**誤る**と大変なことになる。","vi":"Nếu phán đoán sai lầm thì sẽ gặp chuyện lớn."}],
  "720": [{"jp":"泥棒に財布を**奪われた**。","vi":"Tôi bị tên trộm cướp mất ví."},{"jp":"その事故は多くの命を**奪った**。","vi":"Vụ tai nạn đó đã cướp đi nhiều sinh mạng."}],
  "721": [{"jp":"使った道具は元の場所に**しまって**ください。","vi":"Hãy cất dụng cụ đã dùng về chỗ cũ."},{"jp":"冬服を押し入れに**しまった**。","vi":"Tôi đã cất quần áo mùa đông vào tủ âm tường."}],
  "722": [{"jp":"**怠けて**いると試験に落ちるよ。","vi":"Cứ lười biếng thì sẽ trượt kỳ thi đấy."},{"jp":"彼は仕事を**怠けて**ばかりいる。","vi":"Anh ta suốt ngày lười làm việc."}],
  "723": [{"jp":"事故で父を**失った**。","vi":"Tôi đã mất cha vì tai nạn."},{"jp":"自信を**失わない**でください。","vi":"Xin đừng đánh mất sự tự tin."}],
  "724": [{"jp":"敵の城を**攻めた**。","vi":"Đã tấn công thành của địch."},{"jp":"後半はどんどん**攻めて**いこう。","vi":"Hiệp hai hãy liên tục tấn công nào."}],
  "725": [{"jp":"先生に**にらまれて**黙った。","vi":"Bị thầy lườm nên tôi im lặng."},{"jp":"彼は怖い顔で私を**にらんだ**。","vi":"Anh ta lườm tôi với vẻ mặt đáng sợ."}],
  "726": [{"jp":"失敗した部下を**責める**のはよくない。","vi":"Đổ lỗi cho cấp dưới đã thất bại là không tốt."},{"jp":"そんなに自分を**責めない**でください。","vi":"Xin đừng tự trách mình như vậy."}],
  "727": [{"jp":"親友に**裏切られて**、とてもショックだった。","vi":"Bị bạn thân phản bội, tôi đã rất sốc."},{"jp":"期待を**裏切る**ような結果になってしまった。","vi":"Kết quả lại phụ lòng mong đợi."}],
  "728": [{"jp":"いつまでも親に**頼って**いてはいけない。","vi":"Không thể cứ mãi dựa dẫm vào bố mẹ."},{"jp":"困った時はいつでも私を**頼って**ください。","vi":"Khi gặp khó khăn, cứ dựa vào tôi bất cứ lúc nào."}],
  "729": [{"jp":"帰り道で事故に**遭って**しまった。","vi":"Tôi đã gặp tai nạn trên đường về."},{"jp":"旅行中、ひどい雨に**遭った**。","vi":"Trong chuyến du lịch, tôi gặp phải trận mưa lớn."}],
  "730": [{"jp":"友人を自宅に**招いて**食事をした。","vi":"Tôi mời bạn về nhà ăn cơm."},{"jp":"彼は手で私を**招いた**。","vi":"Anh ấy vẫy tay gọi tôi lại."},{"jp":"不注意が大きな事故を**招いた**。","vi":"Sự bất cẩn đã gây ra một tai nạn lớn."}],
  "731": [{"jp":"凧が木の枝に**引っ掛かって**いる。","vi":"Con diều bị vướng vào cành cây."},{"jp":"簡単な詐欺に**引っ掛かって**しまった。","vi":"Tôi đã bị mắc lừa một trò lừa đảo đơn giản."},{"jp":"空港の検査に**引っ掛かった**。","vi":"Tôi bị giữ lại ở khâu kiểm tra sân bay."}],
  "732": [{"jp":"コートをフックに**引っ掛けて**ください。","vi":"Hãy móc áo khoác lên cái móc."},{"jp":"釘に服を**引っ掛けて**破いてしまった。","vi":"Tôi để áo mắc vào đinh nên bị rách."},{"jp":"客を**引っ掛ける**悪い商売がある。","vi":"Có những kiểu buôn bán xấu lừa khách."}],
  "733": [{"jp":"強風でボートが**ひっくり返った**。","vi":"Thuyền bị lật vì gió mạnh."},{"jp":"滑って後ろに**ひっくり返った**。","vi":"Tôi trượt chân ngã ngửa ra sau."},{"jp":"最後の一点で試合が**ひっくり返った**。","vi":"Trận đấu bị lật ngược ở điểm cuối cùng."}],
  "734": [{"jp":"フライパンの卵を**ひっくり返す**。","vi":"Lật quả trứng trong chảo."},{"jp":"子どもがコップを**ひっくり返した**。","vi":"Đứa trẻ làm đổ cái cốc."}],
  "735": [{"jp":"眼鏡が**ずれて**よく見えない。","vi":"Kính bị trượt xuống nên tôi không nhìn rõ."},{"jp":"彼の意見は話の要点から**ずれて**いる。","vi":"Ý kiến của anh ấy đi chệch khỏi trọng tâm câu chuyện."}],
  "736": [{"jp":"机を少し右に**ずらして**ください。","vi":"Hãy dịch cái bàn sang phải một chút."},{"jp":"会議の時間を一時間**ずらした**。","vi":"Tôi đã lùi giờ họp một tiếng."},{"jp":"休みを**ずらして**旅行に行く。","vi":"Tôi đổi ngày nghỉ để đi du lịch."}],
  "737": [{"jp":"地震で古い家が**崩れた**。","vi":"Ngôi nhà cũ bị sụp đổ vì động đất."},{"jp":"週末は天気が**崩れる**そうだ。","vi":"Nghe nói cuối tuần thời tiết sẽ xấu đi."}],
  "738": [{"jp":"無理をして体調を**崩した**。","vi":"Tôi cố quá sức nên đổ bệnh."},{"jp":"山を**崩して**道路を作る。","vi":"Phá núi để làm đường."},{"jp":"一万円札を**崩して**もらえますか。","vi":"Có thể đổi tờ mười nghìn yên ra tiền lẻ giúp tôi không?"}],
  "739": [{"jp":"台風で海が**荒れて**いる。","vi":"Biển đang động vì bão."},{"jp":"冬は肌が**荒れ**やすい。","vi":"Mùa đông da dễ bị nứt nẻ."},{"jp":"彼は酒を飲むと**荒れる**。","vi":"Anh ta hễ uống rượu là trở nên hung hăng."}],
  "740": [{"jp":"猿が畑を**荒らして**しまった。","vi":"Khỉ đã phá nát cánh đồng."},{"jp":"留守中に泥棒に部屋を**荒らされた**。","vi":"Khi vắng nhà, phòng tôi bị trộm lục tung."}],
  "741": [{"jp":"彼はようやく自分の間違いを**認めた**。","vi":"Cuối cùng anh ấy cũng thừa nhận sai lầm của mình."},{"jp":"外出は**認められて**いません。","vi":"Việc ra ngoài không được cho phép."},{"jp":"彼の才能は誰もが**認めて**いる。","vi":"Ai cũng công nhận tài năng của anh ấy."}],
  "742": [{"jp":"提出前にもう一度答えを**見直した**。","vi":"Tôi xem lại đáp án một lần nữa trước khi nộp."},{"jp":"計画を**見直す**必要がある。","vi":"Cần phải xem xét lại kế hoạch."},{"jp":"あの一件で彼を**見直した**。","vi":"Nhờ chuyện đó mà tôi đánh giá lại anh ấy (tốt hơn)."}],
  "743": [{"jp":"**見慣れた**町並みが懐かしい。","vi":"Tôi nhớ những dãy phố quen thuộc."},{"jp":"**見慣れない**車が家の前に止まっている。","vi":"Có một chiếc xe lạ đang đỗ trước nhà."}],
  "744": [{"jp":"彼は大声で助けを**求めた**。","vi":"Anh ấy kêu to cầu cứu."},{"jp":"会社は社員に説明を**求めた**。","vi":"Công ty yêu cầu nhân viên giải thích."},{"jp":"お**求め**の商品はこちらです。","vi":"Món hàng quý khách cần mua ở đây ạ."}],
  "745": [{"jp":"ガスが**漏れて**いるようだ。","vi":"Hình như ga đang bị rò rỉ."},{"jp":"会議の内容が外部に**漏れた**。","vi":"Nội dung cuộc họp đã bị lộ ra ngoài."},{"jp":"名簿から私の名前が**漏れて**いた。","vi":"Tên tôi bị sót khỏi danh sách."}],
  "746": [{"jp":"彼女は思わずため息を**漏らした**。","vi":"Cô ấy bất giác buông ra một tiếng thở dài."},{"jp":"秘密を**漏らさない**でください。","vi":"Xin đừng để lộ bí mật."},{"jp":"大事な点を聞き**漏らして**しまった。","vi":"Tôi đã nghe sót mất điểm quan trọng."}],
  "747": [{"jp":"庭の木にたくさん実が**なった**。","vi":"Cây trong vườn đã ra rất nhiều quả."},{"jp":"このトマトはよく**なる**品種だ。","vi":"Giống cà chua này rất sai quả."}],
  "748": [{"jp":"魚が**焦げて**しまった。","vi":"Cá bị cháy mất rồi."},{"jp":"何か**焦げた**においがする。","vi":"Có mùi gì đó bị khét."}],
  "749": [{"jp":"それは規則に**反する**行為だ。","vi":"Đó là hành vi trái với quy định."},{"jp":"予想に**反して**、試合は負けた。","vi":"Trái với dự đoán, trận đấu đã thua."}],
  "750": [{"jp":"蚊に刺されて腕が**膨れた**。","vi":"Bị muỗi đốt nên cánh tay sưng lên."},{"jp":"注意されて、妹は**膨れて**しまった。","vi":"Bị nhắc nhở, em gái tôi phụng phịu giận dỗi."}],
  "751": [{"jp":"春になって桜のつぼみが**膨らんで**きた。","vi":"Xuân đến, nụ hoa anh đào đã căng lên."},{"jp":"予算が予定より**膨らんだ**。","vi":"Ngân sách tăng lên nhiều hơn dự kiến."},{"jp":"夢が**膨らむ**話ですね。","vi":"Đúng là câu chuyện khiến ước mơ thêm lớn lao."}],
  "752": [{"jp":"子どもが風船を**膨らませて**いる。","vi":"Đứa trẻ đang thổi bóng bay."},{"jp":"彼女は期待に胸を**膨らませた**。","vi":"Cô ấy tràn đầy hy vọng."}],
  "753": [{"jp":"鉛筆の先が**とがって**いる。","vi":"Đầu bút chì nhọn."},{"jp":"**とがった**物は危ないので気をつけて。","vi":"Đồ vật nhọn rất nguy hiểm nên hãy cẩn thận."}],
  "754": [{"jp":"次の条件に**当てはまる**人は応募できます。","vi":"Những người đáp ứng các điều kiện sau có thể ứng tuyển."},{"jp":"この規則はすべての場合に**当てはまる**わけではない。","vi":"Quy tắc này không áp dụng được cho mọi trường hợp."}],
  "755": [{"jp":"卒業後、教師の職に**就いた**。","vi":"Sau khi tốt nghiệp, tôi làm nghề giáo viên."},{"jp":"彼は社長の地位に**就いた**。","vi":"Ông ấy đã lên chức giám đốc."}],
  "756": [{"jp":"田中先生が三年一組を**受け持って**いる。","vi":"Thầy Tanaka phụ trách lớp 3-1."},{"jp":"私はこのプロジェクトの営業を**受け持つ**。","vi":"Tôi đảm nhận mảng kinh doanh của dự án này."}],
  "757": [{"jp":"係員の指示に**従って**ください。","vi":"Hãy làm theo hướng dẫn của nhân viên."},{"jp":"ガイドに**従って**館内を見学した。","vi":"Chúng tôi đi theo hướng dẫn viên tham quan bên trong tòa nhà."},{"jp":"年を取るに**従って**、体力が落ちる。","vi":"Càng có tuổi thì thể lực càng giảm."}],
  "758": [{"jp":"彼は「疲れた」と小さく**つぶやいた**。","vi":"Anh ấy lẩm bẩm khẽ: \"Mệt quá\"."},{"jp":"独り言を**つぶやく**癖がある。","vi":"Tôi có thói quen lẩm bẩm một mình."}],
  "759": [{"jp":"会議で自分の意見を**述べた**。","vi":"Tôi đã phát biểu ý kiến của mình trong cuộc họp."},{"jp":"前に**述べた**ように、計画は変更されました。","vi":"Như đã nói ở trên, kế hoạch đã được thay đổi."}],
  "760": [{"jp":"今朝は五時に**目覚めた**。","vi":"Sáng nay tôi thức dậy lúc 5 giờ."},{"jp":"彼は音楽の才能に**目覚めた**。","vi":"Anh ấy đã nhận ra tài năng âm nhạc của mình."}],
  "761": [{"jp":"高い物がいい物だとは**限らない**。","vi":"Đồ đắt chưa chắc đã là đồ tốt."},{"jp":"疲れた時は寝るに**限る**。","vi":"Khi mệt thì tốt nhất là đi ngủ."},{"jp":"本日に**限り**、全品半額です。","vi":"Chỉ riêng hôm nay, tất cả sản phẩm giảm nửa giá."}],
  "762": [{"jp":"栄養が**片寄らない**ように食べよう。","vi":"Hãy ăn uống sao cho dinh dưỡng không bị lệch."},{"jp":"人口が都市に**片寄って**いる。","vi":"Dân số dồn về các thành phố."},{"jp":"荷物が一方に**片寄って**いて危ない。","vi":"Hành lý dồn về một bên nên nguy hiểm."}],
  "763": [{"jp":"氷が溶けて、味が**薄まった**。","vi":"Đá tan nên vị đã nhạt đi."},{"jp":"時間がたって、怒りが**薄まって**きた。","vi":"Thời gian trôi qua, cơn giận đã nguôi dần."}],
  "764": [{"jp":"このジュースは水で**薄めて**飲む。","vi":"Nước ép này pha loãng với nước rồi uống."},{"jp":"スープが濃いので少し**薄めた**。","vi":"Súp đậm quá nên tôi làm nhạt bớt một chút."}],
  "765": [{"jp":"子どもの頃の記憶が**薄れて**きた。","vi":"Ký ức thời thơ ấu đã phai nhạt dần."},{"jp":"夜明けとともに霧が**薄れた**。","vi":"Sương mù tan dần khi trời sáng."}],
  "766": [{"jp":"この湖の水は**透き通って**いる。","vi":"Nước hồ này trong vắt."},{"jp":"彼女は**透き通る**ような声で歌った。","vi":"Cô ấy hát bằng giọng trong trẻo."}],
  "767": [{"jp":"先生が入ると、教室が**静まった**。","vi":"Khi thầy giáo bước vào, lớp học im lặng."},{"jp":"薬を飲んだら痛みが**鎮まった**。","vi":"Uống thuốc xong thì cơn đau dịu đi."},{"jp":"夜になって風が**静まった**。","vi":"Về đêm gió đã lặng."}],
  "768": [{"jp":"深呼吸をして心を**静めた**。","vi":"Tôi hít thở sâu để trấn tĩnh lại."},{"jp":"警察が騒ぎを**鎮めた**。","vi":"Cảnh sát đã dẹp yên vụ náo loạn."},{"jp":"この薬は痛みを**鎮める**効果がある。","vi":"Thuốc này có tác dụng giảm đau."}],
  "769": [{"jp":"彼は**優れた**研究者だ。","vi":"Anh ấy là một nhà nghiên cứu xuất sắc."},{"jp":"この製品は性能が**優れて**いる。","vi":"Sản phẩm này có tính năng vượt trội."}],
  "770": [{"jp":"**落ち着いて**話してください。","vi":"Hãy bình tĩnh mà nói."},{"jp":"この部屋は**落ち着いた**雰囲気だ。","vi":"Căn phòng này có bầu không khí yên bình."},{"jp":"仕事がようやく**落ち着いた**。","vi":"Công việc cuối cùng cũng đã ổn định."}],
  "771": [{"jp":"会議が**長引いて**、帰りが遅くなった。","vi":"Cuộc họp kéo dài nên tôi về muộn."},{"jp":"風邪が**長引いて**困っている。","vi":"Tôi khổ sở vì cảm mãi không khỏi."}],
  "772": [{"jp":"年を取ると体力が**衰える**。","vi":"Có tuổi thì thể lực suy giảm."},{"jp":"その国の経済は**衰えて**きた。","vi":"Nền kinh tế nước đó đã sa sút."}],
  "773": [{"jp":"この部屋には最新の設備が**備わって**いる。","vi":"Căn phòng này được trang bị thiết bị mới nhất."},{"jp":"彼女には指導者としての資質が**備わって**いる。","vi":"Cô ấy có sẵn tố chất của một người lãnh đạo."}],
  "774": [{"jp":"地震に**備えて**水を買っておく。","vi":"Mua sẵn nước để phòng động đất."},{"jp":"このホテルは全室にWi-Fiを**備えて**いる。","vi":"Khách sạn này trang bị Wi-Fi cho tất cả các phòng."}],
  "775": [{"jp":"老後のためにお金を**蓄えて**いる。","vi":"Tôi đang tiết kiệm tiền cho tuổi già."},{"jp":"冬に備えて食料を**蓄える**。","vi":"Dự trữ lương thực để chuẩn bị cho mùa đông."},{"jp":"祖父は立派なひげを**蓄えて**いる。","vi":"Ông tôi để một bộ râu rất đẹp."}],
  "776": [{"jp":"出発の準備が**整った**。","vi":"Việc chuẩn bị xuất phát đã sẵn sàng."},{"jp":"この町は交通の便が**整って**いる。","vi":"Thị trấn này có giao thông thuận tiện."},{"jp":"彼女は**整った**顔立ちをしている。","vi":"Cô ấy có gương mặt cân đối."}],
  "777": [{"jp":"面接の前に服装を**整えた**。","vi":"Tôi chỉnh trang lại trang phục trước buổi phỏng vấn."},{"jp":"試合に向けて体調を**整える**。","vi":"Điều chỉnh thể trạng để chuẩn bị cho trận đấu."},{"jp":"塩で味を**調えて**ください。","vi":"Hãy nêm muối cho vừa vị."}],
  "778": [{"jp":"山が雪に**覆われて**いる。","vi":"Núi được bao phủ bởi tuyết."},{"jp":"彼女は両手で顔を**覆った**。","vi":"Cô ấy lấy hai tay che mặt."}],
  "779": [{"jp":"今日は日が**照って**暑い。","vi":"Hôm nay nắng chiếu nên nóng."},{"jp":"月が明るく**照って**いる。","vi":"Trăng đang chiếu sáng rực."}],
  "780": [{"jp":"懐中電灯で足元を**照らした**。","vi":"Tôi soi đèn pin xuống dưới chân."},{"jp":"街灯が夜道を**照らして**いる。","vi":"Đèn đường đang chiếu sáng con đường đêm."}],
  "781": [{"jp":"夕日で空が赤く**染まった**。","vi":"Bầu trời nhuộm đỏ bởi ánh hoàng hôn."},{"jp":"都会の悪い習慣に**染まって**しまった。","vi":"Tôi đã bị nhiễm thói xấu của thành phố."}],
  "782": [{"jp":"髪を茶色に**染めた**。","vi":"Tôi đã nhuộm tóc màu nâu."},{"jp":"彼女はほおを赤く**染めた**。","vi":"Cô ấy đỏ bừng má."}],
  "783": [{"jp":"会議の予定が**ダブって**しまった。","vi":"Lịch họp bị trùng nhau mất rồi."},{"jp":"同じ本を**ダブって**買ってしまった。","vi":"Tôi lỡ mua trùng hai cuốn sách giống nhau."},{"jp":"疲れて文字が**ダブって**見える。","vi":"Mệt quá nên chữ nhìn thành hai."}],
  "784": [{"jp":"子どもの頃、パイロットに**あこがれて**いた。","vi":"Hồi nhỏ, tôi từng mơ ước làm phi công."},{"jp":"都会の生活に**あこがれる**若者が多い。","vi":"Nhiều bạn trẻ khao khát cuộc sống thành thị."},{"jp":"彼女は先輩に**あこがれて**いる。","vi":"Cô ấy ngưỡng mộ đàn anh."}],
  "785": [{"jp":"人の成功を**うらやむ**必要はない。","vi":"Không cần phải ghen tị với thành công của người khác."},{"jp":"彼は皆に**うらやまれる**ほど幸せだ。","vi":"Anh ấy hạnh phúc đến mức ai cũng ghen tị."}],
  "786": [{"jp":"最後まで**あきらめない**でください。","vi":"Xin đừng bỏ cuộc cho đến cùng."},{"jp":"雨で旅行を**あきらめた**。","vi":"Vì mưa nên tôi đã từ bỏ chuyến du lịch."}],
  "787": [{"jp":"彼のわがままには**あきれた**。","vi":"Tôi sững sờ trước sự ích kỷ của anh ta."},{"jp":"**あきれて**ものが言えない。","vi":"Ngán ngẩm đến mức không nói nên lời."}],
  "788": [{"jp":"失敗を**恐れず**に挑戦しよう。","vi":"Hãy thử thách mà không sợ thất bại."},{"jp":"人々は戦争を**恐れて**いる。","vi":"Mọi người đang sợ hãi chiến tranh."}],
  "789": [{"jp":"彼は今でも父を**恨んで**いる。","vi":"Anh ấy đến giờ vẫn còn oán hận cha mình."},{"jp":"人を**恨んで**も何も変わらない。","vi":"Oán hận người khác cũng chẳng thay đổi được gì."}],
  "790": [{"jp":"試験に落ちた友人を**慰めた**。","vi":"Tôi đã an ủi người bạn thi trượt."},{"jp":"音楽に心を**慰められた**。","vi":"Âm nhạc đã xoa dịu tâm hồn tôi."}],
  "791": [{"jp":"部屋の**インテリア**を変えたい。","vi":"Tôi muốn thay đổi nội thất căn phòng."},{"jp":"彼女は**インテリア**のデザイナーです。","vi":"Cô ấy là nhà thiết kế nội thất."}],
  "792": [{"jp":"部屋の**コーナー**に棚を置いた。","vi":"Tôi đặt cái kệ ở góc phòng."},{"jp":"子ども服の**コーナー**は三階です。","vi":"Khu quần áo trẻ em ở tầng ba."},{"jp":"番組の人気**コーナー**が終わった。","vi":"Chuyên mục được yêu thích của chương trình đã kết thúc."}],
  "793": [{"jp":"**カウンター**でお会計をお願いします。","vi":"Xin vui lòng thanh toán tại quầy."},{"jp":"すし屋の**カウンター**に座った。","vi":"Tôi ngồi ở quầy của tiệm sushi."}],
  "794": [{"jp":"駐車**スペース**が見つからない。","vi":"Không tìm thấy chỗ đậu xe."},{"jp":"この部屋には机を置く**スペース**がない。","vi":"Phòng này không có chỗ để đặt bàn."}],
  "795": [{"jp":"駅前に新しいカフェが**オープン**した。","vi":"Một quán cà phê mới đã khai trương trước nhà ga."},{"jp":"彼は**オープン**な性格で話しやすい。","vi":"Anh ấy có tính cách cởi mở nên dễ nói chuyện."}],
  "796": [{"jp":"市民**センター**で講座が開かれる。","vi":"Khóa học được tổ chức tại trung tâm cộng đồng."},{"jp":"写真の**センター**に立っているのが兄です。","vi":"Người đứng ở giữa bức ảnh là anh trai tôi."}],
  "797": [{"jp":"日本の**カルチャー**に興味があります。","vi":"Tôi quan tâm đến văn hóa Nhật Bản."},{"jp":"母は**カルチャー**スクールに通っている。","vi":"Mẹ tôi đang theo học ở trung tâm văn hóa."}],
  "798": [{"jp":"今、キャンプが**ブーム**になっている。","vi":"Hiện nay cắm trại đang trở thành trào lưu."},{"jp":"その**ブーム**はすぐに終わった。","vi":"Cơn sốt đó đã nhanh chóng qua đi."}],
  "799": [{"jp":"空港の**インフォメーション**で聞いてみよう。","vi":"Hãy thử hỏi ở quầy thông tin sân bay."},{"jp":"最新の**インフォメーション**はウェブサイトで確認できます。","vi":"Có thể xem thông tin mới nhất trên trang web."}],
  "800": [{"jp":"彼はボールを片手で**キャッチ**した。","vi":"Anh ấy bắt bóng bằng một tay."},{"jp":"新しい情報をいち早く**キャッチ**する。","vi":"Nắm bắt thông tin mới nhanh nhất."}],
  "801": [{"jp":"その事件は多くの**メディア**で報道された。","vi":"Vụ việc đó đã được nhiều phương tiện truyền thông đưa tin."},{"jp":"**メディア**の影響力は大きい。","vi":"Sức ảnh hưởng của truyền thông rất lớn."}],
  "802": [{"jp":"首相は記者に**コメント**しなかった。","vi":"Thủ tướng không đưa ra bình luận với phóng viên."},{"jp":"動画にたくさんの**コメント**が付いた。","vi":"Video nhận được rất nhiều bình luận."}],
  "803": [{"jp":"毎朝、新聞の**コラム**を読んでいる。","vi":"Sáng nào tôi cũng đọc chuyên mục trên báo."},{"jp":"彼は雑誌に**コラム**を書いている。","vi":"Anh ấy viết bài chuyên mục cho tạp chí."}],
  "804": [{"jp":"先生の若い頃の**エピソード**を聞いた。","vi":"Tôi đã nghe giai thoại thời trẻ của thầy."},{"jp":"このドラマの第三**エピソード**が面白い。","vi":"Tập ba của bộ phim này rất hay."}],
  "805": [{"jp":"容疑者には**アリバイ**があった。","vi":"Nghi phạm có bằng chứng ngoại phạm."},{"jp":"彼の**アリバイ**は崩れた。","vi":"Bằng chứng ngoại phạm của anh ta đã bị phá vỡ."}],
  "806": [{"jp":"この映画は人気**シリーズ**の最新作だ。","vi":"Bộ phim này là phần mới nhất của loạt phim nổi tiếng."},{"jp":"その**シリーズ**の本を全部読んだ。","vi":"Tôi đã đọc hết bộ sách đó."}],
  "807": [{"jp":"話の**ポイント**をまとめてください。","vi":"Hãy tóm tắt những điểm chính của câu chuyện."},{"jp":"買い物をすると**ポイント**がたまる。","vi":"Mua sắm thì sẽ tích được điểm."}],
  "808": [{"jp":"車の**キー**をなくしてしまった。","vi":"Tôi làm mất chìa khóa xe rồi."},{"jp":"彼の証言が事件解決の**キー**になった。","vi":"Lời khai của anh ấy trở thành chìa khóa giải quyết vụ án."}],
  "809": [{"jp":"半年で日本語を**マスター**するのは難しい。","vi":"Thành thạo tiếng Nhật trong nửa năm là rất khó."},{"jp":"喫茶店の**マスター**はとても親切だ。","vi":"Ông chủ quán cà phê rất tốt bụng."}],
  "810": [{"jp":"彼は**ビジネス**で東京に来た。","vi":"Anh ấy đến Tokyo vì công việc kinh doanh."},{"jp":"新しい**ビジネス**を始めたい。","vi":"Tôi muốn bắt đầu một việc kinh doanh mới."}],
  "811": [{"jp":"彼女は**キャリア**を積んで部長になった。","vi":"Cô ấy tích lũy kinh nghiệm nghề nghiệp và trở thành trưởng phòng."},{"jp":"結婚後も**キャリア**を続けたい。","vi":"Tôi muốn tiếp tục sự nghiệp sau khi kết hôn."},{"jp":"スマホの**キャリア**を変えた。","vi":"Tôi đã đổi nhà mạng điện thoại."}],
  "812": [{"jp":"彼はこの道三十年の**ベテラン**だ。","vi":"Ông ấy là người kỳ cựu với 30 năm trong nghề."},{"jp":"**ベテラン**の先生に相談した。","vi":"Tôi đã hỏi ý kiến một giáo viên giàu kinh nghiệm."}],
  "813": [{"jp":"会社を辞めて**フリー**で働いている。","vi":"Tôi nghỉ việc ở công ty và làm việc tự do."},{"jp":"今週末は**フリー**なので会えます。","vi":"Cuối tuần này tôi rảnh nên có thể gặp."},{"jp":"このイベントは入場**フリー**です。","vi":"Sự kiện này vào cửa miễn phí."}],
  "814": [{"jp":"世界の**エコノミー**が変化している。","vi":"Nền kinh tế thế giới đang thay đổi."},{"jp":"飛行機は**エコノミー**クラスで行く。","vi":"Tôi đi máy bay hạng phổ thông."}],
  "815": [{"jp":"**キャッシュ**で払います。","vi":"Tôi trả bằng tiền mặt."},{"jp":"**キャッシュ**カードでお金を下ろした。","vi":"Tôi rút tiền bằng thẻ ATM."}],
  "816": [{"jp":"**インフレ**で物価が上がり続けている。","vi":"Do lạm phát, giá cả liên tục tăng."},{"jp":"政府は**インフレ**対策を発表した。","vi":"Chính phủ đã công bố biện pháp chống lạm phát."}],
  "817": [{"jp":"駅前で大規模な**デモ**が行われた。","vi":"Một cuộc biểu tình quy mô lớn đã diễn ra trước nhà ga."},{"jp":"新製品の**デモ**を見せてもらった。","vi":"Tôi được xem phần trình diễn sản phẩm mới."}],
  "818": [{"jp":"父は自動車**メーカー**に勤めている。","vi":"Bố tôi làm việc cho một hãng sản xuất ô tô."},{"jp":"この部品は**メーカー**に問い合わせてください。","vi":"Về linh kiện này, hãy liên hệ nhà sản xuất."}],
  "819": [{"jp":"会社の**システム**が変わった。","vi":"Hệ thống của công ty đã thay đổi."},{"jp":"**システム**のトラブルで電車が止まった。","vi":"Tàu bị dừng do sự cố hệ thống."}],
  "820": [{"jp":"こういう**ケース**は珍しい。","vi":"Trường hợp như thế này rất hiếm."},{"jp":"**ケース**によって対応が違う。","vi":"Tùy trường hợp mà cách xử lý khác nhau."}],
  "821": [{"jp":"彼の失敗にはいつも同じ**パターン**がある。","vi":"Thất bại của anh ấy luôn theo cùng một kiểu."},{"jp":"このシャツの**パターン**が好きだ。","vi":"Tôi thích họa tiết của chiếc áo sơ mi này."}],
  "822": [{"jp":"夏休みの旅行の**プラン**を立てた。","vi":"Tôi đã lập kế hoạch du lịch cho kỳ nghỉ hè."},{"jp":"携帯電話の料金**プラン**を変更した。","vi":"Tôi đã đổi gói cước điện thoại di động."}],
  "823": [{"jp":"隣の人と**トラブル**になった。","vi":"Tôi gặp rắc rối với người hàng xóm."},{"jp":"機械の**トラブル**で作業が止まった。","vi":"Công việc bị ngừng do sự cố máy móc."}],
  "824": [{"jp":"画面に**エラー**が表示された。","vi":"Màn hình hiện thông báo lỗi."},{"jp":"入力**エラー**がないか確認してください。","vi":"Hãy kiểm tra xem có lỗi nhập liệu không."}],
  "825": [{"jp":"客から**クレーム**が来た。","vi":"Khách hàng đã gửi phàn nàn."},{"jp":"**クレーム**には丁寧に対応しましょう。","vi":"Hãy xử lý khiếu nại một cách lịch sự."}],
  "826": [{"jp":"ホテルの予約を**キャンセル**した。","vi":"Tôi đã hủy đặt phòng khách sạn."},{"jp":"**キャンセル**料がかかります。","vi":"Sẽ mất phí hủy."}],
  "827": [{"jp":"大雪で電車が**ストップ**した。","vi":"Tàu bị dừng do tuyết rơi dày."},{"jp":"工事は一時**ストップ**している。","vi":"Công trình đang tạm ngừng."}],
  "828": [{"jp":"今年はボーナスが**カット**された。","vi":"Năm nay tiền thưởng bị cắt giảm."},{"jp":"美容院で髪を**カット**してもらった。","vi":"Tôi đã cắt tóc ở tiệm làm tóc."}],
  "829": [{"jp":"ソファに**カバー**をかけた。","vi":"Tôi đã phủ tấm bọc lên ghế sofa."},{"jp":"同僚のミスを**カバー**した。","vi":"Tôi đã che chắn, bù đắp cho lỗi của đồng nghiệp."}],
  "830": [{"jp":"手術後、**リハビリ**を続けている。","vi":"Sau phẫu thuật, tôi đang tiếp tục tập phục hồi chức năng."},{"jp":"**リハビリ**のおかげで歩けるようになった。","vi":"Nhờ tập phục hồi chức năng mà tôi đã đi lại được."}],
  "831": [{"jp":"試合前は**プレッシャー**を感じる。","vi":"Trước trận đấu, tôi cảm thấy áp lực."},{"jp":"部下に**プレッシャー**をかけすぎないように。","vi":"Đừng gây áp lực quá nhiều cho cấp dưới."}],
  "832": [{"jp":"悩みがあって**カウンセリング**を受けた。","vi":"Có chuyện phiền muộn nên tôi đã đi tư vấn tâm lý."},{"jp":"学校には**カウンセリング**室がある。","vi":"Trường có phòng tư vấn."}],
  "833": [{"jp":"彼は明るい**キャラクター**で人気がある。","vi":"Anh ấy được yêu mến nhờ tính cách vui vẻ."},{"jp":"このアニメの**キャラクター**が好きだ。","vi":"Tôi thích nhân vật trong bộ anime này."}],
  "834": [{"jp":"彼は**ユニークな**アイデアを持っている。","vi":"Anh ấy có những ý tưởng độc đáo."},{"jp":"この建物はデザインが**ユニークだ**。","vi":"Tòa nhà này có thiết kế độc đáo."}],
  "835": [{"jp":"彼は時間に**ルーズな**人だ。","vi":"Anh ấy là người không đúng giờ."},{"jp":"お金に**ルーズな**のはよくない。","vi":"Cẩu thả trong chuyện tiền bạc là không tốt."}],
  "836": [{"jp":"夜景がとても**ロマンチックだった**。","vi":"Cảnh đêm thật lãng mạn."},{"jp":"**ロマンチックな**映画を見た。","vi":"Tôi đã xem một bộ phim lãng mạn."}],
  "837": [{"jp":"彼女は服の**センス**がいい。","vi":"Cô ấy có gu ăn mặc đẹp."},{"jp":"彼にはユーモアの**センス**がある。","vi":"Anh ấy có khiếu hài hước."}],
  "838": [{"jp":"**エコロジー**に関心を持つ人が増えた。","vi":"Số người quan tâm đến sinh thái học đã tăng lên."},{"jp":"大学で**エコロジー**を学んでいる。","vi":"Tôi đang học ngành sinh thái học ở đại học."}],
  "839": [{"jp":"川の上流に大きな**ダム**が造られた。","vi":"Một con đập lớn được xây ở thượng nguồn sông."},{"jp":"雨不足で**ダム**の水が減っている。","vi":"Do thiếu mưa nên nước trong đập đang giảm."}],
  "840": [{"jp":"この建物は**コンクリート**でできている。","vi":"Tòa nhà này được làm bằng bê tông."},{"jp":"庭を**コンクリート**で固めた。","vi":"Tôi đã đổ bê tông khoảng sân."}],
  "841": [{"jp":"これは**単純な**計算ミスだ。","vi":"Đây là lỗi tính toán đơn giản."},{"jp":"彼は**単純だ**から、すぐ信じてしまう。","vi":"Anh ấy đơn giản nên tin ngay."}],
  "842": [{"jp":"子どもは**純粋な**心を持っている。","vi":"Trẻ em có tâm hồn trong sáng."},{"jp":"これは**純粋な**金でできている。","vi":"Cái này được làm bằng vàng nguyên chất."}],
  "843": [{"jp":"**透明な**ガラスのコップを買った。","vi":"Tôi đã mua một chiếc cốc thủy tinh trong suốt."},{"jp":"政治はもっと**透明で**あるべきだ。","vi":"Chính trị nên minh bạch hơn."}],
  "844": [{"jp":"朝の**爽やかな**空気を吸った。","vi":"Tôi hít thở bầu không khí trong lành buổi sáng."},{"jp":"彼は**爽やかな**笑顔の青年だ。","vi":"Anh ấy là chàng trai có nụ cười tươi tắn."}],
  "845": [{"jp":"あの子は**素直で**かわいい。","vi":"Đứa bé đó ngoan ngoãn và dễ thương."},{"jp":"**素直に**謝ったほうがいい。","vi":"Nên thành thật xin lỗi thì hơn."}],
  "846": [{"jp":"**率直な**意見を聞かせてください。","vi":"Hãy cho tôi nghe ý kiến thẳng thắn của bạn."},{"jp":"**率直に**言うと、この案には反対です。","vi":"Nói thẳng ra thì tôi phản đối phương án này."}],
  "847": [{"jp":"彼は**誠実な**人なので信頼できる。","vi":"Anh ấy là người thật thà nên có thể tin tưởng."},{"jp":"お客様には**誠実に**対応しなさい。","vi":"Hãy đối xử chân thành với khách hàng."}],
  "848": [{"jp":"彼は成功しても**謙虚だ**。","vi":"Dù thành công anh ấy vẫn khiêm tốn."},{"jp":"人の意見を**謙虚に**聞くことが大切だ。","vi":"Lắng nghe ý kiến người khác một cách khiêm tốn là điều quan trọng."}],
  "849": [{"jp":"この犬はとても**賢い**。","vi":"Con chó này rất thông minh."},{"jp":"それは**賢い**選択だと思う。","vi":"Tôi nghĩ đó là một lựa chọn khôn ngoan."}],
  "850": [{"jp":"彼は何事にも**慎重な**人だ。","vi":"Anh ấy là người thận trọng trong mọi việc."},{"jp":"**慎重に**運転してください。","vi":"Hãy lái xe cẩn thận."}],
  "851": [{"jp":"今日は**穏やかな**天気だ。","vi":"Hôm nay thời tiết êm dịu."},{"jp":"祖母は**穏やかな**性格の人だ。","vi":"Bà tôi là người có tính cách điềm đạm."}],
  "852": [{"jp":"彼は**真剣な**顔で話を聞いていた。","vi":"Anh ấy lắng nghe với vẻ mặt nghiêm túc."},{"jp":"将来について**真剣に**考えるべきだ。","vi":"Nên suy nghĩ nghiêm túc về tương lai."}],
  "853": [{"jp":"結果は来週**正式に**発表される。","vi":"Kết quả sẽ được công bố chính thức vào tuần sau."},{"jp":"**正式な**場ではスーツを着ます。","vi":"Ở những nơi trang trọng thì mặc com-lê."}],
  "854": [{"jp":"この国の**主な**産業は農業だ。","vi":"Ngành công nghiệp chính của nước này là nông nghiệp."},{"jp":"会議の**主な**議題を確認しよう。","vi":"Hãy xác nhận các chủ đề chính của cuộc họp."}],
  "855": [{"jp":"日本の**主要な**都市を訪れた。","vi":"Tôi đã đến thăm các thành phố chủ yếu của Nhật."},{"jp":"彼はチームの**主要な**メンバーだ。","vi":"Anh ấy là thành viên chủ chốt của đội."}],
  "856": [{"jp":"**貴重な**経験をさせていただきました。","vi":"Tôi đã có được một trải nghiệm quý giá."},{"jp":"**貴重な**時間を割いてくれてありがとう。","vi":"Cảm ơn bạn đã dành thời gian quý báu."}],
  "857": [{"jp":"彼は**偉大な**科学者として知られている。","vi":"Ông ấy được biết đến như một nhà khoa học vĩ đại."},{"jp":"母の愛は**偉大だ**。","vi":"Tình mẹ thật vĩ đại."}],
  "858": [{"jp":"一人で全部やったなんて、**偉い**ね。","vi":"Tự mình làm hết tất cả, giỏi quá nhỉ."},{"jp":"彼は会社で**偉い**人だ。","vi":"Ông ấy là người có chức vụ cao trong công ty."}],
  "859": [{"jp":"この料理には**独特な**香りがある。","vi":"Món ăn này có mùi hương đặc trưng."},{"jp":"彼の絵は**独特な**雰囲気を持っている。","vi":"Tranh của anh ấy mang một bầu không khí độc đáo."}],
  "860": [{"jp":"これは**特殊な**ケースです。","vi":"Đây là một trường hợp đặc biệt."},{"jp":"この仕事には**特殊な**技術が必要だ。","vi":"Công việc này cần kỹ thuật đặc thù."}],
  "861": [{"jp":"昨夜、**奇妙な**夢を見た。","vi":"Đêm qua tôi đã có một giấc mơ kỳ lạ."},{"jp":"**奇妙な**音が聞こえてきた。","vi":"Có một âm thanh kỳ lạ vọng đến."}],
  "862": [{"jp":"彼の態度はなんだか**妙だ**。","vi":"Thái độ của anh ấy có gì đó lạ lạ."},{"jp":"**妙な**うわさを耳にした。","vi":"Tôi đã nghe được một tin đồn kỳ lạ."}],
  "863": [{"jp":"家の前に**怪しい**男が立っている。","vi":"Có một người đàn ông khả nghi đứng trước nhà."},{"jp":"その話は本当かどうか**怪しい**。","vi":"Câu chuyện đó thật hay không thì còn đáng ngờ."},{"jp":"空が**怪しく**なってきた。","vi":"Trời bắt đầu có vẻ muốn mưa."}],
  "864": [{"jp":"今年の夏は**異常な**暑さだ。","vi":"Mùa hè năm nay nóng bất thường."},{"jp":"検査の結果、**異常**はなかった。","vi":"Kết quả kiểm tra không có gì bất thường."}],
  "865": [{"jp":"この仕事には**高度な**技術が必要だ。","vi":"Công việc này đòi hỏi kỹ thuật cao."},{"jp":"**高度な**医療を受けられる病院だ。","vi":"Đây là bệnh viện có thể điều trị y tế tiên tiến."}],
  "866": [{"jp":"**新たな**問題が発生した。","vi":"Một vấn đề mới đã phát sinh."},{"jp":"**新たに**店長が来ることになった。","vi":"Sắp có một cửa hàng trưởng mới đến."}],
  "867": [{"jp":"もっと**合理的な**方法を考えよう。","vi":"Hãy nghĩ ra cách làm hợp lý hơn."},{"jp":"彼の説明は**合理的だ**。","vi":"Lời giải thích của anh ấy hợp lý."}],
  "868": [{"jp":"彼は手先が**器用だ**。","vi":"Anh ấy khéo tay."},{"jp":"彼女は何でも**器用に**こなす。","vi":"Cô ấy làm việc gì cũng khéo léo."}],
  "869": [{"jp":"**手軽な**料理を教えてください。","vi":"Hãy chỉ tôi những món ăn đơn giản."},{"jp":"スマホで**手軽に**買い物ができる。","vi":"Có thể mua sắm dễ dàng bằng điện thoại."}],
  "870": [{"jp":"**手ごろな**値段のレストランを探している。","vi":"Tôi đang tìm nhà hàng giá cả phải chăng."},{"jp":"このかばんは旅行に**手ごろな**大きさだ。","vi":"Cái túi này có kích thước vừa phải để đi du lịch."}],
  "871": [{"jp":"この時計はとても**高価な**ものです。","vi":"Chiếc đồng hồ này là đồ rất đắt tiền."},{"jp":"**高価な**プレゼントはもらえません。","vi":"Tôi không thể nhận món quà đắt tiền như vậy."}],
  "872": [{"jp":"彼は**ぜいたくな**生活をしている。","vi":"Anh ấy đang sống một cuộc sống xa hoa."},{"jp":"たまには**ぜいたく**をしてもいいでしょう。","vi":"Thỉnh thoảng xa xỉ một chút cũng được mà."},{"jp":"水を無駄に使うのは**ぜいたくだ**。","vi":"Dùng nước lãng phí là xa xỉ."}],
  "873": [{"jp":"ホテルの**豪華な**料理に驚いた。","vi":"Tôi ngạc nhiên trước những món ăn thịnh soạn của khách sạn."},{"jp":"**豪華な**結婚式を挙げた。","vi":"Họ đã tổ chức một đám cưới hoành tráng."}],
  "874": [{"jp":"**高級な**レストランで食事をした。","vi":"Tôi đã dùng bữa ở một nhà hàng cao cấp."},{"jp":"これは**高級な**ワインだそうです。","vi":"Nghe nói đây là loại rượu vang cao cấp."}],
  "875": [{"jp":"**上等な**スーツを買った。","vi":"Tôi đã mua một bộ vest hàng xịn."},{"jp":"このお茶は**上等な**葉を使っている。","vi":"Trà này dùng loại lá cao cấp."}],
  "876": [{"jp":"彼女は話し方が**上品だ**。","vi":"Cô ấy có cách nói chuyện thanh lịch."},{"jp":"**上品な**色のドレスですね。","vi":"Chiếc váy có màu sắc thật trang nhã."}],
  "877": [{"jp":"**適度な**運動は健康にいい。","vi":"Vận động vừa phải tốt cho sức khỏe."},{"jp":"お酒は**適度に**飲みましょう。","vi":"Hãy uống rượu điều độ."}],
  "878": [{"jp":"新しい部屋はとても**快適だ**。","vi":"Căn phòng mới rất dễ chịu."},{"jp":"**快適な**旅をお楽しみください。","vi":"Chúc quý khách có chuyến đi thoải mái."}],
  "879": [{"jp":"朝の風が**快い**。","vi":"Gió buổi sáng thật dễ chịu."},{"jp":"彼は**快く**引き受けてくれた。","vi":"Anh ấy đã vui vẻ nhận lời."}],
  "880": [{"jp":"工事は**順調に**進んでいます。","vi":"Công trình đang tiến triển thuận lợi."},{"jp":"手術後の回復は**順調だ**。","vi":"Sự hồi phục sau phẫu thuật diễn ra tốt đẹp."}],
  "881": [{"jp":"彼女は**活発な**子どもだ。","vi":"Cô bé là một đứa trẻ hoạt bát."},{"jp":"会議で**活発な**議論が行われた。","vi":"Trong cuộc họp đã diễn ra những cuộc thảo luận sôi nổi."}],
  "882": [{"jp":"先生は**的確な**アドバイスをくれた。","vi":"Thầy đã cho tôi lời khuyên chính xác."},{"jp":"状況を**的確に**判断する。","vi":"Phán đoán tình hình một cách chính xác."}],
  "883": [{"jp":"彼の合格はほぼ**確実だ**。","vi":"Việc anh ấy đỗ gần như là chắc chắn."},{"jp":"**確実な**方法を選びましょう。","vi":"Hãy chọn phương pháp chắc chắn."}],
  "884": [{"jp":"彼が犯人なのは**明らかだ**。","vi":"Rõ ràng anh ta là thủ phạm."},{"jp":"調査で事実が**明らかに**なった。","vi":"Qua điều tra, sự thật đã được làm rõ."}],
  "885": [{"jp":"彼の返事はいつも**あいまいだ**。","vi":"Câu trả lời của anh ấy lúc nào cũng mơ hồ."},{"jp":"**あいまいな**記憶しかない。","vi":"Tôi chỉ còn lại ký ức mơ hồ."}],
  "886": [{"jp":"もっと**具体的な**例を挙げてください。","vi":"Hãy đưa ra ví dụ cụ thể hơn."},{"jp":"計画を**具体的に**説明する。","vi":"Giải thích kế hoạch một cách cụ thể."}],
  "887": [{"jp":"この絵は**抽象的で**よくわからない。","vi":"Bức tranh này trừu tượng nên tôi không hiểu lắm."},{"jp":"彼の説明は**抽象的すぎる**。","vi":"Lời giải thích của anh ấy quá trừu tượng."}],
  "888": [{"jp":"二つの三角形の面積は**等しい**。","vi":"Diện tích hai hình tam giác bằng nhau."},{"jp":"利益を**等しく**分けた。","vi":"Lợi nhuận đã được chia đều."}],
  "889": [{"jp":"すべての人は法の下に**平等だ**。","vi":"Mọi người đều bình đẳng trước pháp luật."},{"jp":"男女**平等な**社会を目指す。","vi":"Hướng tới một xã hội bình đẳng nam nữ."}],
  "890": [{"jp":"審判は**公平な**判断をした。","vi":"Trọng tài đã đưa ra phán quyết công bằng."},{"jp":"仕事を**公平に**分けましょう。","vi":"Hãy chia việc một cách công bằng."}],
  "891": [{"jp":"彼は信頼できる**人物**だ。","vi":"Anh ấy là người đáng tin cậy."},{"jp":"この小説の登場**人物**は多い。","vi":"Cuốn tiểu thuyết này có nhiều nhân vật."}],
  "892": [{"jp":"私は田中という**者**です。","vi":"Tôi là người tên Tanaka."},{"jp":"怪しい**者**が家の前にいた。","vi":"Có kẻ khả nghi đứng trước nhà."}],
  "893": [{"jp":"昼食は**各自**で用意してください。","vi":"Mỗi người hãy tự chuẩn bị bữa trưa."},{"jp":"**各自**の意見を発表する。","vi":"Từng người phát biểu ý kiến của mình."}],
  "894": [{"jp":"今日は**気分**がいい。","vi":"Hôm nay tâm trạng tôi tốt."},{"jp":"**気分**が悪いので早退します。","vi":"Tôi thấy khó chịu nên xin về sớm."},{"jp":"旅行で**気分**転換をした。","vi":"Tôi đi du lịch để thay đổi tâm trạng."}],
  "895": [{"jp":"後ろに人の**気配**を感じた。","vi":"Tôi cảm thấy có người ở phía sau."},{"jp":"雨がやむ**気配**はない。","vi":"Không có dấu hiệu gì là mưa sẽ tạnh."}],
  "896": [{"jp":"仕事が私の**生きがい**です。","vi":"Công việc là lẽ sống của tôi."},{"jp":"老後の**生きがい**を見つけたい。","vi":"Tôi muốn tìm mục đích sống cho tuổi già."}],
  "897": [{"jp":"あの子は**行儀**がいい。","vi":"Đứa bé đó rất ngoan, lễ phép."},{"jp":"食事中は**行儀**よくしなさい。","vi":"Trong bữa ăn hãy cư xử cho đàng hoàng."}],
  "898": [{"jp":"彼女の話し方には**品**がある。","vi":"Cách nói chuyện của cô ấy rất thanh lịch."},{"jp":"そんな**品**のない言葉を使わないで。","vi":"Đừng dùng những lời lẽ thiếu văn hóa như thế."}],
  "899": [{"jp":"遠くに母の**姿**が見えた。","vi":"Tôi thấy bóng dáng mẹ ở đằng xa."},{"jp":"彼はその日から**姿**を消した。","vi":"Từ hôm đó anh ấy biến mất tăm."}],
  "900": [{"jp":"**姿勢**を正して座りなさい。","vi":"Hãy ngồi cho ngay ngắn."},{"jp":"彼の前向きな**姿勢**を評価する。","vi":"Tôi đánh giá cao thái độ tích cực của anh ấy."}],
  "901": [{"jp":"人を**見かけ**で判断してはいけない。","vi":"Không được đánh giá người khác qua vẻ bề ngoài."},{"jp":"この店は**見かけ**より安い。","vi":"Cửa hàng này rẻ hơn so với vẻ bề ngoài."}],
  "902": [{"jp":"彼は寝た**ふり**をしていた。","vi":"Anh ấy đã giả vờ ngủ."},{"jp":"知らない**ふり**をしないで。","vi":"Đừng giả vờ không biết."}],
  "903": [{"jp":"隣の人から騒音の**苦情**が来た。","vi":"Hàng xóm đã phàn nàn về tiếng ồn."},{"jp":"客の**苦情**に丁寧に対応する。","vi":"Xử lý lời phàn nàn của khách một cách lịch sự."}],
  "904": [{"jp":"病気を**口実**に会社を休んだ。","vi":"Anh ta lấy cớ bị ốm để nghỉ làm."},{"jp":"断る**口実**を考えている。","vi":"Tôi đang nghĩ cớ để từ chối."}],
  "905": [{"jp":"犯行の**動機**はまだ不明だ。","vi":"Động cơ gây án vẫn chưa rõ."},{"jp":"日本語を学ぶ**動機**は何ですか。","vi":"Động cơ học tiếng Nhật của bạn là gì?"}],
  "906": [{"jp":"彼はよく**皮肉**を言う。","vi":"Anh ta hay nói mỉa mai."},{"jp":"**皮肉な**ことに、休みの日に雨が降った。","vi":"Trớ trêu thay, trời lại mưa vào ngày nghỉ."}],
  "907": [{"jp":"この研究には大きな**意義**がある。","vi":"Nghiên cứu này có ý nghĩa lớn."},{"jp":"**意義**のある時間を過ごした。","vi":"Tôi đã trải qua khoảng thời gian ý nghĩa."}],
  "908": [{"jp":"彼は自分の**主義**を曲げない。","vi":"Anh ấy không bao giờ đi ngược nguyên tắc của mình."},{"jp":"借金はしない**主義**です。","vi":"Nguyên tắc của tôi là không vay nợ."}],
  "909": [{"jp":"スポーツは**精神**を鍛える。","vi":"Thể thao rèn luyện tinh thần."},{"jp":"**精神**的に疲れている。","vi":"Tôi đang mệt mỏi về mặt tinh thần."}],
  "910": [{"jp":"1980**年代**の音楽が好きだ。","vi":"Tôi thích âm nhạc thập niên 1980."},{"jp":"この寺の**年代**は不明だ。","vi":"Niên đại của ngôi chùa này không rõ."}],
  "911": [{"jp":"**世代**によって考え方が違う。","vi":"Cách suy nghĩ khác nhau tùy theo thế hệ."},{"jp":"若い**世代**に技術を伝える。","vi":"Truyền lại kỹ thuật cho thế hệ trẻ."}],
  "912": [{"jp":"何事も**基礎**が大切だ。","vi":"Việc gì thì nền tảng cũng quan trọng."},{"jp":"**基礎**から日本語を勉強し直す。","vi":"Học lại tiếng Nhật từ cơ bản."}],
  "913": [{"jp":"合格の**基準**は60点です。","vi":"Tiêu chuẩn đỗ là 60 điểm."},{"jp":"安全**基準**を満たしていない。","vi":"Không đáp ứng tiêu chuẩn an toàn."}],
  "914": [{"jp":"彼の身長は**標準**より高い。","vi":"Chiều cao của anh ấy cao hơn mức chuẩn."},{"jp":"**標準**語で話してください。","vi":"Hãy nói bằng tiếng chuẩn."}],
  "915": [{"jp":"彼は**典型**的な日本人だ。","vi":"Anh ấy là người Nhật điển hình."},{"jp":"これは失敗の**典型**だ。","vi":"Đây là ví dụ điển hình của thất bại."}],
  "916": [{"jp":"祖母は**方言**で話す。","vi":"Bà tôi nói bằng tiếng địa phương."},{"jp":"大阪の**方言**は面白い。","vi":"Tiếng địa phương Osaka thật thú vị."}],
  "917": [{"jp":"この植物は全国に**分布**している。","vi":"Loài thực vật này phân bố khắp cả nước."},{"jp":"人口の**分布**を調べる。","vi":"Điều tra sự phân bố dân cư."}],
  "918": [{"jp":"町は急速に**発展**した。","vi":"Thị trấn đã phát triển nhanh chóng."},{"jp":"経済の**発展**に貢献する。","vi":"Góp phần vào sự phát triển kinh tế."}],
  "919": [{"jp":"古代**文明**について学ぶ。","vi":"Học về các nền văn minh cổ đại."},{"jp":"**文明**の発達で生活が便利になった。","vi":"Nhờ văn minh phát triển, cuộc sống trở nên tiện lợi."}],
  "920": [{"jp":"スマホが急速に**普及**した。","vi":"Điện thoại thông minh đã phổ biến nhanh chóng."},{"jp":"新しい技術の**普及**を進める。","vi":"Thúc đẩy việc phổ cập công nghệ mới."}],
  "921": [{"jp":"この道路は速度**制限**が厳しい。","vi":"Con đường này giới hạn tốc độ nghiêm ngặt."},{"jp":"参加人数を**制限**する。","vi":"Hạn chế số người tham gia."}],
  "922": [{"jp":"我慢にも**限度**がある。","vi":"Sự chịu đựng cũng có giới hạn."},{"jp":"カードの利用**限度**額を超えた。","vi":"Tôi đã vượt quá hạn mức sử dụng thẻ."}],
  "923": [{"jp":"体力の**限界**を感じた。","vi":"Tôi cảm thấy đã đến giới hạn thể lực."},{"jp":"一人でできることには**限界**がある。","vi":"Những việc một người làm được có giới hạn."}],
  "924": [{"jp":"その案を前向きに**検討**します。","vi":"Chúng tôi sẽ xem xét đề án đó một cách tích cực."},{"jp":"計画を**検討**し直す必要がある。","vi":"Cần xem xét lại kế hoạch."}],
  "925": [{"jp":"正しい**選択**をしたと思う。","vi":"Tôi nghĩ mình đã lựa chọn đúng."},{"jp":"**選択**科目は何にしましたか。","vi":"Bạn đã chọn môn tự chọn nào?"}],
  "926": [{"jp":"天候を**考慮**して日程を決める。","vi":"Quyết định lịch trình có xem xét đến thời tiết."},{"jp":"相手の気持ちも**考慮**すべきだ。","vi":"Nên cân nhắc cả cảm xúc của đối phương."}],
  "927": [{"jp":"この会社は経験を**重視**する。","vi":"Công ty này coi trọng kinh nghiệm."},{"jp":"安全を**重視**して設計した。","vi":"Thiết kế với sự chú trọng đến an toàn."}],
  "928": [{"jp":"犯人の**見当**がつかない。","vi":"Tôi không đoán được ai là thủ phạm."},{"jp":"大体の**見当**をつけて、駅の方へ歩いた。","vi":"Tôi ước chừng phương hướng rồi đi về phía nhà ga."},{"jp":"彼の答えは**見当**違いだった。","vi":"Câu trả lời của anh ấy hoàn toàn trật lất."}],
  "929": [{"jp":"記事の誤りを**訂正**する。","vi":"Đính chính lỗi sai trong bài báo."},{"jp":"先ほどの発言を**訂正**させてください。","vi":"Cho phép tôi đính chính lời phát biểu lúc nãy."}],
  "930": [{"jp":"計画を一部**修正**した。","vi":"Tôi đã chỉnh sửa một phần kế hoạch."},{"jp":"写真を**修正**してきれいにする。","vi":"Chỉnh sửa ảnh cho đẹp."}],
  "931": [{"jp":"息子は親に**反抗**ばかりする。","vi":"Con trai tôi suốt ngày cãi lời bố mẹ."},{"jp":"中学生は**反抗**期だ。","vi":"Học sinh cấp hai đang ở tuổi nổi loạn."}],
  "932": [{"jp":"犯人は**抵抗**せずに捕まった。","vi":"Thủ phạm bị bắt mà không kháng cự."},{"jp":"人前で話すのに**抵抗**がある。","vi":"Tôi ngại nói trước đám đông."}],
  "933": [{"jp":"旅行中に**災難**に遭った。","vi":"Tôi gặp tai họa trong chuyến du lịch."},{"jp":"財布を盗まれるなんて、とんだ**災難**だったね。","vi":"Bị trộm ví, đúng là xui xẻo thật nhỉ."}],
  "934": [{"jp":"川の**汚染**が深刻だ。","vi":"Ô nhiễm sông ngòi đang nghiêm trọng."},{"jp":"工場の排水で海が**汚染**された。","vi":"Biển bị ô nhiễm do nước thải nhà máy."}],
  "935": [{"jp":"たばこは健康に**害**がある。","vi":"Thuốc lá có hại cho sức khỏe."},{"jp":"虫による農作物の**害**が増えた。","vi":"Thiệt hại cây trồng do sâu bọ đã tăng lên."}],
  "936": [{"jp":"この病気は**伝染**する恐れがある。","vi":"Bệnh này có nguy cơ lây lan."},{"jp":"あくびは**伝染**するらしい。","vi":"Nghe nói ngáp có thể lây."}],
  "937": [{"jp":"地震の**対策**を立てる。","vi":"Lập biện pháp đối phó với động đất."},{"jp":"政府は少子化**対策**を発表した。","vi":"Chính phủ đã công bố biện pháp đối phó với tình trạng giảm sinh."}],
  "938": [{"jp":"けが人に応急**処置**をした。","vi":"Tôi đã sơ cứu cho người bị thương."},{"jp":"早めの**処置**が必要だ。","vi":"Cần xử lý sớm."}],
  "939": [{"jp":"古い家具を**処分**した。","vi":"Tôi đã thanh lý đồ đạc cũ."},{"jp":"規則を破った社員が**処分**された。","vi":"Nhân viên vi phạm quy định đã bị kỷ luật."}],
  "940": [{"jp":"ごみの**処理**に困っている。","vi":"Tôi đang gặp khó khăn trong việc xử lý rác."},{"jp":"このパソコンはデータの**処理**が速い。","vi":"Máy tính này xử lý dữ liệu nhanh."}],
  "941": [{"jp":"みんなで**輪**になって踊った。","vi":"Mọi người đứng thành vòng tròn và nhảy múa."},{"jp":"友情の**輪**を広げよう。","vi":"Hãy mở rộng vòng tròn tình bạn."}],
  "942": [{"jp":"この道は**でこぼこ**で歩きにくい。","vi":"Con đường này gồ ghề khó đi."},{"jp":"**でこぼこ**の道を車で走った。","vi":"Tôi lái xe trên con đường đầy ổ gà."}],
  "943": [{"jp":"雪の上に足の**跡**が残っている。","vi":"Trên tuyết còn lại dấu chân."},{"jp":"ここは古い城の**跡**だ。","vi":"Đây là di tích của một tòa thành cổ."}],
  "944": [{"jp":"この料理は**手間**がかかる。","vi":"Món ăn này tốn công."},{"jp":"お**手間**を取らせてすみません。","vi":"Xin lỗi đã làm mất thời gian của anh."}],
  "945": [{"jp":"朝のほうが仕事の**能率**が上がる。","vi":"Buổi sáng hiệu suất làm việc cao hơn."},{"jp":"**能率**のいい方法を考えよう。","vi":"Hãy nghĩ cách làm hiệu quả."}],
  "946": [{"jp":"このカメラは**性能**がいい。","vi":"Chiếc máy ảnh này có tính năng tốt."},{"jp":"新型車は**性能**が向上した。","vi":"Mẫu xe mới đã được nâng cao hiệu năng."}],
  "947": [{"jp":"この機械は**操作**が簡単だ。","vi":"Máy này thao tác đơn giản."},{"jp":"スマホの**操作**に慣れない。","vi":"Tôi chưa quen thao tác điện thoại thông minh."}],
  "948": [{"jp":"試合で実力を**発揮**した。","vi":"Anh ấy đã phát huy thực lực trong trận đấu."},{"jp":"彼女はリーダーシップを**発揮**した。","vi":"Cô ấy đã thể hiện khả năng lãnh đạo."}],
  "949": [{"jp":"山の**頂点**に立った。","vi":"Tôi đã đứng trên đỉnh núi."},{"jp":"彼は人気の**頂点**にいる。","vi":"Anh ấy đang ở đỉnh cao sự nổi tiếng."}],
  "950": [{"jp":"駅の**周辺**は店が多い。","vi":"Xung quanh nhà ga có nhiều cửa hàng."},{"jp":"東京**周辺**に住んでいる。","vi":"Tôi sống ở khu vực quanh Tokyo."}],
  "951": [{"jp":"警察が事故の**現場**に着いた。","vi":"Cảnh sát đã đến hiện trường vụ tai nạn."},{"jp":"工事**現場**で働いている。","vi":"Tôi làm việc ở công trường."}],
  "952": [{"jp":"今の**状況**を説明してください。","vi":"Hãy giải thích tình hình hiện tại."},{"jp":"経済の**状況**が悪化している。","vi":"Tình hình kinh tế đang xấu đi."}],
  "953": [{"jp":"大きな**組織**で働くのは大変だ。","vi":"Làm việc trong một tổ chức lớn thật vất vả."},{"jp":"新しいチームを**組織**した。","vi":"Đã thành lập một đội mới."}],
  "954": [{"jp":"新しい**制度**が来年から始まる。","vi":"Chế độ mới sẽ bắt đầu từ năm sau."},{"jp":"日本の教育**制度**を調べる。","vi":"Tìm hiểu chế độ giáo dục của Nhật Bản."}],
  "955": [{"jp":"この本は三部で**構成**されている。","vi":"Cuốn sách này gồm ba phần."},{"jp":"家族**構成**を教えてください。","vi":"Hãy cho biết thành phần gia đình bạn."}],
  "956": [{"jp":"決まった**形式**で書類を書く。","vi":"Viết hồ sơ theo mẫu quy định."},{"jp":"試験は面接**形式**で行われる。","vi":"Kỳ thi được tiến hành theo hình thức phỏng vấn."}],
  "957": [{"jp":"最近、若者の車離れの**傾向**がある。","vi":"Gần đây có xu hướng giới trẻ không mặn mà với ô tô."},{"jp":"彼は物事を悪く考える**傾向**がある。","vi":"Anh ấy có khuynh hướng nghĩ tiêu cực về mọi việc."}],
  "958": [{"jp":"会社の**方針**が変わった。","vi":"Phương châm của công ty đã thay đổi."},{"jp":"政府の**方針**に従う。","vi":"Tuân theo chính sách của chính phủ."}],
  "959": [{"jp":"安全管理を**徹底**する。","vi":"Quản lý an toàn một cách triệt để."},{"jp":"**徹底**的に調べてください。","vi":"Hãy điều tra triệt để."}],
  "960": [{"jp":"データを**分析**して報告する。","vi":"Phân tích dữ liệu rồi báo cáo."},{"jp":"失敗の原因を**分析**する。","vi":"Phân tích nguyên nhân thất bại."}],
  "961": [{"jp":"健康を**維持**するために運動する。","vi":"Tôi tập thể dục để duy trì sức khỏe."},{"jp":"平和を**維持**することが大切だ。","vi":"Việc duy trì hòa bình là quan trọng."}],
  "962": [{"jp":"マンションの**管理**人に連絡する。","vi":"Liên lạc với người quản lý chung cư."},{"jp":"薬は涼しい所で**管理**してください。","vi":"Hãy bảo quản thuốc ở nơi thoáng mát."},{"jp":"体調の**管理**も仕事のうちだ。","vi":"Quản lý sức khỏe cũng là một phần công việc."}],
  "963": [{"jp":"犯人の**行方**はまだわからない。","vi":"Tung tích của thủ phạm vẫn chưa rõ."},{"jp":"試合の**行方**が気になる。","vi":"Tôi lo lắng về diễn biến của trận đấu."}],
  "964": [{"jp":"道の**端**を歩いてください。","vi":"Hãy đi bên lề đường."},{"jp":"机の**端**に本を置いた。","vi":"Tôi để sách ở mép bàn."}],
  "965": [{"jp":"その**場**で答えを決めた。","vi":"Tôi đã quyết định câu trả lời ngay tại chỗ."},{"jp":"**場**の雰囲気を読むのは難しい。","vi":"Đọc được bầu không khí của hoàn cảnh thật khó."},{"jp":"練習の**場**を増やしたい。","vi":"Tôi muốn có thêm cơ hội luyện tập."}],
  "966": [{"jp":"彼は医学の**分野**で有名だ。","vi":"Ông ấy nổi tiếng trong lĩnh vực y học."},{"jp":"得意な**分野**は何ですか。","vi":"Lĩnh vực sở trường của bạn là gì?"}],
  "967": [{"jp":"夏は電力の**需要**が増える。","vi":"Mùa hè nhu cầu điện tăng lên."},{"jp":"介護の**需要**が高まっている。","vi":"Nhu cầu chăm sóc người già đang tăng cao."}],
  "968": [{"jp":"被災地に水を**供給**する。","vi":"Cung cấp nước cho vùng bị thiên tai."},{"jp":"需要に**供給**が追いつかない。","vi":"Nguồn cung không theo kịp nhu cầu."}],
  "969": [{"jp":"救援**物資**を送った。","vi":"Đã gửi hàng cứu trợ."},{"jp":"戦時中は**物資**が不足した。","vi":"Trong thời chiến, vật tư bị thiếu hụt."}],
  "970": [{"jp":"この道具は**用途**が広い。","vi":"Dụng cụ này có nhiều công dụng."},{"jp":"お金の**用途**をはっきりさせる。","vi":"Làm rõ mục đích sử dụng tiền."}],
  "971": [{"jp":"事件に**関連**する情報を集める。","vi":"Thu thập thông tin liên quan đến vụ án."},{"jp":"二つの問題は**関連**している。","vi":"Hai vấn đề có liên quan với nhau."}],
  "972": [{"jp":"長い会議で体力を**消耗**した。","vi":"Cuộc họp dài làm tôi hao tổn thể lực."},{"jp":"電池の**消耗**が早い。","vi":"Pin hao nhanh."}],
  "973": [{"jp":"この車にはブレーキの**欠陥**がある。","vi":"Chiếc xe này có khuyết tật ở phanh."},{"jp":"**欠陥**商品を返品した。","vi":"Tôi đã trả lại sản phẩm bị lỗi."}],
  "974": [{"jp":"**予備**の電池を持っていく。","vi":"Mang theo pin dự phòng."},{"jp":"鍵の**予備**を作っておこう。","vi":"Hãy làm sẵn một chiếc chìa khóa dự phòng."}],
  "975": [{"jp":"**付属**のケーブルを使ってください。","vi":"Hãy dùng dây cáp đi kèm."},{"jp":"大学**付属**の病院で働いている。","vi":"Tôi làm việc ở bệnh viện trực thuộc trường đại học."}],
  "976": [{"jp":"けがの**手当**をしてもらった。","vi":"Tôi đã được sơ cứu vết thương."},{"jp":"毎月、住宅**手当**が出る。","vi":"Hằng tháng có trợ cấp nhà ở."},{"jp":"資金の**手当**がついた。","vi":"Nguồn vốn đã được chuẩn bị xong."}],
  "977": [{"jp":"使ったら**元**の場所に戻してください。","vi":"Dùng xong hãy để lại chỗ cũ."},{"jp":"風邪が**元**で肺炎になった。","vi":"Bị cảm rồi dẫn đến viêm phổi."},{"jp":"**元**の生活に戻りたい。","vi":"Tôi muốn trở lại cuộc sống như trước."}],
  "978": [{"jp":"彼には優しい**面**もある。","vi":"Anh ấy cũng có mặt hiền lành."},{"jp":"経済**面**での支援が必要だ。","vi":"Cần hỗ trợ về mặt kinh tế."},{"jp":"サイコロには六つの**面**がある。","vi":"Xúc xắc có sáu mặt."}],
  "979": [{"jp":"その**説**には反対です。","vi":"Tôi phản đối thuyết đó."},{"jp":"恐竜の絶滅にはいくつかの**説**がある。","vi":"Có nhiều giả thuyết về sự tuyệt chủng của khủng long."}],
  "980": [{"jp":"二人の点数には大きな**差**がある。","vi":"Điểm số của hai người chênh lệch lớn."},{"jp":"東京と地方の収入の**差**が広がる。","vi":"Khoảng cách thu nhập giữa Tokyo và các địa phương ngày càng rộng."}],
  "981": [{"jp":"あっという**間**に一年が過ぎた。","vi":"Một năm trôi qua trong chớp mắt."},{"jp":"話の途中で少し**間**を置いた。","vi":"Tôi ngừng một chút giữa câu chuyện."}],
  "982": [{"jp":"これは私の**分**です。","vi":"Đây là phần của tôi."},{"jp":"この**分**なら明日は晴れそうだ。","vi":"Với tình hình này thì có vẻ mai trời sẽ nắng."}],
  "983": [{"jp":"この映画の**筋**は単純だ。","vi":"Cốt truyện của bộ phim này đơn giản."},{"jp":"彼の話は**筋**が通っている。","vi":"Câu chuyện của anh ấy hợp lý."}],
  "984": [{"jp":"時間に**余裕**を持って出かける。","vi":"Ra khỏi nhà sớm cho dư dả thời gian."},{"jp":"今は旅行する**余裕**がない。","vi":"Bây giờ tôi không đủ điều kiện đi du lịch."}],
  "985": [{"jp":"交通費は会社が**負担**する。","vi":"Chi phí đi lại do công ty chi trả."},{"jp":"親に**負担**をかけたくない。","vi":"Tôi không muốn làm gánh nặng cho bố mẹ."}],
  "986": [{"jp":"この製品には一年の**保証**が付いている。","vi":"Sản phẩm này được bảo hành một năm."},{"jp":"成功する**保証**はない。","vi":"Không có gì đảm bảo sẽ thành công."},{"jp":"父が借金の**保証**人になった。","vi":"Bố tôi đã đứng ra bảo lãnh khoản vay."}],
  "987": [{"jp":"家賃の支払いを**催促**された。","vi":"Tôi bị hối thúc trả tiền nhà."},{"jp":"返事を**催促**するメールを送った。","vi":"Tôi đã gửi email giục trả lời."}],
  "988": [{"jp":"新しい法律が**成立**した。","vi":"Luật mới đã được thông qua."},{"jp":"二社の契約が**成立**した。","vi":"Hợp đồng giữa hai công ty đã được ký kết."}],
  "989": [{"jp":"彼の話は**矛盾**している。","vi":"Lời nói của anh ta mâu thuẫn."},{"jp":"言葉と行動に**矛盾**がある。","vi":"Lời nói và hành động có sự mâu thuẫn."}],
  "990": [{"jp":"神の**存在**を信じますか。","vi":"Bạn có tin vào sự tồn tại của thần linh không?"},{"jp":"彼はチームで大きな**存在**だ。","vi":"Anh ấy là nhân vật quan trọng trong đội."}],
  "991": [{"jp":"母がセーターを**編んで**くれた。","vi":"Mẹ đã đan áo len cho tôi."},{"jp":"冬はマフラーを**編む**のが趣味です。","vi":"Mùa đông, sở thích của tôi là đan khăn quàng."}],
  "992": [{"jp":"取れたボタンを**縫った**。","vi":"Tôi đã khâu lại chiếc cúc bị tuột."},{"jp":"傷口を五針**縫った**。","vi":"Vết thương được khâu năm mũi."}],
  "993": [{"jp":"彼は地図の一点を**指した**。","vi":"Anh ấy chỉ vào một điểm trên bản đồ."},{"jp":"時計の針が三時を**指して**いる。","vi":"Kim đồng hồ chỉ ba giờ."},{"jp":"この言葉は何を**指す**のですか。","vi":"Từ này ám chỉ điều gì vậy?"}],
  "994": [{"jp":"駅までの道を地図で**示した**。","vi":"Tôi chỉ đường đến ga trên bản đồ."},{"jp":"彼はその案に関心を**示した**。","vi":"Anh ấy đã tỏ ra quan tâm đến đề án đó."},{"jp":"データがその効果を**示して**いる。","vi":"Dữ liệu cho thấy hiệu quả đó."}],
  "995": [{"jp":"カップにお湯を**注いで**ください。","vi":"Hãy rót nước nóng vào cốc."},{"jp":"彼は研究に力を**注いだ**。","vi":"Anh ấy dồn sức vào nghiên cứu."}],
  "996": [{"jp":"歯を磨いたら口を**すすぐ**。","vi":"Đánh răng xong thì súc miệng."},{"jp":"洗剤が残らないよう、よく**すすいで**ください。","vi":"Hãy xả kỹ để không còn sót xà phòng."}],
  "997": [{"jp":"作品に**触らないで**ください。","vi":"Xin đừng chạm vào tác phẩm."},{"jp":"猫の頭を優しく**触った**。","vi":"Tôi nhẹ nhàng xoa đầu con mèo."}],
  "998": [{"jp":"手が冷たいものに**触れた**。","vi":"Tay tôi chạm vào một vật lạnh."},{"jp":"その問題には**触れないで**おこう。","vi":"Đừng đề cập đến vấn đề đó."}],
  "999": [{"jp":"母は赤ちゃんを胸に**抱いた**。","vi":"Người mẹ ôm em bé vào lòng."},{"jp":"彼は大きな夢を**抱いて**いる。","vi":"Anh ấy ấp ủ một giấc mơ lớn."},{"jp":"彼女に好意を**抱いて**いる。","vi":"Tôi có cảm tình với cô ấy."}],
  "1000": [{"jp":"彼は荷物を両手に**抱えて**いた。","vi":"Anh ấy ôm hành lý bằng cả hai tay."},{"jp":"会社は多くの問題を**抱えて**いる。","vi":"Công ty đang có nhiều vấn đề."}],
  "1001": [{"jp":"重い荷物を肩に**担いだ**。","vi":"Tôi vác hành lý nặng trên vai."},{"jp":"祭りでみこしを**担ぐ**。","vi":"Khiêng kiệu trong lễ hội."}],
  "1002": [{"jp":"壁のポスターを**剥がした**。","vi":"Tôi đã gỡ tấm áp phích trên tường."},{"jp":"シールをきれいに**剥がす**のは難しい。","vi":"Bóc nhãn dán cho sạch thật khó."}],
  "1003": [{"jp":"子どもが空の絵を**描いた**。","vi":"Đứa trẻ đã vẽ bầu trời."},{"jp":"この小説は戦争を**描いて**いる。","vi":"Cuốn tiểu thuyết này miêu tả chiến tranh."},{"jp":"将来の夢を心に**描く**。","vi":"Hình dung ước mơ tương lai trong lòng."}],
  "1004": [{"jp":"波が岩に当たって**砕けた**。","vi":"Sóng đập vào đá vỡ tung."},{"jp":"グラスが床に落ちて**砕けた**。","vi":"Cái ly rơi xuống sàn vỡ tan."},{"jp":"彼は**砕けた**話し方をする。","vi":"Anh ấy có cách nói chuyện thân mật, thoải mái."}],
  "1005": [{"jp":"氷を**砕いて**ジュースに入れる。","vi":"Đập vụn đá rồi cho vào nước ép."},{"jp":"その知らせが彼の夢を**砕いた**。","vi":"Tin đó đã đập tan giấc mơ của anh ấy."}],
  "1006": [{"jp":"事故で道が**ふさがって**いる。","vi":"Đường bị tắc do tai nạn."},{"jp":"今、手が**ふさがって**いる。","vi":"Bây giờ tay tôi đang bận."},{"jp":"悲しみで胸が**ふさがる**思いだ。","vi":"Lòng tôi nghẹn lại vì đau buồn."}],
  "1007": [{"jp":"大きな音に耳を**ふさいだ**。","vi":"Tôi bịt tai lại vì tiếng ồn lớn."},{"jp":"車が道を**ふさいで**いる。","vi":"Chiếc xe đang chắn đường."},{"jp":"失恋して気が**ふさいで**いる。","vi":"Vì thất tình nên tôi đang buồn rầu."}],
  "1008": [{"jp":"混雑する時間を**避けて**出かける。","vi":"Đi ra ngoài tránh giờ đông đúc."},{"jp":"彼は最近私を**避けて**いる。","vi":"Gần đây anh ấy đang tránh mặt tôi."}],
  "1009": [{"jp":"飛んできたボールを**よけた**。","vi":"Tôi né quả bóng bay tới."},{"jp":"水たまりを**よけて**歩く。","vi":"Đi tránh vũng nước."},{"jp":"嫌いな野菜を皿の端に**よける**。","vi":"Gạt rau không thích sang mép đĩa."}],
  "1010": [{"jp":"台風の進路が**それた**。","vi":"Đường đi của cơn bão đã chệch hướng."},{"jp":"ボールがゴールから**それた**。","vi":"Quả bóng đã đi chệch khỏi khung thành."},{"jp":"話が本題から**それて**しまった。","vi":"Câu chuyện đã lạc khỏi chủ đề chính."}],
  "1011": [{"jp":"彼は私から目を**そらした**。","vi":"Anh ấy lảng tránh ánh mắt tôi."},{"jp":"話を**そらさないで**ください。","vi":"Xin đừng lảng sang chuyện khác."}],
  "1012": [{"jp":"彼女は私の顔をじっと**見つめた**。","vi":"Cô ấy nhìn chằm chằm vào mặt tôi."},{"jp":"現実を**見つめる**ことが大切だ。","vi":"Điều quan trọng là phải nhìn thẳng vào thực tế."}],
  "1013": [{"jp":"窓から海を**眺めた**。","vi":"Tôi ngắm biển từ cửa sổ."},{"jp":"しばらく様子を**眺めて**いた。","vi":"Tôi đứng quan sát tình hình một lúc."}],
  "1014": [{"jp":"二人は思わず顔を**見合わせた**。","vi":"Hai người bất giác nhìn nhau."},{"jp":"雨のため試合を**見合わせた**。","vi":"Trận đấu bị hoãn vì trời mưa."},{"jp":"事故で電車が運転を**見合わせて**いる。","vi":"Tàu điện đang tạm ngừng chạy do tai nạn."}],
  "1015": [{"jp":"空港で友達を**見送った**。","vi":"Tôi đã tiễn bạn ở sân bay."},{"jp":"今回は参加を**見送る**ことにした。","vi":"Lần này tôi quyết định không tham gia."},{"jp":"バスを一本**見送って**次のに乗った。","vi":"Tôi bỏ qua một chuyến xe buýt rồi đi chuyến sau."}],
  "1016": [{"jp":"毎年多くの観光客が京都を**訪れる**。","vi":"Mỗi năm có rất nhiều khách du lịch đến thăm Kyoto."},{"jp":"久しぶりに母校を**訪れました**。","vi":"Lâu lắm rồi tôi mới đến thăm lại trường cũ."},{"jp":"この町にもようやく春が**訪れた**。","vi":"Cuối cùng mùa xuân cũng đã đến với thị trấn này."}],
  "1017": [{"jp":"忘れ物に気づいて家へ**引き返した**。","vi":"Nhận ra mình quên đồ nên tôi quay trở lại nhà."},{"jp":"天気が悪くなったので、山頂の手前で**引き返しました**。","vi":"Vì thời tiết xấu đi nên chúng tôi đã quay lại ngay trước khi lên đỉnh núi."}],
  "1018": [{"jp":"彼は何も言わずに部屋を**去った**。","vi":"Anh ấy rời khỏi phòng mà không nói một lời."},{"jp":"定年で会社を**去る**ことになりました。","vi":"Tôi sẽ rời công ty vì đến tuổi nghỉ hưu."},{"jp":"台風が**去って**、空が晴れた。","vi":"Cơn bão đi qua, bầu trời đã quang đãng."}],
  "1019": [{"jp":"熱いスープを**すすった**。","vi":"Tôi húp bát súp nóng."},{"jp":"日本ではそばを音を立てて**すすります**。","vi":"Ở Nhật, người ta húp mì soba thành tiếng."},{"jp":"風邪で鼻を**すすって**いる。","vi":"Bị cảm nên cứ sụt sịt mũi."}],
  "1020": [{"jp":"料理をゆっくり**味わって**ください。","vi":"Xin hãy thưởng thức món ăn một cách thong thả."},{"jp":"初めて優勝の喜びを**味わった**。","vi":"Lần đầu tiên tôi được nếm trải niềm vui chiến thắng."},{"jp":"失恋の苦しみを**味わう**。","vi":"Trải qua nỗi đau thất tình."}],
  "1021": [{"jp":"台所からカレーのいい香りが**匂って**くる。","vi":"Mùi cà ri thơm phức bay ra từ trong bếp."},{"jp":"庭の梅の花がほのかに**匂って**いる。","vi":"Hoa mơ trong vườn tỏa hương thoang thoảng."},{"jp":"この部屋、何か**匂わない**？","vi":"Phòng này có mùi gì không nhỉ?"}],
  "1022": [{"jp":"世界には**飢えて**いる子どもがたくさんいる。","vi":"Trên thế giới có rất nhiều trẻ em đang bị đói."},{"jp":"彼は親の愛に**飢えて**いた。","vi":"Cậu ấy khao khát tình thương của cha mẹ."},{"jp":"知識に**飢えた**学生たちが集まった。","vi":"Những sinh viên khát khao tri thức đã tụ họp lại."}],
  "1023": [{"jp":"事故の責任を**問われた**。","vi":"Tôi bị truy cứu trách nhiệm về vụ tai nạn."},{"jp":"この仕事は経験を**問いません**。","vi":"Công việc này không yêu cầu kinh nghiệm."},{"jp":"国民に信を**問う**選挙が行われる。","vi":"Một cuộc bầu cử để hỏi ý kiến tín nhiệm của người dân sẽ được tổ chức."}],
  "1024": [{"jp":"祖父は戦争の体験を**語って**くれた。","vi":"Ông tôi đã kể cho tôi nghe về trải nghiệm chiến tranh."},{"jp":"彼は将来の夢を熱く**語った**。","vi":"Anh ấy say sưa nói về ước mơ tương lai."}],
  "1025": [{"jp":"二人は永遠の愛を**誓った**。","vi":"Hai người đã thề nguyện tình yêu vĩnh cửu."},{"jp":"もう二度と遅刻しないと**誓います**。","vi":"Tôi xin hứa sẽ không bao giờ đi muộn nữa."}],
  "1026": [{"jp":"家族が私を**支えて**くれた。","vi":"Gia đình đã luôn hỗ trợ tôi."},{"jp":"彼は一人で家計を**支えて**いる。","vi":"Anh ấy một mình gánh vác kinh tế gia đình."},{"jp":"この柱が屋根を**支えて**います。","vi":"Cây cột này đỡ lấy mái nhà."}],
  "1027": [{"jp":"研究に十年を**費やした**。","vi":"Tôi đã dành mười năm cho việc nghiên cứu."},{"jp":"無駄なことに時間を**費やす**な。","vi":"Đừng tốn thời gian vào những việc vô ích."}],
  "1028": [{"jp":"この実験には新しい方法を**用いた**。","vi":"Thí nghiệm này đã sử dụng phương pháp mới."},{"jp":"会社は優秀な人材を積極的に**用いて**いる。","vi":"Công ty tích cực tuyển dụng những nhân tài xuất sắc."},{"jp":"敬語を正しく**用いる**のは難しい。","vi":"Sử dụng kính ngữ cho đúng thật khó."}],
  "1029": [{"jp":"年が**改まって**、気持ちも新たになった。","vi":"Sang năm mới, tâm trạng cũng trở nên mới mẻ."},{"jp":"規則が**改まり**、手続きが簡単になった。","vi":"Quy định được sửa đổi nên thủ tục trở nên đơn giản hơn."},{"jp":"そんなに**改まった**言い方をしなくてもいいよ。","vi":"Không cần phải nói năng trịnh trọng như vậy đâu."}],
  "1030": [{"jp":"悪い習慣を**改める**べきだ。","vi":"Nên sửa đổi những thói quen xấu."},{"jp":"料金表を**改めました**。","vi":"Chúng tôi đã thay đổi bảng giá."},{"jp":"日を**改めて**伺います。","vi":"Tôi sẽ đến thăm vào một ngày khác."}],
  "1031": [{"jp":"荷物が全部箱に**収まった**。","vi":"Toàn bộ hành lý đã vừa vặn trong thùng."},{"jp":"やっと騒ぎが**収まった**。","vi":"Cuối cùng vụ ồn ào cũng đã lắng xuống."},{"jp":"彼は新しい会社の社長の座に**納まった**。","vi":"Anh ấy đã yên vị ở ghế giám đốc công ty mới."}],
  "1032": [{"jp":"チームは大きな成功を**収めた**。","vi":"Đội đã đạt được thành công lớn."},{"jp":"社長がうまく争いを**収めた**。","vi":"Giám đốc đã khéo léo dàn xếp cuộc tranh chấp."},{"jp":"写真をアルバムに**収めた**。","vi":"Tôi đã cất ảnh vào album."}],
  "1033": [{"jp":"川に**沿って**桜並木が続いている。","vi":"Hàng cây anh đào trải dài dọc theo con sông."},{"jp":"ご期待に**沿える**よう努力します。","vi":"Tôi sẽ cố gắng để đáp ứng được kỳ vọng của quý vị."},{"jp":"マニュアルに**沿って**作業を進める。","vi":"Tiến hành công việc theo đúng sách hướng dẫn."}],
  "1034": [{"jp":"プレゼントにカードを**添えた**。","vi":"Tôi gửi kèm một tấm thiệp với món quà."},{"jp":"料理にパセリを**添える**。","vi":"Thêm rau mùi tây vào món ăn để trang trí."}],
  "1035": [{"jp":"そのご要望にはお応えし**かねます**。","vi":"Chúng tôi không thể đáp ứng yêu cầu đó."},{"jp":"私にはわかり**かねます**。","vi":"Tôi e là không thể biết được."},{"jp":"この部屋は書斎と客間を**兼ねて**いる。","vi":"Căn phòng này vừa là phòng làm việc vừa là phòng khách."}],
  "1036": [{"jp":"この土地は米作りに**適して**いる。","vi":"Vùng đất này thích hợp để trồng lúa."},{"jp":"彼はリーダーに**適した**人物だ。","vi":"Anh ấy là người phù hợp để làm trưởng nhóm."}],
  "1037": [{"jp":"1ドルは約150円に**相当する**。","vi":"1 đô la tương đương khoảng 150 yên."},{"jp":"日本の国会に**相当する**機関はどこですか。","vi":"Cơ quan tương ứng với Quốc hội Nhật Bản là cơ quan nào?"}],
  "1038": [{"jp":"この手術には危険が**伴う**。","vi":"Ca phẫu thuật này kéo theo nhiều rủi ro."},{"jp":"社長は秘書を**伴って**出張した。","vi":"Giám đốc dẫn theo thư ký đi công tác."},{"jp":"経済の発展に**伴って**、環境問題が生じた。","vi":"Cùng với sự phát triển kinh tế, vấn đề môi trường đã phát sinh."}],
  "1039": [{"jp":"ホールにピアノの音が**響いた**。","vi":"Tiếng đàn piano vang vọng khắp hội trường."},{"jp":"先生の言葉が心に**響いた**。","vi":"Lời của thầy đã lay động trái tim tôi."},{"jp":"上の階の足音が**響いて**眠れない。","vi":"Tiếng bước chân ở tầng trên dội xuống làm tôi không ngủ được."}],
  "1040": [{"jp":"大阪は東京に**次ぐ**大都市だ。","vi":"Osaka là thành phố lớn chỉ đứng sau Tokyo."},{"jp":"地震に**次いで**津波が発生した。","vi":"Tiếp theo sau trận động đất là sóng thần."}],
  "1041": [{"jp":"「国際連合」を**略して**「国連」と言う。","vi":"\"Kokusai Rengō\" được viết tắt là \"Kokuren\" (Liên Hợp Quốc)."},{"jp":"敬称は**略させて**いただきます。","vi":"Xin phép được lược bỏ kính xưng."},{"jp":"詳しい説明は**略します**。","vi":"Tôi xin lược bớt phần giải thích chi tiết."}],
  "1042": [{"jp":"締め切りが**迫って**いる。","vi":"Hạn chót đang đến gần."},{"jp":"台風が九州に**迫って**きた。","vi":"Cơn bão đang tiến sát Kyushu."},{"jp":"上司に決断を**迫られた**。","vi":"Tôi bị cấp trên thúc ép phải đưa ra quyết định."}],
  "1043": [{"jp":"今年は優勝を**狙って**います。","vi":"Năm nay chúng tôi nhắm đến chức vô địch."},{"jp":"猫が鳥を**狙って**いる。","vi":"Con mèo đang rình con chim."},{"jp":"観光客を**狙った**スリが多い。","vi":"Có nhiều kẻ móc túi nhắm vào khách du lịch."}],
  "1044": [{"jp":"彼は罪を**犯して**逮捕された。","vi":"Anh ta phạm tội và đã bị bắt."},{"jp":"人は誰でも過ちを**犯す**ものだ。","vi":"Ai cũng có lúc phạm sai lầm."}],
  "1045": [{"jp":"隣国が国境を**侵した**。","vi":"Nước láng giềng đã xâm phạm biên giới."},{"jp":"他人のプライバシーを**侵して**はいけない。","vi":"Không được xâm phạm quyền riêng tư của người khác."}],
  "1046": [{"jp":"彼は危険を**冒して**子どもを助けた。","vi":"Anh ấy đã bất chấp nguy hiểm để cứu đứa trẻ."},{"jp":"大雨を**冒して**出発した。","vi":"Chúng tôi đã đương đầu với mưa lớn mà lên đường."}],
  "1047": [{"jp":"男はナイフで店員を**脅した**。","vi":"Gã đàn ông đã dùng dao đe dọa nhân viên cửa hàng."},{"jp":"彼はお金を出せと**脅されて**いた。","vi":"Cậu ấy bị đe dọa bắt đưa tiền."}],
  "1048": [{"jp":"後ろから急に声をかけて友達を**脅かした**。","vi":"Tôi bất ngờ gọi từ phía sau để hù bạn."},{"jp":"そんなに**脅かさない**でよ。","vi":"Đừng dọa tớ như thế chứ."}],
  "1049": [{"jp":"親に**逆らって**家を出た。","vi":"Tôi đã chống lại cha mẹ và bỏ nhà đi."},{"jp":"風に**逆らって**自転車をこいだ。","vi":"Tôi đạp xe ngược chiều gió."},{"jp":"時代の流れには**逆らえない**。","vi":"Không thể đi ngược lại dòng chảy của thời đại."}],
  "1050": [{"jp":"騒音が睡眠を**妨げる**。","vi":"Tiếng ồn cản trở giấc ngủ."},{"jp":"車が道をふさいで通行を**妨げて**いる。","vi":"Chiếc xe chắn đường, gây cản trở giao thông."}],
  "1051": [{"jp":"政府はそのうわさを**打ち消した**。","vi":"Chính phủ đã bác bỏ tin đồn đó."},{"jp":"彼は不安を**打ち消す**ように笑った。","vi":"Anh ấy cười như để xua đi nỗi bất an."}],
  "1052": [{"jp":"インタビューに**応じて**いただけますか。","vi":"Anh có thể nhận lời phỏng vấn không ạ?"},{"jp":"能力に**応じて**給料が決まる。","vi":"Lương được quyết định tùy theo năng lực."},{"jp":"客の要望に**応じる**。","vi":"Đáp ứng yêu cầu của khách hàng."}],
  "1053": [{"jp":"ご注文を**承りました**。","vi":"Chúng tôi đã nhận đơn đặt hàng của quý khách."},{"jp":"ご意見を**承りたい**と思います。","vi":"Tôi muốn được lắng nghe ý kiến của quý vị."}],
  "1054": [{"jp":"お手紙を**頂戴しました**。","vi":"Tôi đã nhận được thư của anh."},{"jp":"少々お時間を**頂戴できます**か。","vi":"Tôi có thể xin anh một chút thời gian được không?"},{"jp":"それ、ちょっと見せて**ちょうだい**。","vi":"Cái đó cho mẹ xem một chút nào."}],
  "1055": [{"jp":"大学で経済を**学んで**います。","vi":"Tôi đang học kinh tế ở trường đại học."},{"jp":"失敗から多くのことを**学んだ**。","vi":"Tôi đã học được nhiều điều từ thất bại."}],
  "1056": [{"jp":"小麦粉を水でよく**練る**。","vi":"Nhào kỹ bột mì với nước."},{"jp":"旅行の計画を**練って**いる。","vi":"Tôi đang lên kế hoạch kỹ lưỡng cho chuyến du lịch."},{"jp":"何度も文章を**練り**直した。","vi":"Tôi đã trau chuốt lại câu văn nhiều lần."}],
  "1057": [{"jp":"母は赤ちゃんを背中に**負って**いた。","vi":"Người mẹ cõng đứa bé trên lưng."},{"jp":"この事故の責任は会社が**負う**。","vi":"Công ty sẽ chịu trách nhiệm về vụ tai nạn này."},{"jp":"転んで足にけがを**負った**。","vi":"Tôi bị ngã và bị thương ở chân."}],
  "1058": [{"jp":"親としての責任を**果たす**。","vi":"Hoàn thành trách nhiệm của bậc cha mẹ."},{"jp":"ついに長年の夢を**果たした**。","vi":"Cuối cùng tôi đã thực hiện được ước mơ bao năm."}],
  "1059": [{"jp":"その仕事は私が**引き受けます**。","vi":"Công việc đó tôi sẽ đảm nhận."},{"jp":"安易に頼みを**引き受け**てはいけない。","vi":"Không nên dễ dàng nhận lời nhờ vả."}],
  "1060": [{"jp":"雨で川の水かさが**増した**。","vi":"Do mưa nên mực nước sông đã dâng lên."},{"jp":"春になって日差しが強さを**増して**きた。","vi":"Sang xuân, ánh nắng càng lúc càng gay gắt hơn."}],
  "1061": [{"jp":"茶わんの縁が**欠けて**いる。","vi":"Mép bát bị sứt mẻ."},{"jp":"彼には常識が**欠けて**いる。","vi":"Anh ta thiếu hiểu biết thông thường."},{"jp":"メンバーが一人**欠けて**試合に出られない。","vi":"Thiếu một thành viên nên không thể ra sân thi đấu."}],
  "1062": [{"jp":"毎朝のジョギングを**欠かした**ことがない。","vi":"Tôi chưa bao giờ bỏ buổi chạy bộ mỗi sáng."},{"jp":"水は生活に**欠かせない**。","vi":"Nước là thứ không thể thiếu trong cuộc sống."}],
  "1063": [{"jp":"山の空気は**澄んで**いる。","vi":"Không khí trên núi trong lành."},{"jp":"**澄んだ**目で私を見つめた。","vi":"Cô bé nhìn tôi bằng đôi mắt trong veo."},{"jp":"この川の水はとても**澄んで**いる。","vi":"Nước con sông này rất trong."}],
  "1064": [{"jp":"大雨で川の水が**濁った**。","vi":"Do mưa lớn nên nước sông bị đục."},{"jp":"この池は**濁って**いて底が見えない。","vi":"Cái ao này đục ngầu, không nhìn thấy đáy."}],
  "1065": [{"jp":"彼は返事を**濁した**。","vi":"Anh ấy trả lời ậm ừ, không rõ ràng."},{"jp":"言葉を**濁して**ごまかした。","vi":"Anh ta nói lấp lửng để lảng tránh."},{"jp":"泥で水を**濁さない**ようにしてください。","vi":"Xin đừng làm đục nước bằng bùn."}],
  "1066": [{"jp":"計画に問題が**生じた**。","vi":"Kế hoạch đã nảy sinh vấn đề."},{"jp":"二人の間に誤解が**生じて**しまった。","vi":"Giữa hai người đã nảy sinh hiểu lầm."}],
  "1067": [{"jp":"会議は5時間に**及んだ**。","vi":"Cuộc họp kéo dài đến tận 5 tiếng."},{"jp":"被害は町全体に**及んで**いる。","vi":"Thiệt hại đã lan ra toàn thị trấn."},{"jp":"料理の腕では、私は母に**及ばない**。","vi":"Về tài nấu nướng, tôi không bằng mẹ."}],
  "1068": [{"jp":"たばこは健康に悪い影響を**及ぼす**。","vi":"Thuốc lá gây ảnh hưởng xấu đến sức khỏe."},{"jp":"台風が農作物に大きな被害を**及ぼした**。","vi":"Cơn bão đã gây thiệt hại lớn cho mùa màng."}],
  "1069": [{"jp":"この道は駅に**至る**。","vi":"Con đường này dẫn đến nhà ga."},{"jp":"話し合いの結果、合意に**至った**。","vi":"Sau khi thảo luận, hai bên đã đi đến thống nhất."},{"jp":"事故の原因は現在に**至る**まで分かっていない。","vi":"Cho đến tận bây giờ nguyên nhân vụ tai nạn vẫn chưa rõ."}],
  "1070": [{"jp":"登山隊はついに山頂に**達した**。","vi":"Đoàn leo núi cuối cùng đã lên tới đỉnh."},{"jp":"売り上げが目標に**達しました**。","vi":"Doanh số đã đạt mục tiêu."}],
  "1071": [{"jp":"今年はりんごがたくさん**実った**。","vi":"Năm nay táo ra rất nhiều quả."},{"jp":"長年の努力がようやく**実った**。","vi":"Nỗ lực bao năm cuối cùng đã đơm hoa kết trái."},{"jp":"二人の恋は**実らなかった**。","vi":"Mối tình của hai người đã không thành."}],
  "1072": [{"jp":"冬は日が**暮れる**のが早い。","vi":"Mùa đông trời tối nhanh."},{"jp":"もうすぐ今年も**暮れる**。","vi":"Năm nay cũng sắp hết rồi."},{"jp":"彼女は悲しみに**暮れて**いた。","vi":"Cô ấy chìm đắm trong nỗi buồn."}],
  "1073": [{"jp":"この製品は品質で他社に**劣らない**。","vi":"Sản phẩm này không thua kém công ty khác về chất lượng."},{"jp":"体力では若い人に**劣る**。","vi":"Về thể lực thì tôi kém hơn người trẻ."}],
  "1074": [{"jp":"国によって習慣が**異なる**。","vi":"Phong tục khác nhau tùy theo quốc gia."},{"jp":"二人の意見は大きく**異なって**いる。","vi":"Ý kiến của hai người rất khác nhau."}],
  "1075": [{"jp":"強風で髪が**乱れた**。","vi":"Gió mạnh làm tóc rối bù."},{"jp":"大雪でダイヤが**乱れて**いる。","vi":"Do tuyết lớn nên lịch tàu bị xáo trộn."},{"jp":"生活が**乱れる**と体調を崩しやすい。","vi":"Sinh hoạt thất thường thì dễ đổ bệnh."}],
  "1076": [{"jp":"彼の行動がクラスの秩序を**乱した**。","vi":"Hành động của cậu ta đã làm rối loạn trật tự lớp học."},{"jp":"急な仕事で予定を**乱された**。","vi":"Công việc đột xuất làm đảo lộn kế hoạch của tôi."},{"jp":"列を**乱さない**でください。","vi":"Xin đừng làm lộn xộn hàng."}],
  "1077": [{"jp":"ねじが**緩んで**いる。","vi":"Con ốc bị lỏng."},{"jp":"試験が終わって気が**緩んだ**。","vi":"Thi xong nên tôi thấy lơi lỏng tinh thần."},{"jp":"寒さが少し**緩んで**きた。","vi":"Cái lạnh đã dịu bớt một chút."}],
  "1078": [{"jp":"ベルトを**緩めて**ください。","vi":"Hãy nới lỏng thắt lưng ra."},{"jp":"カーブの手前でスピードを**緩めた**。","vi":"Tôi giảm tốc độ trước khúc cua."},{"jp":"最後まで気を**緩めない**ように。","vi":"Đừng lơ là cho đến phút cuối."}],
  "1079": [{"jp":"古い自転車が**さびて**しまった。","vi":"Chiếc xe đạp cũ đã bị gỉ sét."},{"jp":"雨にぬれた釘はすぐ**さびる**。","vi":"Đinh bị dính mưa sẽ nhanh gỉ."}],
  "1080": [{"jp":"日本は海に**接した**国だ。","vi":"Nhật Bản là quốc gia giáp biển."},{"jp":"仕事で多くの外国人と**接する**機会がある。","vi":"Trong công việc tôi có cơ hội tiếp xúc với nhiều người nước ngoài."},{"jp":"お客様には丁寧に**接して**ください。","vi":"Hãy đối xử lịch sự với khách hàng."}],
  "1081": [{"jp":"彼はテニス部に**属して**いる。","vi":"Cậu ấy thuộc câu lạc bộ quần vợt."},{"jp":"クジラはほ乳類に**属する**。","vi":"Cá voi thuộc lớp động vật có vú."}],
  "1082": [{"jp":"女性が社員の半分を**占めて**いる。","vi":"Phụ nữ chiếm một nửa số nhân viên."},{"jp":"彼は会社で重要な地位を**占めて**いる。","vi":"Anh ấy giữ vị trí quan trọng trong công ty."}],
  "1083": [{"jp":"一日中歩いて**くたびれた**。","vi":"Đi bộ cả ngày nên mệt rã rời."},{"jp":"**くたびれた**スーツを着ている。","vi":"Anh ấy mặc bộ vest đã sờn cũ."},{"jp":"彼の長話には**くたびれる**。","vi":"Nghe anh ta nói dài dòng thật phát ngán."}],
  "1084": [{"jp":"私は友達に**恵まれて**いる。","vi":"Tôi may mắn có nhiều bạn tốt."},{"jp":"当日は天気に**恵まれた**。","vi":"Hôm đó thời tiết rất thuận lợi."},{"jp":"この国は資源に**恵まれて**いる。","vi":"Đất nước này giàu tài nguyên."}],
  "1085": [{"jp":"やる気が**湧いて**きた。","vi":"Động lực đã trào dâng."},{"jp":"この辺りは温泉が**湧く**。","vi":"Vùng này có suối nước nóng phun lên."},{"jp":"彼の話を聞いて疑問が**湧いた**。","vi":"Nghe chuyện của anh ấy, tôi nảy sinh nghi vấn."}],
  "1086": [{"jp":"赤ちゃんが母親を見て**ほほえんだ**。","vi":"Em bé nhìn mẹ và mỉm cười."},{"jp":"彼女はいつも**ほほえんで**いる。","vi":"Cô ấy lúc nào cũng mỉm cười."}],
  "1087": [{"jp":"授業中に**ふざけて**先生に叱られた。","vi":"Đùa nghịch trong giờ học nên bị thầy mắng."},{"jp":"**ふざける**のもいい加減にしなさい。","vi":"Đùa giỡn vừa phải thôi."},{"jp":"**ふざけた**ことを言うな。","vi":"Đừng có nói nhảm nhí."}],
  "1088": [{"jp":"今さら**悔やんで**も仕方がない。","vi":"Bây giờ có hối hận cũng chẳng ích gì."},{"jp":"彼は自分の失敗を深く**悔やんだ**。","vi":"Anh ấy vô cùng ân hận về thất bại của mình."},{"jp":"あの時の発言を今でも**悔やんで**いる。","vi":"Đến giờ tôi vẫn còn hối tiếc về câu nói lúc đó."}],
  "1089": [{"jp":"彼女は返事を**ためらった**。","vi":"Cô ấy chần chừ không trả lời."},{"jp":"**ためらわず**に質問してください。","vi":"Đừng ngần ngại, cứ đặt câu hỏi."}],
  "1090": [{"jp":"お年寄りを**敬う**ことは大切だ。","vi":"Tôn trọng người cao tuổi là điều quan trọng."},{"jp":"彼は師を心から**敬って**いる。","vi":"Anh ấy kính trọng thầy mình từ tận đáy lòng."}],
  "1091": [{"jp":"シャワーを浴びて**さっぱり**した。","vi":"Tắm xong thấy sảng khoái hẳn."},{"jp":"この問題は**さっぱり**わからない。","vi":"Bài này tôi hoàn toàn không hiểu."},{"jp":"**さっぱり**した味の料理が好きだ。","vi":"Tôi thích những món ăn có vị thanh nhẹ."}],
  "1092": [{"jp":"部屋を片付けて**すっきり**した。","vi":"Dọn phòng xong thấy gọn gàng thoáng đãng."},{"jp":"言いたいことを言って気分が**すっきり**した。","vi":"Nói được điều muốn nói nên thấy nhẹ nhõm."},{"jp":"このデザインは**すっきり**していて見やすい。","vi":"Thiết kế này gọn gàng, dễ nhìn."}],
  "1093": [{"jp":"今日は**実に**楽しい一日だった。","vi":"Hôm nay thực sự là một ngày vui."},{"jp":"彼の作品は**実に**すばらしい。","vi":"Tác phẩm của anh ấy thật tuyệt vời."}],
  "1094": [{"jp":"週末は**思い切り**遊びたい。","vi":"Cuối tuần tôi muốn chơi thả ga."},{"jp":"ボールを**思い切り**蹴った。","vi":"Tôi sút quả bóng hết sức."},{"jp":"彼は**思い切り**がいい人だ。","vi":"Anh ấy là người rất dứt khoát."}],
  "1095": [{"jp":"**何となく**彼が嘘をついている気がする。","vi":"Không hiểu sao tôi cảm thấy anh ta đang nói dối."},{"jp":"**何となく**散歩に出かけた。","vi":"Chẳng vì lý do gì, tôi ra ngoài đi dạo."}],
  "1096": [{"jp":"**何だか**寒気がする。","vi":"Thấy hơi ớn lạnh."},{"jp":"**何だか**悲しくなってきた。","vi":"Tự nhiên thấy hơi buồn."}],
  "1097": [{"jp":"**どうにか**締め切りに間に合った。","vi":"Bằng cách nào đó tôi cũng kịp hạn chót."},{"jp":"この問題を**どうにか**してください。","vi":"Xin hãy làm gì đó để giải quyết vấn đề này."}],
  "1098": [{"jp":"この痛みは**どうにも**我慢できない。","vi":"Cơn đau này tôi chẳng thể nào chịu được."},{"jp":"今さら**どうにも**ならない。","vi":"Bây giờ thì chẳng thể làm gì được nữa."}],
  "1099": [{"jp":"**何とか**試験に合格した。","vi":"Bằng cách nào đó tôi cũng đã thi đỗ."},{"jp":"**何とか**してこの問題を解決したい。","vi":"Tôi muốn làm sao đó giải quyết được vấn đề này."},{"jp":"田中さんとか**何とか**いう人から電話があった。","vi":"Có điện thoại từ một người tên là Tanaka hay gì đó."}],
  "1100": [{"jp":"結果は**何とも**言えません。","vi":"Kết quả thì tôi không thể nói trước được gì."},{"jp":"彼は失敗しても**何とも**思っていない。","vi":"Anh ta thất bại mà chẳng thấy bận tâm chút nào."}],
  "1101": [{"jp":"彼は**わざと**負けた。","vi":"Anh ấy cố tình thua."},{"jp":"**わざと**やったわけではありません。","vi":"Tôi không cố ý làm vậy."}],
  "1102": [{"jp":"**わざわざ**行ったのに、店は休みだった。","vi":"Mất công đi đến nơi mà cửa hàng lại nghỉ."},{"jp":"**わざわざ**来てくださってありがとうございます。","vi":"Cảm ơn anh đã mất công đến tận đây."}],
  "1103": [{"jp":"**せっかく**作ったので、食べてください。","vi":"Tôi đã mất công nấu rồi, anh ăn đi nhé."},{"jp":"**せっかく**の休みだから、旅行に行こう。","vi":"Kỳ nghỉ hiếm hoi mà, đi du lịch thôi."}],
  "1104": [{"jp":"**あいにく**父は留守にしております。","vi":"Rất tiếc là bố tôi đang đi vắng."},{"jp":"**あいにく**の雨で試合が中止になった。","vi":"Thật không may trời mưa nên trận đấu bị hủy."}],
  "1105": [{"jp":"**案の定**、彼は遅刻してきた。","vi":"Đúng như dự đoán, anh ta đến muộn."},{"jp":"心配していたら、**案の定**雨が降り出した。","vi":"Đang lo thì quả nhiên trời đổ mưa."}],
  "1106": [{"jp":"**いよいよ**明日は試験だ。","vi":"Cuối cùng ngày mai cũng đến kỳ thi."},{"jp":"**いよいよ**私の番が来た。","vi":"Đã đến lượt tôi rồi."},{"jp":"雨は**いよいよ**激しくなった。","vi":"Mưa càng lúc càng nặng hạt."}],
  "1107": [{"jp":"**さすが**プロだ、上手だね。","vi":"Quả không hổ danh là dân chuyên nghiệp, giỏi thật."},{"jp":"**さすが**に疲れた。","vi":"Đến mức này thì quả thật là mệt."},{"jp":"一位とは**さすが**ですね。","vi":"Đứng nhất à, đúng là anh có khác."}],
  "1108": [{"jp":"**とにかく**やってみよう。","vi":"Dù sao thì cứ thử làm xem."},{"jp":"**とにかく**今日は早く寝なさい。","vi":"Dù thế nào thì hôm nay cũng đi ngủ sớm đi."}],
  "1109": [{"jp":"値段は**ともかく**、味はいい。","vi":"Giá cả thì chưa bàn, chứ vị thì ngon."},{"jp":"**ともかく**現場へ行ってみよう。","vi":"Dù sao thì cứ đến hiện trường xem đã."}],
  "1110": [{"jp":"**せめて**一日だけでも休みたい。","vi":"Ít nhất tôi cũng muốn được nghỉ một ngày."},{"jp":"**せめて**電話くらいしてほしかった。","vi":"Ít ra thì cũng nên gọi điện cho tôi chứ."}],
  "1111": [{"jp":"参加者は**せいぜい**20人だろう。","vi":"Người tham gia cùng lắm chỉ khoảng 20 người."},{"jp":"私にできるのは**せいぜい**これくらいだ。","vi":"Những gì tôi làm được cùng lắm chỉ đến thế này."}],
  "1112": [{"jp":"**どうせ**間に合わないから、ゆっくり行こう。","vi":"Đằng nào cũng không kịp, cứ đi thong thả thôi."},{"jp":"**どうせ**やるなら、楽しくやろう。","vi":"Đằng nào cũng làm thì làm cho vui."}],
  "1113": [{"jp":"箱に本が**ぎっしり**詰まっている。","vi":"Sách được nhét chật cứng trong hộp."},{"jp":"来週は予定が**ぎっしり**だ。","vi":"Tuần sau lịch kín mít."}],
  "1114": [{"jp":"店の前に人が**ずらりと**並んでいる。","vi":"Người xếp thành hàng dài trước cửa hàng."},{"jp":"棚に新しい商品が**ずらりと**並んだ。","vi":"Hàng mới được bày thành dãy trên kệ."}],
  "1115": [{"jp":"**あっさり**した料理が食べたい。","vi":"Tôi muốn ăn món gì thanh đạm."},{"jp":"優勝候補が**あっさり**負けた。","vi":"Ứng cử viên vô địch đã thua một cách dễ dàng."},{"jp":"彼は**あっさり**と謝った。","vi":"Anh ấy xin lỗi một cách nhanh gọn."}],
  "1116": [{"jp":"会場は**しんと**静まり返った。","vi":"Hội trường chìm vào im lặng."},{"jp":"夜の図書館は**しいんと**していた。","vi":"Thư viện ban đêm yên ắng lặng lẽ."}],
  "1117": [{"jp":"**ちゃんと**宿題をしなさい。","vi":"Làm bài tập về nhà cho đàng hoàng vào."},{"jp":"約束は**ちゃんと**守ります。","vi":"Tôi sẽ giữ lời hứa đàng hoàng."},{"jp":"書類は**ちゃんと**確認しましたか。","vi":"Anh đã kiểm tra hồ sơ cẩn thận chưa?"}],
  "1118": [{"jp":"会場に客が**続々**と集まってきた。","vi":"Khách lần lượt kéo đến hội trường."},{"jp":"新製品が**続々**と発売されている。","vi":"Các sản phẩm mới liên tục được tung ra."}],
  "1119": [{"jp":"ドアが開くと客が**どっと**入ってきた。","vi":"Cửa vừa mở, khách ùa vào cùng lúc."},{"jp":"家に着いたら疲れが**どっと**出た。","vi":"Về đến nhà, mệt mỏi bỗng ập đến."},{"jp":"彼の冗談に皆が**どっと**笑った。","vi":"Mọi người cùng phá lên cười trước câu đùa của anh ấy."}],
  "1120": [{"jp":"駅で昔の友人に**ばったり**会った。","vi":"Tôi tình cờ gặp lại bạn cũ ở nhà ga."},{"jp":"彼は道で**ばったり**倒れた。","vi":"Anh ấy đột nhiên ngã gục trên đường."}],
  "1121": [{"jp":"**さっさと**仕事を片付けよう。","vi":"Mau chóng giải quyết công việc thôi."},{"jp":"彼は**さっさと**帰ってしまった。","vi":"Anh ta vội vã về mất rồi."}],
  "1122": [{"jp":"野菜を**さっと**ゆでる。","vi":"Luộc sơ rau thật nhanh."},{"jp":"彼女は**さっと**手を挙げた。","vi":"Cô ấy giơ tay lên thoắt một cái."}],
  "1123": [{"jp":"猫が**すっと**部屋から出ていった。","vi":"Con mèo lẻn ra khỏi phòng nhanh như chớp."},{"jp":"薬を飲んだら痛みが**すっと**消えた。","vi":"Uống thuốc xong cơn đau biến mất ngay."}],
  "1124": [{"jp":"母は朝から**せっせと**働いている。","vi":"Mẹ chăm chỉ làm việc từ sáng."},{"jp":"アリが**せっせと**食べ物を運んでいる。","vi":"Lũ kiến cần mẫn tha thức ăn."}],
  "1125": [{"jp":"資料に**ざっと**目を通した。","vi":"Tôi đã xem lướt qua tài liệu."},{"jp":"参加者は**ざっと**100人いた。","vi":"Người tham gia có khoảng chừng 100 người."}],
  "1126": [{"jp":"授業中に**こっそり**メールを見た。","vi":"Tôi lén xem tin nhắn trong giờ học."},{"jp":"彼は**こっそり**部屋を抜け出した。","vi":"Anh ta lén lút rời khỏi phòng."}],
  "1127": [{"jp":"子どもたちが**生き生き**と遊んでいる。","vi":"Bọn trẻ đang chơi đùa hăng say."},{"jp":"新しい職場で彼女は**生き生き**している。","vi":"Ở chỗ làm mới, cô ấy trông đầy sức sống."},{"jp":"この小説は人物が**生き生き**と描かれている。","vi":"Nhân vật trong cuốn tiểu thuyết này được miêu tả rất sinh động."}],
  "1128": [{"jp":"窓の外を**ぼんやり**眺めていた。","vi":"Tôi thẫn thờ nhìn ra ngoài cửa sổ."},{"jp":"寝不足で頭が**ぼんやり**する。","vi":"Thiếu ngủ nên đầu óc lơ mơ."},{"jp":"霧の中に山が**ぼんやり**見える。","vi":"Ngọn núi hiện ra mờ mờ trong sương."}],
  "1129": [{"jp":"**ふと**昔のことを思い出した。","vi":"Tôi chợt nhớ lại chuyện ngày xưa."},{"jp":"**ふと**空を見上げると虹が出ていた。","vi":"Tình cờ ngước nhìn lên trời thì thấy cầu vồng."}],
  "1130": [{"jp":"社長に**じかに**話を聞いた。","vi":"Tôi đã nghe trực tiếp từ giám đốc."},{"jp":"薬を**じかに**肌に塗らないでください。","vi":"Đừng bôi thuốc trực tiếp lên da."}],
  "1131": [{"jp":"**一度に**たくさん食べると体に悪い。","vi":"Ăn nhiều một lúc không tốt cho cơ thể."},{"jp":"**一度に**二つのことはできない。","vi":"Không thể làm hai việc cùng một lúc."}],
  "1132": [{"jp":"合図で全員が**一斉に**走り出した。","vi":"Nghe hiệu lệnh, tất cả đồng loạt chạy."},{"jp":"全国で**一斉に**試験が行われた。","vi":"Kỳ thi được tổ chức đồng loạt trên toàn quốc."}],
  "1133": [{"jp":"家族と**共に**暮らしている。","vi":"Tôi sống cùng gia đình."},{"jp":"年齢と**共に**体力が落ちる。","vi":"Thể lực giảm đi cùng với tuổi tác."}],
  "1134": [{"jp":"二つの国は**相互に**協力している。","vi":"Hai nước hợp tác lẫn nhau."},{"jp":"参加者が**相互に**意見を交換した。","vi":"Những người tham gia đã trao đổi ý kiến với nhau."}],
  "1135": [{"jp":"先生は生徒**一人一人**に声をかけた。","vi":"Thầy giáo hỏi han từng học sinh một."},{"jp":"**一人一人**の意見を大切にしたい。","vi":"Tôi muốn trân trọng ý kiến của từng người."}],
  "1136": [{"jp":"**いちいち**文句を言わないで。","vi":"Đừng có cái gì cũng phàn nàn."},{"jp":"**いちいち**説明している時間はない。","vi":"Không có thời gian giải thích chi li từng thứ."}],
  "1137": [{"jp":"壁の**所々**にひびが入っている。","vi":"Bức tường bị nứt ở một vài chỗ."},{"jp":"この本は**所々**意味が分からない。","vi":"Cuốn sách này có đôi chỗ tôi không hiểu nghĩa."}],
  "1138": [{"jp":"**どうか**よろしくお願いします。","vi":"Kính mong được giúp đỡ."},{"jp":"**どうか**許してください。","vi":"Xin hãy tha thứ cho tôi."}],
  "1139": [{"jp":"**できれば**明日までに返事をください。","vi":"Nếu có thể, xin hãy trả lời trước ngày mai."},{"jp":"**できたら**一緒に来てほしい。","vi":"Nếu được thì tôi mong bạn đi cùng."}],
  "1140": [{"jp":"この映画は**たいして**面白くなかった。","vi":"Bộ phim này không hay lắm."},{"jp":"今日は**たいして**寒くない。","vi":"Hôm nay không lạnh lắm."}],
  "1141": [{"jp":"**恐らく**明日は雨だろう。","vi":"Có lẽ ngày mai trời sẽ mưa."},{"jp":"彼は**恐らく**来ないと思う。","vi":"Tôi e rằng anh ấy sẽ không đến."}],
  "1142": [{"jp":"夏より**むしろ**冬が好きだ。","vi":"So với mùa hè, tôi thích mùa đông hơn."},{"jp":"失敗は**むしろ**良い経験になった。","vi":"Thất bại trái lại đã trở thành một kinh nghiệm tốt."}],
  "1143": [{"jp":"**果たして**、結果は予想通りだった。","vi":"Quả nhiên, kết quả đúng như dự đoán."},{"jp":"**果たして**彼は本当に来るだろうか。","vi":"Liệu anh ấy có thật sự đến không nhỉ?"}],
  "1144": [{"jp":"薬を飲んだら**かえって**悪くなった。","vi":"Uống thuốc xong lại càng tệ hơn."},{"jp":"タクシーより電車のほうが**かえって**早い。","vi":"Đi tàu ngược lại còn nhanh hơn taxi."}],
  "1145": [{"jp":"高い物が**必ずしも**良いとは限らない。","vi":"Đồ đắt chưa hẳn đã tốt."},{"jp":"彼の意見が**必ずしも**正しいわけではない。","vi":"Ý kiến của anh ấy không hẳn là đúng."}],
  "1146": [{"jp":"それは**単に**私の意見です。","vi":"Đó đơn giản chỉ là ý kiến của tôi."},{"jp":"**単に**お金の問題ではない。","vi":"Đó không đơn thuần chỉ là vấn đề tiền bạc."}],
  "1147": [{"jp":"あの事件は**いまだに**解決していない。","vi":"Vụ án đó đến nay vẫn chưa được giải quyết."},{"jp":"**いまだに**彼の名前が思い出せない。","vi":"Đến giờ tôi vẫn không nhớ ra tên anh ấy."}],
  "1148": [{"jp":"散歩の**ついでに**パンを買ってきた。","vi":"Nhân tiện đi dạo, tôi mua bánh mì về."},{"jp":"**ついでに**これもお願いできますか。","vi":"Nhân tiện, anh làm giúp tôi cái này luôn được không?"}],
  "1149": [{"jp":"**とりあえず**ビールをください。","vi":"Trước mắt cho tôi bia đã."},{"jp":"**とりあえず**今日はここまでにしよう。","vi":"Tạm thời hôm nay dừng ở đây thôi."}],
  "1150": [{"jp":"**万一**の場合はここに連絡してください。","vi":"Trong trường hợp khẩn cấp, hãy liên lạc đến đây."},{"jp":"**万が一**失敗しても、後悔はしない。","vi":"Lỡ như có thất bại thì tôi cũng không hối hận."},{"jp":"**万一**に備えて保険に入った。","vi":"Tôi đã mua bảo hiểm để phòng trường hợp xấu."}],
  "1151": [{"jp":"駅で**偶然**先生に会った。","vi":"Tôi tình cờ gặp thầy giáo ở nhà ga."},{"jp":"これは**偶然**の一致だ。","vi":"Đây là sự trùng hợp ngẫu nhiên."}],
  "1152": [{"jp":"**たまたま**隣の席が友達だった。","vi":"Tình cờ người ngồi ghế bên cạnh là bạn tôi."},{"jp":"**たまたま**通りかかった店に入った。","vi":"Tôi bước vào một cửa hàng tình cờ đi ngang qua."}],
  "1153": [{"jp":"**実際**に見ると、写真より大きい。","vi":"Nhìn tận mắt thì to hơn trong ảnh."},{"jp":"**実際**、彼の話は本当だった。","vi":"Thực tế thì câu chuyện của anh ấy là thật."}],
  "1154": [{"jp":"昨年と**同様**、今年も開催します。","vi":"Giống như năm ngoái, năm nay cũng sẽ tổ chức."},{"jp":"彼は家族**同様**に大切な友人だ。","vi":"Anh ấy là người bạn quý giá như người nhà."}],
  "1155": [{"jp":"彼は**元々**優しい人だ。","vi":"Anh ấy vốn dĩ là người hiền lành."},{"jp":"ここは**元々**畑だった。","vi":"Chỗ này ban đầu là ruộng."},{"jp":"だめで**元々**、やってみよう。","vi":"Không được cũng chẳng mất gì, cứ thử xem."}],
  "1156": [{"jp":"**本来**、この部屋は倉庫だった。","vi":"Căn phòng này vốn dĩ là nhà kho."},{"jp":"選手が**本来**の力を発揮した。","vi":"Cầu thủ đã phát huy được năng lực vốn có."}],
  "1157": [{"jp":"**ある**日、不思議な手紙が届いた。","vi":"Một ngày nọ, có một lá thư kỳ lạ được gửi đến."},{"jp":"**ある**人からこの話を聞いた。","vi":"Tôi nghe chuyện này từ một người nọ."}],
  "1158": [{"jp":"**あらゆる**方法を試してみた。","vi":"Tôi đã thử mọi cách."},{"jp":"この店には**あらゆる**商品がそろっている。","vi":"Cửa hàng này có đủ mọi loại hàng hóa."}],
  "1159": [{"jp":"**たいした**けがではないので、心配いりません。","vi":"Không phải vết thương gì nghiêm trọng nên đừng lo."},{"jp":"一人で全部やるなんて、**たいした**ものだ。","vi":"Làm hết một mình thì thật là giỏi."}],
  "1160": [{"jp":"彼は**いわゆる**天才だ。","vi":"Anh ấy là cái người ta gọi là thiên tài."},{"jp":"これが**いわゆる**「日本的経営」だ。","vi":"Đây chính là cái gọi là \"phong cách quản lý kiểu Nhật\"."}]
});
